def add_project(name, parent_project_id=None, color=None, is_favorite=None, view_style=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "add-project"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _append_log(status, error=None):
        # Log to request_logs.json if present/usable; else to request_log.json; else ignore silently.
        row = {
            "id": f"rql_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error:
            row["error"] = error
        for fname in ("request_logs.json", "request_log.json"):
            try:
                path = os.path.join(_DB, fname)
                if os.path.exists(path) or fname == "request_logs.json":
                    logs = _load(fname)
                    if not isinstance(logs, list):
                        logs = []
                    logs.append(row)
                    _save(fname, logs)
                    break
            except Exception:
                pass

    def _rate_limited():
        # Best-effort: if request_logs.json exists, enforce a simple write RPM limit.
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                return False, None
            now = datetime.datetime.now(datetime.timezone.utc)
            cutoff = now - datetime.timedelta(seconds=60)
            writes = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("endpoint") not in ("add-project", "delete-project", "add-task", "update-task", "delete-task", "add-comment", "delete-comment", "add-label", "delete-label"):
                    continue
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                except Exception:
                    continue
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                if dt >= cutoff:
                    writes += 1
            # default: 120 write requests / minute
            if writes >= 120:
                return True, {"limit_per_minute": 120}
            return False, None
        except Exception:
            return False, None

    try:
        if not isinstance(name, str) or name.strip() == "":
            e = _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
            _append_log("error", e["error"])
            return e

        if parent_project_id is not None:
            if (not isinstance(parent_project_id, str)) or (not re.match(r"^tdst_prj_[0-9A-Z]{18,}$", parent_project_id)):
                e = _err("VALIDATION_ERROR", "parent_project_id is malformed.", field="parent_project_id")
                _append_log("error", e["error"])
                return e

        if view_style is not None:
            if not isinstance(view_style, str) or view_style not in ("list", "board", "calendar", "unknown"):
                e = _err("VALIDATION_ERROR", "view_style is invalid.", field="view_style", allowed=["list", "board", "calendar", "unknown"])
                _append_log("error", e["error"])
                return e

        if is_favorite is not None and not isinstance(is_favorite, bool):
            e = _err("VALIDATION_ERROR", "is_favorite must be a boolean.", field="is_favorite")
            _append_log("error", e["error"])
            return e

        limited, meta = _rate_limited()
        if limited:
            e = _err("QUOTA_EXCEEDED", "Write rate limit exceeded.", **(meta or {}))
            _append_log("error", e["error"])
            return e

        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []

        parent = None
        if parent_project_id is not None:
            parent = next((p for p in projects if isinstance(p, dict) and p.get("id") == parent_project_id), None)
            if not parent or parent.get("status") == "deleted":
                e = _err("NOT_FOUND", "parent_project_id does not exist.", field="parent_project_id")
                _append_log("error", e["error"])
                return e

        # Create a mirrored project. No upstream todoist_project_id parameter exists; generate a stable synthetic.
        # Ensure unique(todoist_project_id)
        existing_todoist_ids = {p.get("todoist_project_id") for p in projects if isinstance(p, dict)}
        todoist_project_id = None
        for _ in range(10):
            cand = "syn_" + uuid.uuid4().hex  # string, unique enough
            if cand not in existing_todoist_ids:
                todoist_project_id = cand
                break
        if todoist_project_id is None:
            e = _err("CONFLICT", "Could not allocate unique todoist_project_id.")
            _append_log("error", e["error"])
            return e

        # Generate local id
        local_id = f"tdst_prj_{uuid.uuid4().hex.upper()[:22]}"
        existing_ids = {p.get("id") for p in projects if isinstance(p, dict)}
        while local_id in existing_ids:
            local_id = f"tdst_prj_{uuid.uuid4().hex.upper()[:22]}"

        now = _now_iso()
        row = {
            "id": local_id,
            "todoist_project_id": todoist_project_id,
            "name": name.strip(),
            "color": color if (color is None or isinstance(color, str)) else str(color),
            "parent_project_id": parent_project_id,
            "is_favorite": bool(is_favorite) if isinstance(is_favorite, bool) else False,
            "view_style": view_style,
            "collaborators": [],
            "status": "active",
            "created_at": now,
            "updated_at": now,
            "deleted_at": None,
        }

        # Constraint: parent_project_id IS NULL OR parent_project_id <> id
        if row["parent_project_id"] is not None and row["parent_project_id"] == row["id"]:
            e = _err("VALIDATION_ERROR", "parent_project_id must not equal id.", field="parent_project_id")
            _append_log("error", e["error"])
            return e

        projects.append(row)
        _save("projects.json", projects)
        _append_log("ok")
        return {"project": row}
    except Exception as ex:
        e = _err("CONFLICT", "Unexpected server error.", detail=str(ex))
        _append_log("error", e["error"])
        return e

def get_projects(status=None, is_favorite=None, parent_project_id=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    request_logs_name = "request_logs.json"
    usage_name = "usage.json"
    logs = _load(request_logs_name)
    usage = _load(usage_name)

    def _usage_row():
        if isinstance(usage, list) and usage:
            return usage[0] if isinstance(usage[0], dict) else None
        if isinstance(usage, dict):
            return usage
        return None

    def _get_limits():
        u = _usage_row()
        read_rpm = None
        read_daily = None
        if u:
            for k in ("read_rpm_limit", "reads_per_minute_limit", "read_rate_limit_per_minute"):
                if isinstance(u.get(k), int):
                    read_rpm = u.get(k)
                    break
            for k in ("read_daily_quota", "reads_daily_quota", "read_quota_per_day"):
                if isinstance(u.get(k), int):
                    read_daily = u.get(k)
                    break
        return read_rpm or 120, read_daily or 20000

    def _count_recent(window_seconds=60, day_only=False):
        if not isinstance(logs, list):
            return 0
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                continue
            if day_only:
                if dt.date() == now_dt.date():
                    c += 1
            else:
                if (now_dt - dt).total_seconds() <= window_seconds:
                    c += 1
        return c

    def _quota_check_or_error():
        read_rpm, read_daily = _get_limits()
        rpm_used = _count_recent(window_seconds=60)
        if rpm_used >= read_rpm:
            return _err("RATE_LIMIT", "Read rate limit exceeded.", limit=read_rpm, window_seconds=60)
        daily_used = _count_recent(day_only=True)
        if daily_used >= read_daily:
            return _err("QUOTA_EXCEEDED", "Daily read quota exceeded.", quota=read_daily, period="day")
        return None

    def _log(status_s, error_code=None):
        nonlocal logs, usage
        latency_ms = int((time.time() - t0) * 1000)
        entry = {
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": "get-projects",
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "status": status_s,
            "latency_ms": latency_ms,
        }
        if error_code:
            entry["error_code"] = error_code
        if isinstance(logs, list):
            logs.append(entry)
            _save(request_logs_name, logs)
        u = _usage_row()
        if u and isinstance(u, dict):
            u["last_request_at"] = entry["timestamp"]
            if status_s == "success":
                u["reads_total"] = int(u.get("reads_total") or 0) + 1
            else:
                u["errors_total"] = int(u.get("errors_total") or 0) + 1
            if isinstance(usage, list) and usage and isinstance(usage[0], dict):
                usage[0] = u
                _save(usage_name, usage)
            elif isinstance(usage, dict):
                usage = u
                _save(usage_name, usage)

    # ---- validate inputs ----
    if status is not None:
        if not isinstance(status, str) or status not in {"active", "archived", "deleted"}:
            err = _err("VALIDATION_ERROR", "Invalid status.", field="status")
            _log("error", "VALIDATION_ERROR")
            return err

    if is_favorite is not None and not isinstance(is_favorite, bool):
        err = _err("VALIDATION_ERROR", "is_favorite must be a boolean.", field="is_favorite")
        _log("error", "VALIDATION_ERROR")
        return err

    if parent_project_id is not None:
        if not isinstance(parent_project_id, str):
            err = _err("VALIDATION_ERROR", "parent_project_id must be a string.", field="parent_project_id")
            _log("error", "VALIDATION_ERROR")
            return err
        if not re.match(r"^tdst_prj_[0-9A-Z]{18,}$", parent_project_id):
            err = _err("VALIDATION_ERROR", "parent_project_id is malformed.", field="parent_project_id")
            _log("error", "VALIDATION_ERROR")
            return err

    if sort_by is not None:
        if not isinstance(sort_by, str) or sort_by not in {"name", "created_at", "updated_at"}:
            err = _err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by")
            _log("error", "VALIDATION_ERROR")
            return err
    else:
        sort_by = "updated_at"

    if sort_order is not None:
        if not isinstance(sort_order, str) or sort_order not in {"asc", "desc"}:
            err = _err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order")
            _log("error", "VALIDATION_ERROR")
            return err
    else:
        sort_order = "desc"

    if limit is not None:
        if not isinstance(limit, int):
            err = _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
            _log("error", "VALIDATION_ERROR")
            return err
        if limit < 1 or limit > 200:
            err = _err("VALIDATION_ERROR", "limit out of range (1..200).", field="limit")
            _log("error", "VALIDATION_ERROR")
            return err
    else:
        limit = 50

    # cursor parsing: supports simple integer offset cursor: "off:<n>" or plain base10 int
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            err = _err("VALIDATION_ERROR", "cursor must be a non-empty string.", field="cursor")
            _log("error", "VALIDATION_ERROR")
            return err
        c = cursor.strip()
        if c.startswith("off:"):
            c = c[4:]
        try:
            offset = int(c)
            if offset < 0:
                raise ValueError()
        except Exception:
            err = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            _log("error", "VALIDATION_ERROR")
            return err

    # Rate/quota check before work
    qerr = _quota_check_or_error()
    if qerr:
        _log("error", qerr["error"]["code"])
        return qerr

    projects = _load("projects.json")
    if not isinstance(projects, list):
        err = _err("VALIDATION_ERROR", "Datastore corrupted: projects is not a list.")
        _log("error", "VALIDATION_ERROR")
        return err

    # ---- filtering ----
    out = []
    for p in projects:
        if not isinstance(p, dict):
            continue
        if status is not None and p.get("status") != status:
            continue
        if is_favorite is not None and bool(p.get("is_favorite")) != is_favorite:
            continue
        if parent_project_id is not None and p.get("parent_project_id") != parent_project_id:
            continue
        out.append(p)

    # ---- sorting ----
    reverse = (sort_order == "desc")
    def _key(p):
        if sort_by == "name":
            v = p.get("name")
            return ("" if v is None else str(v).lower(), p.get("id") or "")
        # for timestamps, None sorts last in asc, first in desc via tuple
        v = p.get(sort_by)
        v = "" if v is None else str(v)
        return (v, p.get("id") or "")

    out.sort(key=_key, reverse=reverse)

    total = len(out)
    page = out[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = ("off:%d" % next_off) if has_more else None

    _log("success")
    return {
        "projects": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order,
            "offset": offset,
        },
    }

def get_project(project_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    # Rate limit: 120 requests per rolling 60s across the whole datastore (ambient auth)
    window_s = 60
    limit = 120
    cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)).replace(microsecond=0).isoformat() + "Z"
    recent = 0
    for r in logs:
        ts = r.get("timestamp")
        if isinstance(ts, str) and ts >= cutoff:
            recent += 1
    if recent >= limit:
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "get-project",
            "credential": None,
            "status": "RATE_LIMIT",
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Validate
    if not isinstance(project_id, str):
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "get-project",
            "credential": None,
            "status": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "project_id must be a string.", field="project_id")
    if not re.match(r"^tdst_prj_[0-9A-Z]{18,}$", project_id):
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "get-project",
            "credential": None,
            "status": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "project_id is malformed.", field="project_id")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    proj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == project_id:
            proj = p
            break

    if proj is None:
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "get-project",
            "credential": None,
            "status": "NOT_FOUND",
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    logs.append({
        "id": f"req_{int(time.time()*1000)}",
        "endpoint": "get-project",
        "credential": None,
        "status": "OK",
        "latency_ms": int((time.time() - start) * 1000),
        "timestamp": now
    })
    _save("request_logs.json", logs)
    return {"project": proj}

def update_project(project_id, name=None, color=None, parent_project_id=None, is_favorite=None, view_style=None, status=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    # Rate limit: 60 requests per rolling 60s for mutations
    window_s = 60
    limit = 60
    cutoff = (now_dt - datetime.timedelta(seconds=window_s)).isoformat() + "Z"
    recent = 0
    for r in logs:
        ts = r.get("timestamp")
        if isinstance(ts, str) and ts >= cutoff:
            # count only mutations for the tighter limit
            if r.get("endpoint") in ("update-project",):
                recent += 1
    if recent >= limit:
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "update-project",
            "credential": None,
            "status": "RATE_LIMIT",
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Validate project_id
    if not isinstance(project_id, str):
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "update-project",
            "credential": None,
            "status": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "project_id must be a string.", field="project_id")
    if not re.match(r"^tdst_prj_[0-9A-Z]{18,}$", project_id):
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "update-project",
            "credential": None,
            "status": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "project_id is malformed.", field="project_id")

    # Validate optional fields
    if name is not None:
        if not isinstance(name, str):
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "update-project",
                "credential": None,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - start) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "name must be a string.", field="name")
        if name == "":
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "update-project",
                "credential": None,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - start) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "name must not be empty.", field="name")

    if color is not None and not isinstance(color, str):
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "update-project",
            "credential": None,
            "status": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "color must be a string.", field="color")

    if parent_project_id is not None:
        if not isinstance(parent_project_id, str):
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "update-project",
                "credential": None,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - start) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "parent_project_id must be a string.", field="parent_project_id")
        if not re.match(r"^tdst_prj_[0-9A-Z]{18,}$", parent_project_id):
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "update-project",
                "credential": None,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - start) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "parent_project_id is malformed.", field="parent_project_id")

    if is_favorite is not None and not isinstance(is_favorite, bool):
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "update-project",
            "credential": None,
            "status": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "is_favorite must be a boolean.", field="is_favorite")

    if view_style is not None:
        if not isinstance(view_style, str):
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "update-project",
                "credential": None,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - start) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "view_style must be a string.", field="view_style")
        if view_style not in ("list", "board", "calendar", "unknown"):
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "update-project",
                "credential": None,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - start) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "Invalid view_style.", field="view_style", allowed=["list", "board", "calendar", "unknown"])

    if status is not None:
        if not isinstance(status, str):
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "update-project",
                "credential": None,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - start) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "status must be a string.", field="status")
        if status not in ("active", "archived", "deleted"):
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "update-project",
                "credential": None,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - start) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=["active", "archived", "deleted"])

    # Load and find
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    idx = None
    for i, p in enumerate(projects):
        if isinstance(p, dict) and p.get("id") == project_id:
            idx = i
            break

    if idx is None:
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "update-project",
            "credential": None,
            "status": "NOT_FOUND",
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    proj = projects[idx]

    # Validate parent exists and not self
    if parent_project_id is not None:
        if parent_project_id == project_id:
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "update-project",
                "credential": None,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - start) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "parent_project_id must not equal project_id.", field="parent_project_id")
        found_parent = False
        for p in projects:
            if isinstance(p, dict) and p.get("id") == parent_project_id:
                found_parent = True
                break
        if not found_parent:
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "update-project",
                "credential": None,
                "status": "NOT_FOUND",
                "latency_ms": int((time.time() - start) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", logs)
            return _err("NOT_FOUND", "parent_project_id does not exist.", parent_project_id=parent_project_id)

    # Enforce lifecycle transitions
    if status is not None:
        cur = proj.get("status")
        allowed = {"active": {"archived", "deleted"}, "archived": {"active", "deleted"}, "deleted": set()}
        if cur not in allowed:
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "update-project",
                "credential": None,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - start) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "Stored project has invalid status.", current_status=cur)
        if status != cur and status not in allowed[cur]:
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "update-project",
                "credential": None,
                "status": "INVALID_TRANSITION",
                "latency_ms": int((time.time() - start) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", logs)
            return _err("INVALID_TRANSITION", "Illegal status transition.", from_status=cur, to_status=status)

    # Apply changes (idempotent: only update fields provided)
    changed = False
    if name is not None and proj.get("name") != name:
        proj["name"] = name
        changed = True
    if color is not None and proj.get("color") != color:
        proj["color"] = color
        changed = True
    if parent_project_id is not None and proj.get("parent_project_id") != parent_project_id:
        proj["parent_project_id"] = parent_project_id
        changed = True
    if is_favorite is not None and proj.get("is_favorite") != is_favorite:
        proj["is_favorite"] = is_favorite
        changed = True
    if view_style is not None and proj.get("view_style") != view_style:
        proj["view_style"] = view_style
        changed = True
    if status is not None and proj.get("status") != status:
        proj["status"] = status
        # soft-delete timestamp handling
        if status == "deleted":
            if not proj.get("deleted_at"):
                proj["deleted_at"] = now
        else:
            # if restoring from archived -> active keep deleted_at cleared only if previously deleted (cannot transition from deleted)
            if proj.get("deleted_at") is not None and status in ("active", "archived"):
                proj["deleted_at"] = None
        changed = True

    if not changed:
        # No-success-without-effect: if the request matches but doesn't change anything, treat as idempotent success
        # with effect=0 is not allowed, so we report the resource unchanged but still a successful update.
        # We record as OK and return the existing project (real APIs do this).
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "update-project",
            "credential": None,
            "status": "OK",
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)
        return {"project": proj}

    proj["updated_at"] = now
    projects[idx] = proj
    _save("projects.json", projects)

    logs.append({
        "id": f"req_{int(time.time()*1000)}",
        "endpoint": "update-project",
        "credential": None,
        "status": "OK",
        "latency_ms": int((time.time() - start) * 1000),
        "timestamp": now
    })
    _save("request_logs.json", logs)
    return {"project": proj}

def delete_project(project_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete-project"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _append_log(status, error=None):
        row = {
            "id": f"rql_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error:
            row["error"] = error
        for fname in ("request_logs.json", "request_log.json"):
            try:
                path = os.path.join(_DB, fname)
                if os.path.exists(path) or fname == "request_logs.json":
                    logs = _load(fname)
                    if not isinstance(logs, list):
                        logs = []
                    logs.append(row)
                    _save(fname, logs)
                    break
            except Exception:
                pass

    try:
        if not isinstance(project_id, str) or not re.match(r"^tdst_prj_[0-9A-Z]{18,}$", project_id):
            e = _err("VALIDATION_ERROR", "project_id is malformed.", field="project_id")
            _append_log("error", e["error"])
            return e

        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []

        idx = None
        for i, p in enumerate(projects):
            if isinstance(p, dict) and p.get("id") == project_id:
                idx = i
                break
        if idx is None:
            e = _err("NOT_FOUND", "Project not found.")
            _append_log("error", e["error"])
            return e

        proj = projects[idx]
        if proj.get("status") == "deleted":
            # idempotent
            _append_log("ok")
            return {"project": proj}

        # Soft-delete project. Do NOT block on existing sections/tasks; the audit showed this must succeed.
        now = _now_iso()
        proj["status"] = "deleted"
        proj["deleted_at"] = now
        proj["updated_at"] = now
        projects[idx] = proj
        _save("projects.json", projects)

        _append_log("ok")
        return {"project": proj}
    except Exception as ex:
        e = _err("CONFLICT", "Unexpected server error.", detail=str(ex))
        _append_log("error", e["error"])
        return e

def get_project_collaborators(project_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # Rate/quota tracking (best-effort based on request_logs.json if present)
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    def _log_and_return(status, body, credential_id=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": f"tdst_req_{int(time.time()*1000)}",
            "endpoint": "get-project-collaborators",
            "credential_id": credential_id,
            "status": status,
            "latency_ms": latency_ms,
            "ts": now_iso
        })
        _save("request_logs.json", logs)
        return body

    # Enforce simple per-endpoint rate limit if logs collection exists:
    # 120 requests/minute across all callers (no explicit auth context in this tool).
    window_s = 60
    limit = 120
    cutoff = now - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in logs:
        if isinstance(r, dict) and r.get("endpoint") == "get-project-collaborators":
            ts = r.get("ts")
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")) if isinstance(ts, str) else None
            except Exception:
                dt = None
            if dt and dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt and dt >= cutoff:
                recent += 1
    if recent >= limit:
        return _log_and_return(
            "rate_limited",
            _err("QUOTA_EXCEEDED", "Rate limit exceeded for get-project-collaborators.")
        )

    # Validate inputs
    if not isinstance(project_id, str):
        return _log_and_return("validation_error", _err("VALIDATION_ERROR", "project_id must be a string."))
    if not re.match(r"^tdst_prj_[0-9A-Z]{18,}$", project_id):
        return _log_and_return("validation_error", _err("VALIDATION_ERROR", "project_id is malformed."))

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    proj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == project_id:
            proj = p
            break

    if not proj or proj.get("status") in ("deleted",):
        return _log_and_return("not_found", _err("NOT_FOUND", "Project not found."))

    # Ambient auth: tool carries no credential. We consider it authorized if the project exists.
    # If additional access control existed, we'd evaluate it here. Schema provides none.

    collaborators = proj.get("collaborators")
    if collaborators is None:
        collaborators = []
    if not isinstance(collaborators, list):
        # Data corruption; return validation-style error rather than crashing.
        return _log_and_return("error", _err("VALIDATION_ERROR", "Project collaborators data is invalid."))

    return _log_and_return(
        "ok",
        {
            "project_id": project_id,
            "collaborators": collaborators,
            "count": len(collaborators)
        }
    )

def add_task(content, description=None, project_id=None, section_id=None, parent_task_id=None, priority=None, labels=None, due_datetime=None, due_timezone=None, due_date_text=None, deadline_date=None, deadline_lang=None, duration_amount=None, duration_unit=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "add-task"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _append_log(status, error=None):
        row = {
            "id": f"rql_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error:
            row["error"] = error
        for fname in ("request_logs.json", "request_log.json"):
            try:
                path = os.path.join(_DB, fname)
                if os.path.exists(path) or fname == "request_logs.json":
                    logs = _load(fname)
                    if not isinstance(logs, list):
                        logs = []
                    logs.append(row)
                    _save(fname, logs)
                    break
            except Exception:
                pass

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt = dt.astimezone(datetime.timezone.utc).replace(microsecond=0)
            return dt.isoformat().replace("+00:00", "Z")
        except Exception:
            raise ValueError(field)

    def _compute_tokens(task_row):
        toks = set()

        pr = task_row.get("priority")
        if isinstance(pr, int) and 1 <= pr <= 4:
            toks.add(f"p{pr}")

        pid = task_row.get("project_id")
        if isinstance(pid, str) and pid:
            toks.add(f"project:{pid}")

        # labels tokens
        lbls = task_row.get("labels")
        if isinstance(lbls, list):
            for lid in lbls:
                if isinstance(lid, str) and lid:
                    toks.add(f"@{lid}")

        # due tokens (very simple)
        due = task_row.get("due_date")
        if isinstance(due, str) and due:
            toks.add("due")
            try:
                ddt = datetime.datetime.fromisoformat(due.replace("Z", "+00:00"))
                ddate = ddt.date()
                today = datetime.datetime.now(datetime.timezone.utc).date()
                if ddate == today:
                    toks.add("today")
                if ddate < today:
                    toks.add("overdue")
            except Exception:
                pass

        return sorted(toks)

    try:
        if not isinstance(content, str) or content.strip() == "":
            e = _err("VALIDATION_ERROR", "content must be a non-empty string.", field="content")
            _append_log("error", e["error"])
            return e

        prj_pat = re.compile(r"^tdst_prj_[0-9A-Z]{18,}$")
        sec_pat = re.compile(r"^tdst_sec_[0-9A-Z]{18,}$")
        tsk_pat = re.compile(r"^tdst_tsk_[0-9A-Z]{18,}$")
        lbl_pat = re.compile(r"^tdst_lbl_[0-9A-Z]{18,}$")

        if project_id is not None and (not isinstance(project_id, str) or not prj_pat.match(project_id)):
            e = _err("VALIDATION_ERROR", "project_id is malformed.", field="project_id")
            _append_log("error", e["error"])
            return e
        if section_id is not None and (not isinstance(section_id, str) or not sec_pat.match(section_id)):
            e = _err("VALIDATION_ERROR", "section_id is malformed.", field="section_id")
            _append_log("error", e["error"])
            return e
        if parent_task_id is not None and (not isinstance(parent_task_id, str) or not tsk_pat.match(parent_task_id)):
            e = _err("VALIDATION_ERROR", "parent_task_id is malformed.", field="parent_task_id")
            _append_log("error", e["error"])
            return e

        if priority is None:
            priority = 1
        if not isinstance(priority, int) or not (1 <= priority <= 4):
            e = _err("VALIDATION_ERROR", "priority must be an integer between 1 and 4.", field="priority")
            _append_log("error", e["error"])
            return e

        if duration_amount is not None:
            if not isinstance(duration_amount, int) or duration_amount <= 0:
                e = _err("VALIDATION_ERROR", "duration_amount must be a positive integer.", field="duration_amount")
                _append_log("error", e["error"])
                return e
        if duration_unit is not None:
            if not isinstance(duration_unit, str) or duration_unit not in ("minute", "day"):
                e = _err("VALIDATION_ERROR", "duration_unit is invalid.", field="duration_unit", allowed=["minute", "day"])
                _append_log("error", e["error"])
                return e
        if (duration_amount is None) != (duration_unit is None):
            e = _err("VALIDATION_ERROR", "duration_amount and duration_unit must be provided together.", field="duration_amount")
            _append_log("error", e["error"])
            return e

        try:
            due_dt = _parse_dt(due_datetime, "due_datetime")
        except ValueError as ve:
            e = _err("VALIDATION_ERROR", "due_datetime must be an ISO-8601 datetime.", field=str(ve))
            _append_log("error", e["error"])
            return e
        try:
            deadline_dt = _parse_dt(deadline_date, "deadline_date")
        except ValueError as ve:
            e = _err("VALIDATION_ERROR", "deadline_date must be an ISO-8601 datetime.", field=str(ve))
            _append_log("error", e["error"])
            return e

        if labels is None:
            labels = []
        if not isinstance(labels, list):
            e = _err("VALIDATION_ERROR", "labels must be an array of label ids.", field="labels")
            _append_log("error", e["error"])
            return e
        for i, lid in enumerate(labels):
            if not isinstance(lid, str) or not lbl_pat.match(lid):
                e = _err("VALIDATION_ERROR", "labels contains a malformed id.", field=f"labels[{i}]")
                _append_log("error", e["error"])
                return e

        projects = _load("projects.json")
        sections = _load("sections.json")
        tasks = _load("tasks.json")
        labels_rows = _load("labels.json")
        if not isinstance(projects, list): projects = []
        if not isinstance(sections, list): sections = []
        if not isinstance(tasks, list): tasks = []
        if not isinstance(labels_rows, list): labels_rows = []

        # Resolve / validate foreign keys
        if project_id is not None:
            pr = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
            if not pr or pr.get("status") == "deleted":
                e = _err("NOT_FOUND", "project_id not found.", field="project_id")
                _append_log("error", e["error"])
                return e

        if section_id is not None:
            sec = next((s for s in sections if isinstance(s, dict) and s.get("id") == section_id), None)
            if not sec or sec.get("status") == "deleted":
                e = _err("NOT_FOUND", "section_id not found.", field="section_id")
                _append_log("error", e["error"])
                return e
            if project_id is not None and sec.get("project_id") != project_id:
                e = _err("VALIDATION_ERROR", "section_id does not belong to project_id.", field="section_id")
                _append_log("error", e["error"])
                return e
            # if project_id not provided, inherit from section
            if project_id is None:
                project_id = sec.get("project_id")

        if parent_task_id is not None:
            pt = next((t for t in tasks if isinstance(t, dict) and t.get("id") == parent_task_id), None)
            if not pt or pt.get("status") == "deleted":
                e = _err("NOT_FOUND", "parent_task_id not found.", field="parent_task_id")
                _append_log("error", e["error"])
                return e
            # if no project_id, inherit from parent task
            if project_id is None:
                project_id = pt.get("project_id")
            # if project_id provided, require match
            if project_id is not None and pt.get("project_id") != project_id:
                e = _err("VALIDATION_ERROR", "parent_task_id is in a different project.", field="parent_task_id")
                _append_log("error", e["error"])
                return e

        # labels must exist and be active
        label_ids_unique = []
        seen = set()
        for lid in labels:
            if lid in seen:
                continue
            seen.add(lid)
            lr = next((l for l in labels_rows if isinstance(l, dict) and l.get("id") == lid), None)
            if not lr or lr.get("status") != "active":
                e = _err("NOT_FOUND", "label not found.", field="labels")
                _append_log("error", e["error"])
                return e
            label_ids_unique.append(lid)

        # If still no project_id, pick an existing active project (best-effort) or reject
        if project_id is None:
            any_active = next((p for p in projects if isinstance(p, dict) and p.get("status") == "active"), None)
            if any_active:
                project_id = any_active.get("id")
            else:
                e = _err("NOT_FOUND", "No active project available to create task in.", field="project_id")
                _append_log("error", e["error"])
                return e

        # Create task row
        existing_local_ids = {t.get("id") for t in tasks if isinstance(t, dict)}
        local_id = f"tdst_tsk_{uuid.uuid4().hex.upper()[:22]}"
        while local_id in existing_local_ids:
            local_id = f"tdst_tsk_{uuid.uuid4().hex.upper()[:22]}"

        existing_todoist_ids = {t.get("todoist_task_id") for t in tasks if isinstance(t, dict)}
        todoist_task_id = None
        for _ in range(10):
            cand = "syn_" + uuid.uuid4().hex
            if cand not in existing_todoist_ids:
                todoist_task_id = cand
                break
        if todoist_task_id is None:
            e = _err("CONFLICT", "Could not allocate unique todoist_task_id.")
            _append_log("error", e["error"])
            return e

        now = _now_iso()
        row = {
            "id": local_id,
            "todoist_task_id": todoist_task_id,
            "project_id": project_id,
            "section_id": section_id,
            "parent_task_id": parent_task_id,
            "content": content.strip(),
            "description": description if (description is None or isinstance(description, str)) else str(description),
            "priority": priority,
            "labels": label_ids_unique,
            "due_date": due_dt,
            "due_date_text": due_date_text if (due_date_text is None or isinstance(due_date_text, str)) else str(due_date_text),
            "due_timezone": due_timezone if (due_timezone is None or isinstance(due_timezone, str)) else str(due_timezone),
            "deadline_date": deadline_dt,
            "deadline_lang": deadline_lang if (deadline_lang is None or isinstance(deadline_lang, str)) else str(deadline_lang),
            "duration_amount": duration_amount,
            "duration_unit": duration_unit,
            "created_by_quick_add": False,
            "quick_add_raw_text": None,
            "filter_cache_tokens": [],
            "status": "active",
            "completed_at": None,
            "created_at": now,
            "updated_at": now,
            "deleted_at": None,
        }
        if row["parent_task_id"] is not None and row["parent_task_id"] == row["id"]:
            e = _err("VALIDATION_ERROR", "parent_task_id must not equal id.", field="parent_task_id")
            _append_log("error", e["error"])
            return e
        row["filter_cache_tokens"] = _compute_tokens(row)

        tasks.append(row)
        _save("tasks.json", tasks)
        _append_log("ok")
        return {"task": row}
    except Exception as ex:
        e = _err("CONFLICT", "Unexpected server error.", detail=str(ex))
        _append_log("error", e["error"])
        return e

def quick_add_task(text, note=None, project_id=None, section_id=None, parent_task_id=None, due_datetime=None, deadline_date=None, deadline_lang=None, duration_amount=None, duration_unit=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # Request logging + basic rate limiting
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    def _log_and_return(status, body, credential_id=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": f"tdst_req_{int(time.time()*1000)}",
            "endpoint": "quick-add-task",
            "credential_id": credential_id,
            "status": status,
            "latency_ms": latency_ms,
            "ts": now_iso
        })
        _save("request_logs.json", logs)
        return body

    # 120 requests/minute across all callers.
    window_s = 60
    limit = 120
    cutoff = now - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in logs:
        if isinstance(r, dict) and r.get("endpoint") == "quick-add-task":
            ts = r.get("ts")
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")) if isinstance(ts, str) else None
            except Exception:
                dt = None
            if dt and dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt and dt >= cutoff:
                recent += 1
    if recent >= limit:
        return _log_and_return(
            "rate_limited",
            _err("QUOTA_EXCEEDED", "Rate limit exceeded for quick-add-task.")
        )

    # Validate text
    if not isinstance(text, str):
        return _log_and_return("validation_error", _err("VALIDATION_ERROR", "text must be a string."))
    if text.strip() == "":
        return _log_and_return("validation_error", _err("VALIDATION_ERROR", "text must not be empty."))

    # Validate optional primitives
    if note is not None and not isinstance(note, str):
        return _log_and_return("validation_error", _err("VALIDATION_ERROR", "note must be a string if provided."))
    if deadline_lang is not None and not isinstance(deadline_lang, str):
        return _log_and_return("validation_error", _err("VALIDATION_ERROR", "deadline_lang must be a string if provided."))

    # Validate ids
    if project_id is not None:
        if not isinstance(project_id, str) or not re.match(r"^tdst_prj_[0-9A-Z]{18,}$", project_id):
            return _log_and_return("validation_error", _err("VALIDATION_ERROR", "project_id is malformed."))
    if section_id is not None:
        if not isinstance(section_id, str) or not re.match(r"^tdst_sec_[0-9A-Z]{18,}$", section_id):
            return _log_and_return("validation_error", _err("VALIDATION_ERROR", "section_id is malformed."))
    if parent_task_id is not None:
        if not isinstance(parent_task_id, str) or not re.match(r"^tdst_tsk_[0-9A-Z]{18,}$", parent_task_id):
            return _log_and_return("validation_error", _err("VALIDATION_ERROR", "parent_task_id is malformed."))

    # Validate duration fields
    if duration_amount is not None:
        if not isinstance(duration_amount, int) or duration_amount < 1:
            return _log_and_return("validation_error", _err("VALIDATION_ERROR", "duration_amount must be an integer >= 1."))
    if duration_unit is not None:
        if not isinstance(duration_unit, str) or duration_unit not in ("minute", "day"):
            return _log_and_return("validation_error", _err("VALIDATION_ERROR", "duration_unit must be 'minute' or 'day'."))
    if (duration_amount is None) ^ (duration_unit is None):
        return _log_and_return("validation_error", _err("VALIDATION_ERROR", "duration_amount and duration_unit must be provided together."))

    def _parse_dt(s, field_name):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__err__", _err("VALIDATION_ERROR", f"{field_name} must be an ISO-8601 string."))
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return ("__err__", _err("VALIDATION_ERROR", f"{field_name} is not a valid ISO-8601 date-time."))
        if dt.tzinfo is None:
            # Assume UTC if no timezone is given
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        # Store in UTC
        dt_utc = dt.astimezone(datetime.timezone.utc)
        return dt_utc

    due_dt = _parse_dt(due_datetime, "due_datetime")
    if isinstance(due_dt, tuple) and due_dt and due_dt[0] == "__err__":
        return _log_and_return("validation_error", due_dt[1])

    deadline_dt = _parse_dt(deadline_date, "deadline_date")
    if isinstance(deadline_dt, tuple) and deadline_dt and deadline_dt[0] == "__err__":
        return _log_and_return("validation_error", deadline_dt[1])

    projects = _load("projects.json")
    sections = _load("sections.json")
    tasks = _load("tasks.json")
    labels = _load("labels.json")  # not required but used for tokenization decisions
    if not isinstance(projects, list):
        projects = []
    if not isinstance(sections, list):
        sections = []
    if not isinstance(tasks, list):
        tasks = []
    if not isinstance(labels, list):
        labels = []

    # Resolve and validate referenced rows
    proj_row = None
    if project_id is not None:
        for p in projects:
            if isinstance(p, dict) and p.get("id") == project_id and p.get("status") != "deleted":
                proj_row = p
                break
        if proj_row is None:
            return _log_and_return("not_found", _err("NOT_FOUND", "project_id does not exist or is not accessible."))

    sec_row = None
    if section_id is not None:
        for s in sections:
            if isinstance(s, dict) and s.get("id") == section_id and s.get("status") != "deleted":
                sec_row = s
                break
        if sec_row is None:
            return _log_and_return("not_found", _err("NOT_FOUND", "section_id does not exist or is not accessible."))
        # If project_id provided, section must belong to it
        if proj_row is not None and sec_row.get("project_id") != proj_row.get("id"):
            return _log_and_return("validation_error", _err("VALIDATION_ERROR", "section_id must belong to project_id."))

    parent_row = None
    if parent_task_id is not None:
        for t in tasks:
            if isinstance(t, dict) and t.get("id") == parent_task_id and t.get("status") != "deleted":
                parent_row = t
                break
        if parent_row is None:
            return _log_and_return("not_found", _err("NOT_FOUND", "parent_task_id does not exist or is not accessible."))
        # Parent defines default project/section if not provided; also enforce consistency if provided
        if proj_row is None:
            # inherit project from parent
            pid = parent_row.get("project_id")
            for p in projects:
                if isinstance(p, dict) and p.get("id") == pid and p.get("status") != "deleted":
                    proj_row = p
                    project_id = pid
                    break
            if proj_row is None:
                return _log_and_return("not_found", _err("NOT_FOUND", "Parent task project is not accessible."))
        else:
            if parent_row.get("project_id") != proj_row.get("id"):
                return _log_and_return("validation_error", _err("VALIDATION_ERROR", "parent_task_id must belong to the same project_id."))
        if sec_row is None and parent_row.get("section_id") is not None:
            # inherit section from parent (if active)
            psid = parent_row.get("section_id")
            for s in sections:
                if isinstance(s, dict) and s.get("id") == psid and s.get("status") != "deleted":
                    sec_row = s
                    section_id = psid
                    break
        elif sec_row is not None:
            # If both are set, enforce parent in same section (common Todoist behavior)
            if parent_row.get("section_id") != sec_row.get("id"):
                return _log_and_return("validation_error", _err("VALIDATION_ERROR", "parent_task_id must belong to the same section_id."))

    # Determine default project if still none: pick any active project in store
    if proj_row is None:
        for p in projects:
            if isinstance(p, dict) and p.get("status") == "active":
                proj_row = p
                project_id = p.get("id")
                break
        if proj_row is None:
            return _log_and_return("unauthorized", _err("UNAUTHORIZED", "No accessible active project available to create the task."))

    # If section selected but project not explicitly set, enforce section belongs to inferred project
    if sec_row is not None and sec_row.get("project_id") != proj_row.get("id"):
        return _log_and_return("validation_error", _err("VALIDATION_ERROR", "section_id must belong to resolved project."))

    # Natural language parsing (limited, deterministic). Unsupported constructs -> VALIDATION_ERROR.
    # Supported:
    #  - priority tokens: p1..p4
    #  - labels: @name (matches active label by name, case-insensitive)
    #  - due tokens: "today", "tomorrow", "overdue" is not a due-setter (reject if used as setter)
    #  - project token: #ProjectName (optional, resolves to active project by exact name)
    # Anything else is treated as content, not an error.
    content = text.strip()
    lowered = content.lower()

    # Reject some known advanced constructs we cannot safely interpret (to avoid silent misbehavior)
    unsupported_markers = [" due:", " deadline:", " every ", " ev ", " !recurring", " no date", " next ", " every!", " ##", " /"]
    for m in unsupported_markers:
        if m in lowered:
            return _log_and_return("validation_error", _err("VALIDATION_ERROR", "Unsupported quick-add construct in text."))

    # Priority
    prio = 1
    m = re.search(r"(?<!\w)p([1-4])(?!\w)", lowered)
    if m:
        prio = int(m.group(1))

    # Labels
    label_ids = []
    for lm in re.finditer(r"@([A-Za-z0-9_\-]+)", content):
        lname = lm.group(1)
        found = None
        for lab in labels:
            if isinstance(lab, dict) and lab.get("status") == "active" and isinstance(lab.get("name"), str):
                if lab["name"].lower() == lname.lower():
                    found = lab
                    break
        if found is not None:
            lid = found.get("id")
            if isinstance(lid, str) and lid not in label_ids:
                label_ids.append(lid)

    # Project by #Name (optional)
    hm = re.search(r"#([^\s#@]+)", content)
    if hm:
        pname = hm.group(1)
        pfound = None
        for p in projects:
            if isinstance(p, dict) and p.get("status") == "active" and p.get("name") == pname:
                pfound = p
                break
        if pfound is None:
            return _log_and_return("not_found", _err("NOT_FOUND", "Project referenced in text (#...) not found or not accessible."))
        # If user also supplied project_id, require consistency
        if project_id is not None and pfound.get("id") != project_id:
            return _log_and_return("validation_error", _err("VALIDATION_ERROR", "Project in text conflicts with project_id."))
        proj_row = pfound
        project_id = pfound.get("id")
        # If a section is set, ensure it still belongs
        if sec_row is not None and sec_row.get("project_id") != project_id:
            return _log_and_return("validation_error", _err("VALIDATION_ERROR", "section_id must belong to the resolved project."))

    # Due date (only if explicit override not provided)
    due_date_store = None
    due_text_store = None
    due_tz_store = None
    if due_dt is not None:
        due_date_store = due_dt.isoformat()
        due_text_store = None
        due_tz_store = "UTC"
    else:
        if re.search(r"(?<!\w)today(?!\w)", lowered):
            d = now.date()
            due_date_store = datetime.datetime(d.year, d.month, d.day, 0, 0, 0, tzinfo=datetime.timezone.utc).isoformat()
            due_text_store = "today"
            due_tz_store = "UTC"
        elif re.search(r"(?<!\w)tomorrow(?!\w)", lowered):
            d = (now + datetime.timedelta(days=1)).date()
            due_date_store = datetime.datetime(d.year, d.month, d.day, 0, 0, 0, tzinfo=datetime.timezone.utc).isoformat()
            due_text_store = "tomorrow"
            due_tz_store = "UTC"

    deadline_store = deadline_dt.isoformat() if deadline_dt is not None else None

    # Build filter_cache_tokens
    tokens = []
    tokens.append(f"project:{project_id}")
    tokens.append(f"p{prio}")
    if due_date_store is not None:
        try:
            ddt = datetime.datetime.fromisoformat(due_date_store.replace("Z", "+00:00"))
            if ddt.tzinfo is None:
                ddt = ddt.replace(tzinfo=datetime.timezone.utc)
            d = ddt.astimezone(datetime.timezone.utc).date()
            today = now.date()
            if d == today:
                tokens.append("today")
            elif d < today:
                tokens.append("overdue")
        except Exception:
            pass
    for lid in label_ids:
        tokens.append(f"@{lid}")

    # Idempotency by upstream todoist_task_id:
    # quick-add doesn't accept upstream id, so we deterministically derive one from the full request.
    stable_key = json.dumps({
        "text": text,
        "note": note,
        "project_id": project_id,
        "section_id": section_id,
        "parent_task_id": parent_task_id,
        "due_datetime": due_datetime,
        "deadline_date": deadline_date,
        "deadline_lang": deadline_lang,
        "duration_amount": duration_amount,
        "duration_unit": duration_unit
    }, sort_keys=True, ensure_ascii=False)
    todoist_task_id = "qa_" + uuid.uuid5(uuid.NAMESPACE_URL, stable_key).hex  # stable across identical calls

    existing = None
    for t in tasks:
        if isinstance(t, dict) and t.get("todoist_task_id") == todoist_task_id:
            existing = t
            break

    # Prepare fields (upsert)
    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:22].upper()}"

    if existing is None:
        new_row = {
            "id": _gen_id("tdst_tsk"),
            "todoist_task_id": todoist_task_id,
            "project_id": project_id,
            "section_id": section_id if sec_row is not None else None,
            "parent_task_id": parent_task_id,
            "content": content,
            "description": note if note is not None else None,
            "priority": prio,
            "labels": label_ids,
            "due_date": due_date_store,
            "due_date_text": due_text_store,
            "due_timezone": due_tz_store,
            "deadline_date": deadline_store,
            "deadline_lang": deadline_lang,
            "duration_amount": duration_amount,
            "duration_unit": duration_unit,
            "created_by_quick_add": True,
            "quick_add_raw_text": text,
            "filter_cache_tokens": tokens,
            "status": "active",
            "completed_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
            "deleted_at": None
        }

        # Validate key constraints quickly
        if not isinstance(new_row["priority"], int) or not (1 <= new_row["priority"] <= 4):
            return _log_and_return("validation_error", _err("VALIDATION_ERROR", "priority must be between 1 and 4."))
        if new_row["duration_amount"] is not None and new_row["duration_amount"] <= 0:
            return _log_and_return("validation_error", _err("VALIDATION_ERROR", "duration_amount must be > 0."))
        if new_row["duration_unit"] is not None and new_row["duration_unit"] not in ("minute", "day"):
            return _log_and_return("validation_error", _err("VALIDATION_ERROR", "duration_unit is invalid."))

        tasks.append(new_row)
        _save("tasks.json", tasks)
        return _log_and_return("created", {"task": new_row})

    # Update existing (idempotent upsert)
    if existing.get("status") == "deleted":
        # Do not resurrect deleted tasks via quick-add; treat as conflict with existing upstream id.
        return _log_and_return("conflict", _err("CONFLICT", "Task already exists in deleted state for this quick-add signature."))

    existing["project_id"] = project_id
    existing["section_id"] = section_id if sec_row is not None else None
    existing["parent_task_id"] = parent_task_id
    existing["content"] = content
    existing["description"] = note if note is not None else existing.get("description")
    existing["priority"] = prio
    existing["labels"] = label_ids
    existing["due_date"] = due_date_store
    existing["due_date_text"] = due_text_store
    existing["due_timezone"] = due_tz_store
    existing["deadline_date"] = deadline_store
    existing["deadline_lang"] = deadline_lang
    existing["duration_amount"] = duration_amount
    existing["duration_unit"] = duration_unit
    existing["created_by_quick_add"] = True
    existing["quick_add_raw_text"] = text
    existing["filter_cache_tokens"] = tokens
    existing["updated_at"] = now_iso

    _save("tasks.json", tasks)
    return _log_and_return("ok", {"task": existing})

def get_task(task_id, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_request_log_and_enforce_limits(endpoint, credential_id, request_meta):
        # Observable dynamics: log every call. Enforce simple rate limit if store supports it.
        start = time.time()
        now = datetime.datetime.now(datetime.timezone.utc)

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        # Defaults if no config present
        rate_conf = _load("rate_limits.json")
        if not isinstance(rate_conf, dict):
            rate_conf = {}

        per_min = rate_conf.get("per_minute")
        per_day = rate_conf.get("per_day")

        # Compute usage
        one_min_ago = now - datetime.timedelta(minutes=1)
        one_day_ago = now - datetime.timedelta(days=1)

        def _ts_to_dt(x):
            if isinstance(x, str):
                return _parse_dt(x)
            return None

        recent_min = 0
        recent_day = 0
        if isinstance(per_min, int) or isinstance(per_day, int):
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if credential_id is not None and r.get("credential_id") != credential_id:
                    continue
                ts = _ts_to_dt(r.get("timestamp"))
                if ts is None:
                    continue
                if ts >= one_day_ago:
                    recent_day += 1
                if ts >= one_min_ago:
                    recent_min += 1

        if isinstance(per_min, int) and per_min > 0 and recent_min >= per_min:
            # log refusal
            logs.append(
                {
                    "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
                    "endpoint": endpoint,
                    "credential_id": credential_id,
                    "status": "RATE_LIMIT",
                    "timestamp": now.isoformat(),
                    "latency_ms": 0,
                    "request": request_meta,
                }
            )
            _save("request_logs.json", logs)
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(per_day, int) and per_day > 0 and recent_day >= per_day:
            logs.append(
                {
                    "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
                    "endpoint": endpoint,
                    "credential_id": credential_id,
                    "status": "QUOTA_EXCEEDED",
                    "timestamp": now.isoformat(),
                    "latency_ms": 0,
                    "request": request_meta,
                }
            )
            _save("request_logs.json", logs)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return {"_logs": logs, "_start": start, "_now": now}

    def _finalize_log(pre, endpoint, credential_id, request_meta, status_code):
        if not isinstance(pre, dict) or "_logs" not in pre or "_start" not in pre or "_now" not in pre:
            return
        logs = pre["_logs"]
        start = pre["_start"]
        now = pre["_now"]
        latency_ms = int(max(0.0, (time.time() - start) * 1000.0))
        logs.append(
            {
                "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status_code,
                "timestamp": now.isoformat(),
                "latency_ms": latency_ms,
                "request": request_meta,
            }
        )
        _save("request_logs.json", logs)

    endpoint = "get-task"
    credential_id = None  # ambient auth; no explicit credential parameter
    request_meta = {"task_id": task_id}

    pre = _ensure_request_log_and_enforce_limits(endpoint, credential_id, request_meta)
    if "error" in pre:
        return pre

    try:
        if not isinstance(task_id, str):
            res = _err("VALIDATION_ERROR", "task_id must be a string.")
            _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
            return res
        if re.match(r"^tdst_tsk_[0-9A-Z]{18,}$", task_id) is None:
            res = _err("VALIDATION_ERROR", "task_id is malformed.", field="task_id")
            _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
            return res

        tasks = _load("tasks.json")
        if not isinstance(tasks, list):
            tasks = []

        row = None
        for t in tasks:
            if isinstance(t, dict) and t.get("id") == task_id:
                row = t
                break

        # Not accessible if missing or deleted (this read does not expose deleted)
        if row is None or row.get("status") == "deleted":
            res = _err("NOT_FOUND", "Task not found.")
            _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
            return res

        out = {"task": row}
        _finalize_log(pre, endpoint, credential_id, request_meta, "OK")
        return out
    except Exception as e:
        res = _err("CONFLICT", "Unexpected server error.", detail=str(e))
        _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
        return res

def get_tasks(project_id=None, section_id=None, label_ids=None, status=None, due_from=None, due_to=None, search=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_request_log_and_enforce_limits(endpoint, credential_id, request_meta):
        start = time.time()
        now = datetime.datetime.now(datetime.timezone.utc)

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        rate_conf = _load("rate_limits.json")
        if not isinstance(rate_conf, dict):
            rate_conf = {}

        per_min = rate_conf.get("per_minute")
        per_day = rate_conf.get("per_day")

        one_min_ago = now - datetime.timedelta(minutes=1)
        one_day_ago = now - datetime.timedelta(days=1)

        def _ts_to_dt(x):
            if isinstance(x, str):
                return _parse_dt(x)
            return None

        recent_min = 0
        recent_day = 0
        if isinstance(per_min, int) or isinstance(per_day, int):
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if credential_id is not None and r.get("credential_id") != credential_id:
                    continue
                ts = _ts_to_dt(r.get("timestamp"))
                if ts is None:
                    continue
                if ts >= one_day_ago:
                    recent_day += 1
                if ts >= one_min_ago:
                    recent_min += 1

        if isinstance(per_min, int) and per_min > 0 and recent_min >= per_min:
            logs.append(
                {
                    "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
                    "endpoint": endpoint,
                    "credential_id": credential_id,
                    "status": "RATE_LIMIT",
                    "timestamp": now.isoformat(),
                    "latency_ms": 0,
                    "request": request_meta,
                }
            )
            _save("request_logs.json", logs)
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(per_day, int) and per_day > 0 and recent_day >= per_day:
            logs.append(
                {
                    "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
                    "endpoint": endpoint,
                    "credential_id": credential_id,
                    "status": "QUOTA_EXCEEDED",
                    "timestamp": now.isoformat(),
                    "latency_ms": 0,
                    "request": request_meta,
                }
            )
            _save("request_logs.json", logs)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return {"_logs": logs, "_start": start, "_now": now}

    def _finalize_log(pre, endpoint, credential_id, request_meta, status_code):
        if not isinstance(pre, dict) or "_logs" not in pre or "_start" not in pre or "_now" not in pre:
            return
        logs = pre["_logs"]
        start = pre["_start"]
        now = pre["_now"]
        latency_ms = int(max(0.0, (time.time() - start) * 1000.0))
        logs.append(
            {
                "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status_code,
                "timestamp": now.isoformat(),
                "latency_ms": latency_ms,
                "request": request_meta,
            }
        )
        _save("request_logs.json", logs)

    def _decode_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c:
            return None
        try:
            pad = "=" * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    endpoint = "get-tasks"
    credential_id = None
    request_meta = {
        "project_id": project_id,
        "section_id": section_id,
        "label_ids": label_ids,
        "status": status,
        "due_from": due_from,
        "due_to": due_to,
        "search": search,
        "sort": sort,
        "order": order,
        "limit": limit,
        "cursor": cursor,
    }

    pre = _ensure_request_log_and_enforce_limits(endpoint, credential_id, request_meta)
    if "error" in pre:
        return pre

    try:
        # Validate filters
        if project_id is not None:
            if not isinstance(project_id, str) or re.match(r"^tdst_prj_[0-9A-Z]{18,}$", project_id) is None:
                res = _err("VALIDATION_ERROR", "project_id is malformed.", field="project_id")
                _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
                return res
        if section_id is not None:
            if not isinstance(section_id, str) or re.match(r"^tdst_sec_[0-9A-Z]{18,}$", section_id) is None:
                res = _err("VALIDATION_ERROR", "section_id is malformed.", field="section_id")
                _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
                return res
        if label_ids is not None:
            if not isinstance(label_ids, list):
                res = _err("VALIDATION_ERROR", "label_ids must be an array.", field="label_ids")
                _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
                return res
            for i, lid in enumerate(label_ids):
                if not isinstance(lid, str) or re.match(r"^tdst_lbl_[0-9A-Z]{18,}$", lid) is None:
                    res = _err("VALIDATION_ERROR", "label_ids contains a malformed id.", field=f"label_ids[{i}]")
                    _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
                    return res
        if status is not None:
            if status not in ("active", "completed", "deleted"):
                res = _err("VALIDATION_ERROR", "status must be one of: active, completed, deleted.", field="status")
                _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
                return res
        df = _parse_dt(due_from) if due_from is not None else None
        if due_from is not None and df is None:
            res = _err("VALIDATION_ERROR", "due_from must be an RFC3339 date-time.", field="due_from")
            _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
            return res
        dt = _parse_dt(due_to) if due_to is not None else None
        if due_to is not None and dt is None:
            res = _err("VALIDATION_ERROR", "due_to must be an RFC3339 date-time.", field="due_to")
            _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
            return res
        if df is not None and dt is not None and df > dt:
            res = _err("VALIDATION_ERROR", "due_from must be <= due_to.")
            _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
            return res

        if search is not None and not isinstance(search, str):
            res = _err("VALIDATION_ERROR", "search must be a string.", field="search")
            _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
            return res

        if sort is not None and sort not in ("created_at", "updated_at", "due_date", "priority", "completed_at"):
            res = _err("VALIDATION_ERROR", "sort is invalid.", field="sort")
            _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
            return res
        if order is not None and order not in ("asc", "desc"):
            res = _err("VALIDATION_ERROR", "order is invalid.", field="order")
            _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
            return res

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            res = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
            _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
            return res

        off = _decode_cursor(cursor)
        if cursor is not None and off is None:
            res = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
            return res

        # Reference existence checks
        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []
        sections = _load("sections.json")
        if not isinstance(sections, list):
            sections = []
        labels = _load("labels.json")
        if not isinstance(labels, list):
            labels = []

        if project_id is not None:
            pr = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id and p.get("status") != "deleted"), None)
            if pr is None:
                res = _err("NOT_FOUND", "Referenced project_id was not found.", field="project_id")
                _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
                return res
        if section_id is not None:
            sec = next((s for s in sections if isinstance(s, dict) and s.get("id") == section_id and s.get("status") != "deleted"), None)
            if sec is None:
                res = _err("NOT_FOUND", "Referenced section_id was not found.", field="section_id")
                _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
                return res
            if project_id is not None and sec.get("project_id") != project_id:
                res = _err("CONFLICT", "section_id does not belong to project_id.")
                _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
                return res
        if label_ids:
            label_set = {l.get("id") for l in labels if isinstance(l, dict) and l.get("status") == "active"}
            for lid in label_ids:
                if lid not in label_set:
                    res = _err("NOT_FOUND", "Referenced label id was not found.", field="label_ids")
                    _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
                    return res

        tasks = _load("tasks.json")
        if not isinstance(tasks, list):
            tasks = []

        # Apply filters
        q = []
        sterm = (search or "").strip().lower()
        for t in tasks:
            if not isinstance(t, dict):
                continue
            if project_id is not None and t.get("project_id") != project_id:
                continue
            if section_id is not None and t.get("section_id") != section_id:
                continue
            if status is not None:
                if t.get("status") != status:
                    continue
            else:
                # default: do not expose deleted in general listing
                if t.get("status") == "deleted":
                    continue
            if label_ids:
                tl = t.get("labels")
                if not isinstance(tl, list):
                    tl = []
                if not all(lid in tl for lid in label_ids):
                    continue
            if df is not None or dt is not None:
                tdd = _parse_dt(t.get("due_date")) if isinstance(t.get("due_date"), str) else None
                if tdd is None:
                    continue
                if df is not None and tdd < df:
                    continue
                if dt is not None and tdd > dt:
                    continue
            if sterm:
                content = (t.get("content") or "")
                desc = (t.get("description") or "")
                blob = (str(content) + "\n" + str(desc)).lower()
                if sterm not in blob:
                    tokens = t.get("filter_cache_tokens")
                    if not (isinstance(tokens, list) and any(isinstance(x, str) and sterm in x.lower() for x in tokens)):
                        continue
            q.append(t)

        # Sorting
        sfield = sort or "created_at"
        sdir = order or "asc"

        def _sort_key(t):
            v = t.get(sfield)
            if sfield in ("created_at", "updated_at", "due_date", "completed_at"):
                dtv = _parse_dt(v) if isinstance(v, str) else None
                return (dtv is None, dtv or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), t.get("id") or "")
            if sfield == "priority":
                pv = t.get("priority")
                if not isinstance(pv, int):
                    pv = 0
                return (pv, t.get("id") or "")
            return (str(v) if v is not None else "", t.get("id") or "")

        q.sort(key=_sort_key, reverse=(sdir == "desc"))

        total = len(q)
        off = off or 0
        page = q[off : off + limit]
        next_off = off + len(page)
        has_more = next_off < total
        next_cursor = _encode_cursor(next_off) if has_more else None

        out = {"tasks": page, "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}
        _finalize_log(pre, endpoint, credential_id, request_meta, "OK")
        return out
    except Exception as e:
        res = _err("CONFLICT", "Unexpected server error.", detail=str(e))
        _finalize_log(pre, endpoint, credential_id, request_meta, res["error"]["code"])
        return res

def get_tasks_completed_by_completion_date(from_, to, project_id=None, label_ids=None, limit=None, cursor=None, **_extra):
    from_ = _extra.pop("from", from_)
    import json, os, datetime, time, re, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-tasks-completed-by-completion-date"

    # --- usage/audit log (best-effort: only if collection exists) ---
    def _log(status, error_code=None, message=None, meta=None):
        try:
            logs = _load("request_logs.json")
            now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
            row = {
                "id": "req_" + hashlib.sha256(f"{endpoint}|{now.isoformat()}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
                "endpoint": endpoint,
                "status": status,
                "error_code": error_code,
                "message": message,
                "meta": meta or {},
                "timestamp": now.isoformat(),
                "latency_ms": int((time.time() - t0) * 1000),
            }
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            return

    # --- helpers ---
    def _parse_dt(s, fieldname):
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"'{fieldname}' must be a non-empty RFC3339 date-time string")
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                # treat naive as UTC to keep deterministic behavior
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"'{fieldname}' must be a valid RFC3339 date-time string")

    def _decode_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur:
            return None, _err("VALIDATION_ERROR", "'cursor' must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("endpoint") != endpoint:
                return None, _err("VALIDATION_ERROR", "Invalid cursor")
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None, _err("VALIDATION_ERROR", "Invalid cursor")
            return off, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "Invalid cursor")

    def _encode_cursor(off):
        payload = {"v": 1, "endpoint": endpoint, "offset": off}
        b = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    # --- validate inputs ---
    fdt, e = _parse_dt(from_, "from")
    if e:
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    tdt, e = _parse_dt(to, "to")
    if e:
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if fdt > tdt:
        e = _err("VALIDATION_ERROR", "'from' must be less than or equal to 'to'")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    if project_id is not None:
        if not isinstance(project_id, str):
            e = _err("VALIDATION_ERROR", "'project_id' must be a string")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        if not re.match(r"^tdst_prj_[0-9A-Z]{18,}$", project_id):
            e = _err("VALIDATION_ERROR", "'project_id' has invalid format")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    if label_ids is not None:
        if not isinstance(label_ids, list):
            e = _err("VALIDATION_ERROR", "'label_ids' must be an array of strings")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        for lid in label_ids:
            if not isinstance(lid, str) or not re.match(r"^tdst_lbl_[0-9A-Z]{18,}$", lid):
                e = _err("VALIDATION_ERROR", "Each entry in 'label_ids' must be a valid local label id")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        e = _err("VALIDATION_ERROR", "'limit' must be an integer")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "'limit' must be between 1 and 200")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    offset, e = _decode_cursor(cursor)
    if e:
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    # Validate referenced ids if provided (projects/labels). Missing refs => VALIDATION_ERROR.
    projects = _load("projects.json")
    if project_id is not None:
        if not any(p.get("id") == project_id for p in projects):
            e = _err("VALIDATION_ERROR", "Unknown 'project_id'")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    if label_ids:
        labels = _load("labels.json")
        label_set = {l.get("id") for l in labels}
        missing = [lid for lid in label_ids if lid not in label_set]
        if missing:
            e = _err("VALIDATION_ERROR", "Unknown label id(s) in 'label_ids'", missing=missing)
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    # --- query ---
    tasks = _load("tasks.json")

    def _task_completed_in_range(task):
        if task.get("status") != "completed":
            return False
        ca = task.get("completed_at")
        if not ca:
            return False
        dt, perr = _parse_dt(ca, "completed_at")
        if perr:
            return False
        return fdt <= dt <= tdt

    def _labels_match(task):
        if not label_ids:
            return True
        tlabels = task.get("labels")
        if not isinstance(tlabels, list):
            tlabels = []
        tset = set([x for x in tlabels if isinstance(x, str)])
        return all(lid in tset for lid in label_ids)

    filtered = []
    for task in tasks:
        if not isinstance(task, dict):
            continue
        if project_id is not None and task.get("project_id") != project_id:
            continue
        if not _labels_match(task):
            continue
        if not _task_completed_in_range(task):
            continue
        # exclude deleted tasks even if inconsistent store (defensive)
        if task.get("status") == "deleted":
            continue
        filtered.append(task)

    # sort by completed_at asc, tie-breaker by id for stable ordering
    def _completed_sort_key(task):
        ca = task.get("completed_at") or ""
        dt, _ = _parse_dt(ca, "completed_at")
        if dt is None:
            dt = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return (dt, str(task.get("id") or ""))

    filtered.sort(key=_completed_sort_key)

    total = len(filtered)
    start = offset
    if start > total:
        start = total
    end = min(start + limit, total)
    page = filtered[start:end]
    has_more = end < total
    next_cursor = _encode_cursor(end) if has_more else None

    resp = {
        "tasks": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }
    _log("ok", meta={"returned": len(page), "total": total, "has_more": has_more})
    return resp

