            return

    def _parse_dt(s, fieldname):
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"'{fieldname}' must be a non-empty RFC3339 date-time string")
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"'{fieldname}' must be a valid RFC3339 date-time string")

    def _decode_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur:
            return None, _err("VALIDATION_ERROR", "'cursor' must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("endpoint") != endpoint:
                return None, _err("VALIDATION_ERROR", "Invalid cursor")
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None, _err("VALIDATION_ERROR", "Invalid cursor")
            return off, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "Invalid cursor")

    def _encode_cursor(off):
        payload = {"v": 1, "endpoint": endpoint, "offset": off}
        b = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    # --- validate inputs ---
    fdt, e = _parse_dt(from_, "from")
    if e:
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    tdt, e = _parse_dt(to, "to")
    if e:
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if fdt > tdt:
        e = _err("VALIDATION_ERROR", "'from' must be less than or equal to 'to'")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    if project_id is not None:
        if not isinstance(project_id, str):
            e = _err("VALIDATION_ERROR", "'project_id' must be a string")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        if not re.match(r"^tdst_prj_[0-9A-Z]{18,}$", project_id):
            e = _err("VALIDATION_ERROR", "'project_id' has invalid format")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    if label_ids is not None:
        if not isinstance(label_ids, list):
            e = _err("VALIDATION_ERROR", "'label_ids' must be an array of strings")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        for lid in label_ids:
            if not isinstance(lid, str) or not re.match(r"^tdst_lbl_[0-9A-Z]{18,}$", lid):
                e = _err("VALIDATION_ERROR", "Each entry in 'label_ids' must be a valid local label id")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        e = _err("VALIDATION_ERROR", "'limit' must be an integer")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "'limit' must be between 1 and 200")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    offset, e = _decode_cursor(cursor)
    if e:
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    # Validate referenced ids if provided
    projects = _load("projects.json")
    if project_id is not None:
        if not any(p.get("id") == project_id for p in projects):
            e = _err("VALIDATION_ERROR", "Unknown 'project_id'")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    if label_ids:
        labels = _load("labels.json")
        label_set = {l.get("id") for l in labels}
        missing = [lid for lid in label_ids if lid not in label_set]
        if missing:
            e = _err("VALIDATION_ERROR", "Unknown label id(s) in 'label_ids'", missing=missing)
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    tasks = _load("tasks.json")

    def _due_in_range(task):
        if task.get("status") != "completed":
            return False
        dd = task.get("due_date")
        if not dd:
            return False
        dt, perr = _parse_dt(dd, "due_date")
        if perr:
            return False
        return fdt <= dt <= tdt

    def _labels_match(task):
        if not label_ids:
            return True
        tlabels = task.get("labels")
        if not isinstance(tlabels, list):
            tlabels = []
        tset = set([x for x in tlabels if isinstance(x, str)])
        return all(lid in tset for lid in label_ids)

    filtered = []
    for task in tasks:
        if not isinstance(task, dict):
            continue
        if project_id is not None and task.get("project_id") != project_id:
            continue
        if not _labels_match(task):
            continue
        if not _due_in_range(task):
            continue
        if task.get("status") == "deleted":
            continue
        filtered.append(task)

    # Sort by due_date asc, tie-breaker by id
    def _due_sort_key(task):
        dd = task.get("due_date") or ""
        dt, _ = _parse_dt(dd, "due_date")
        if dt is None:
            dt = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return (dt, str(task.get("id") or ""))

    filtered.sort(key=_due_sort_key)

    total = len(filtered)
    start = offset
    if start > total:
        start = total
    end = min(start + limit, total)
    page = filtered[start:end]
    has_more = end < total
    next_cursor = _encode_cursor(end) if has_more else None

    resp = {
        "tasks": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }
    _log("ok", meta={"returned": len(page), "total": total, "has_more": has_more})
    return resp

def get_productivity_stats(from_, to, group_by, project_id=None, label_ids=None, timezone=None, **_extra):
    from_ = _extra.pop("from", from_)
    import json, os, datetime, time, re
    try:
        from zoneinfo import ZoneInfo
    except Exception:
        ZoneInfo = None

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()

    def _parse_dt(s, field):
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"'{field}' must be an RFC3339 datetime string")
        try:
            # Support trailing Z
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
        except Exception:
            return None, _err("VALIDATION_ERROR", f"'{field}' must be an RFC3339 datetime string")
        if dt.tzinfo is None:
            # Treat naive as UTC for this local server
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    def _get_reqlog():
        rows = _load("request_log.json")
        if isinstance(rows, list):
            return rows
        return []

    def _save_reqlog(rows):
        _save("request_log.json", rows)

    def _enforce_rate_limit(reqlog, endpoint):
        # Simple global limit: 120 req/min across the datastore
        now = datetime.datetime.now(datetime.timezone.utc)
        win_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reqlog:
            try:
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                tss = ts
                if tss.endswith("Z"):
                    tss = tss[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(tss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
                if dt >= win_start:
                    cnt += 1
            except Exception:
                continue
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    endpoint = "get-productivity-stats"
    reqlog = _get_reqlog()
    rlerr = _enforce_rate_limit(reqlog, endpoint)
    if rlerr:
        # log refused request
        reqlog.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "status": "error",
                "error_code": rlerr["error"]["code"],
                "timestamp": _iso_now(),
                "latency_ms": int((time.time() - _t0) * 1000),
            }
        )
        _save_reqlog(reqlog)
        return rlerr

    # Validate group_by
    if group_by not in ("day", "week", "month"):
        err = _err("VALIDATION_ERROR", "group_by must be one of: day, week, month")
        reqlog.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "timestamp": _iso_now(),
                "latency_ms": int((time.time() - _t0) * 1000),
            }
        )
        _save_reqlog(reqlog)
        return err

    # Validate from/to
    from_dt, e1 = _parse_dt(from_, "from")
    if e1:
        reqlog.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "status": "error",
                "error_code": e1["error"]["code"],
                "timestamp": _iso_now(),
                "latency_ms": int((time.time() - _t0) * 1000),
            }
        )
        _save_reqlog(reqlog)
        return e1
    to_dt, e2 = _parse_dt(to, "to")
    if e2:
        reqlog.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "status": "error",
                "error_code": e2["error"]["code"],
                "timestamp": _iso_now(),
                "latency_ms": int((time.time() - _t0) * 1000),
            }
        )
        _save_reqlog(reqlog)
        return e2

    if from_dt > to_dt:
        err = _err("VALIDATION_ERROR", "'from' must be <= 'to'")
        reqlog.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "timestamp": _iso_now(),
                "latency_ms": int((time.time() - _t0) * 1000),
            }
        )
        _save_reqlog(reqlog)
        return err

    # Validate optional project_id format and existence
    if project_id is not None:
        if not isinstance(project_id, str) or not re.match(r"^tdst_prj_[0-9A-Z]{18,}$", project_id):
            err = _err("VALIDATION_ERROR", "project_id is malformed")
            reqlog.append(
                {
                    "id": f"req_{int(time.time()*1000)}",
                    "endpoint": endpoint,
                    "status": "error",
                    "error_code": "VALIDATION_ERROR",
                    "timestamp": _iso_now(),
                    "latency_ms": int((time.time() - _t0) * 1000),
                }
            )
            _save_reqlog(reqlog)
            return err
        projects = _load("projects.json")
        if not any(isinstance(p, dict) and p.get("id") == project_id for p in projects):
            err = _err("NOT_FOUND", "project_id not found")
            reqlog.append(
                {
                    "id": f"req_{int(time.time()*1000)}",
                    "endpoint": endpoint,
                    "status": "error",
                    "error_code": "NOT_FOUND",
                    "timestamp": _iso_now(),
                    "latency_ms": int((time.time() - _t0) * 1000),
                }
            )
            _save_reqlog(reqlog)
            return err

    # Validate label_ids format and existence
    if label_ids is not None:
        if not isinstance(label_ids, list):
            err = _err("VALIDATION_ERROR", "label_ids must be an array of label ids")
            reqlog.append(
                {
                    "id": f"req_{int(time.time()*1000)}",
                    "endpoint": endpoint,
                    "status": "error",
                    "error_code": "VALIDATION_ERROR",
                    "timestamp": _iso_now(),
                    "latency_ms": int((time.time() - _t0) * 1000),
                }
            )
            _save_reqlog(reqlog)
            return err
        for lid in label_ids:
            if not isinstance(lid, str) or not re.match(r"^tdst_lbl_[0-9A-Z]{18,}$", lid):
                err = _err("VALIDATION_ERROR", "label_ids contains a malformed label id")
                reqlog.append(
                    {
                        "id": f"req_{int(time.time()*1000)}",
                        "endpoint": endpoint,
                        "status": "error",
                        "error_code": "VALIDATION_ERROR",
                        "timestamp": _iso_now(),
                        "latency_ms": int((time.time() - _t0) * 1000),
                    }
                )
                _save_reqlog(reqlog)
                return err
        labels = _load("labels.json")
        label_set = {l.get("id") for l in labels if isinstance(l, dict)}
        missing = [lid for lid in label_ids if lid not in label_set]
        if missing:
            err = _err("NOT_FOUND", "One or more label_ids not found", missing_label_ids=missing)
            reqlog.append(
                {
                    "id": f"req_{int(time.time()*1000)}",
                    "endpoint": endpoint,
                    "status": "error",
                    "error_code": "NOT_FOUND",
                    "timestamp": _iso_now(),
                    "latency_ms": int((time.time() - _t0) * 1000),
                }
            )
            _save_reqlog(reqlog)
            return err

    # Resolve timezone for bucketing
    tzname = timezone if isinstance(timezone, str) and timezone.strip() else "UTC"
    tz = datetime.timezone.utc
    if tzname != "UTC":
        if ZoneInfo is None:
            err = _err("VALIDATION_ERROR", "Timezone support is not available on this server runtime")
            reqlog.append(
                {
                    "id": f"req_{int(time.time()*1000)}",
                    "endpoint": endpoint,
                    "status": "error",
                    "error_code": "VALIDATION_ERROR",
                    "timestamp": _iso_now(),
                    "latency_ms": int((time.time() - _t0) * 1000),
                }
            )
            _save_reqlog(reqlog)
            return err
        try:
            tz = ZoneInfo(tzname)
        except Exception:
            err = _err("VALIDATION_ERROR", "Invalid IANA timezone", timezone=tzname)
            reqlog.append(
                {
                    "id": f"req_{int(time.time()*1000)}",
                    "endpoint": endpoint,
                    "status": "error",
                    "error_code": "VALIDATION_ERROR",
                    "timestamp": _iso_now(),
                    "latency_ms": int((time.time() - _t0) * 1000),
                }
            )
            _save_reqlog(reqlog)
            return err

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []

    # Filter by completion window (inclusive), status completed, exclude deleted
    want_labels = set(label_ids) if isinstance(label_ids, list) else None

    def _parse_row_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    filtered = []
    for t in tasks:
        if not isinstance(t, dict):
            continue
        if t.get("status") != "completed":
            continue
        if t.get("status") == "deleted":
            continue
        if t.get("deleted_at") is not None or t.get("status") == "deleted":
            continue
        if project_id is not None and t.get("project_id") != project_id:
            continue
        if want_labels is not None:
            tl = t.get("labels")
            if not isinstance(tl, list):
                continue
            if not want_labels.issubset(set([x for x in tl if isinstance(x, str)])):
                continue
        cdt = _parse_row_dt(t.get("completed_at"))
        if cdt is None:
            continue
        if cdt < from_dt or cdt > to_dt:
            continue
        filtered.append((t, cdt))

    # Bucket by group_by using local timezone
    buckets = {}
    for _, cdt in filtered:
        local = cdt.astimezone(tz)
        if group_by == "day":
            key_dt = datetime.datetime(local.year, local.month, local.day, tzinfo=tz)
            key = key_dt.date().isoformat()
        elif group_by == "week":
            # ISO week bucket label: YYYY-Www
            iso_year, iso_week, _ = local.isocalendar()
            key = f"{iso_year}-W{iso_week:02d}"
        else:  # month
            key = f"{local.year:04d}-{local.month:02d}"
        buckets[key] = buckets.get(key, 0) + 1

    # Sort buckets chronologically as best-effort depending on grouping
    def _bucket_sort_key(k):
        try:
            if group_by == "day":
                return (0, datetime.date.fromisoformat(k))
            if group_by == "month":
                y, m = k.split("-")
                return (1, int(y), int(m))
            if group_by == "week":
                y, w = k.split("-W")
                return (2, int(y), int(w))
        except Exception:
            return (9, k)
        return (9, k)

    series = [{"bucket": k, "completed_count": buckets[k]} for k in sorted(buckets.keys(), key=_bucket_sort_key)]

    resp = {
        "from": from_dt.isoformat(),
        "to": to_dt.isoformat(),
        "group_by": group_by,
        "timezone": tzname,
        "filters": {"project_id": project_id, "label_ids": list(want_labels) if want_labels is not None else None},
        "total_completed": sum(buckets.values()),
        "series": series,
    }

    reqlog.append(
        {
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": "ok",
            "timestamp": _iso_now(),
            "latency_ms": int((time.time() - _t0) * 1000),
        }
    )
    _save_reqlog(reqlog)
    return resp

def update_task(task_id, content=None, description=None, project_id=None, section_id=None, parent_task_id=None, priority=None, label_ids=None, due_date=None, due_date_text=None, due_timezone=None, deadline_date=None, deadline_lang=None, duration_amount=None, duration_unit=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start_t = time.time()
    endpoint = "update-task"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            ss = s.strip().replace("Z", "+00:00")
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log(status_code, err_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "credential": None,
            "status": status_code,
            "error_code": err_code,
            "latency_ms": int((time.time() - start_t) * 1000),
            "ts": _iso_now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_rate_limit():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return True
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-2000:]:
            ts = r.get("ts")
            if isinstance(ts, str):
                dt = _parse_dt(ts)
                if dt and dt >= window_start:
                    cnt += 1
        return cnt < 120

    if not _check_rate_limit():
        _log("error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Too many requests; please retry later.")

    tsk_pat = re.compile(r"^tdst_tsk_[0-9A-Z]{18,}$")
    prj_pat = re.compile(r"^tdst_prj_[0-9A-Z]{18,}$")
    sec_pat = re.compile(r"^tdst_sec_[0-9A-Z]{18,}$")
    lbl_pat = re.compile(r"^tdst_lbl_[0-9A-Z]{18,}$")

    if not isinstance(task_id, str) or not tsk_pat.match(task_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed 'task_id'.")

    if content is not None and (not isinstance(content, str) or content == ""):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "'content' must be a non-empty string when provided.")
    if description is not None and (not isinstance(description, str)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "'description' must be a string when provided.")
    if project_id is not None and (not isinstance(project_id, str) or not prj_pat.match(project_id)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed 'project_id'.")
    if section_id is not None and (not isinstance(section_id, str) or not sec_pat.match(section_id)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed 'section_id'.")
    if parent_task_id is not None and (not isinstance(parent_task_id, str) or not tsk_pat.match(parent_task_id)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed 'parent_task_id'.")
    if priority is not None:
        if not isinstance(priority, int) or priority < 1 or priority > 4:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'priority'; must be integer 1-4.")
    if label_ids is not None:
        if not isinstance(label_ids, list):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "'label_ids' must be an array.")
        for lid in label_ids:
            if not isinstance(lid, str) or not lbl_pat.match(lid):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Malformed label id in 'label_ids'.", label_id=lid)

    if duration_amount is not None:
        if not isinstance(duration_amount, int) or duration_amount < 1:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'duration_amount'; must be integer >= 1.")
    if duration_unit is not None:
        if duration_unit not in ("minute", "day"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'duration_unit'.", allowed=["minute", "day"])
    if (duration_amount is None) != (duration_unit is None):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "'duration_amount' and 'duration_unit' must be provided together (or both omitted).")

    dd_dt = _parse_dt(due_date) if due_date is not None else None
    if due_date is not None and dd_dt is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'due_date' date-time.")
    dl_dt = _parse_dt(deadline_date) if deadline_date is not None else None
    if deadline_date is not None and dl_dt is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'deadline_date' date-time.")
    if due_date_text is not None and not isinstance(due_date_text, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "'due_date_text' must be a string when provided.")
    if due_timezone is not None and not isinstance(due_timezone, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "'due_timezone' must be a string when provided.")
    if deadline_lang is not None and not isinstance(deadline_lang, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "'deadline_lang' must be a string when provided.")

    tasks = _load("tasks.json")
    projects = _load("projects.json")
    sections = _load("sections.json")
    labels = _load("labels.json")

    idx = None
    for i, t in enumerate(tasks):
        if t.get("id") == task_id:
            idx = i
            break
    if idx is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Task not found.", task_id=task_id)

    task = dict(tasks[idx])

    # Cannot update a deleted task via this endpoint (treat as conflict)
    if task.get("status") == "deleted":
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Task is deleted and cannot be updated.", task_id=task_id)

    # Resolve destination references with validation
    dest_project_id = project_id if project_id is not None else task.get("project_id")
    if dest_project_id is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Task has no project_id; cannot update.")
    prj = next((p for p in projects if p.get("id") == dest_project_id), None)
    if prj is None or prj.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Destination project not found.", project_id=dest_project_id)

    dest_section_id = section_id if section_id is not None else task.get("section_id")
    if dest_section_id is not None:
        sec = next((s for s in sections if s.get("id") == dest_section_id), None)
        if sec is None or sec.get("status") == "deleted":
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Destination section not found.", section_id=dest_section_id)
        if sec.get("project_id") != dest_project_id:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "section_id must belong to the destination project_id.", section_id=dest_section_id, project_id=dest_project_id)

    dest_parent_task_id = parent_task_id if parent_task_id is not None else task.get("parent_task_id")
    if dest_parent_task_id is not None:
        if dest_parent_task_id == task_id:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_task_id cannot equal task_id.")
        parent = next((t for t in tasks if t.get("id") == dest_parent_task_id), None)
        if parent is None:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Parent task not found.", parent_task_id=dest_parent_task_id)
        if parent.get("status") == "deleted":
            _log("error", "CONFLICT")
            return _err("CONFLICT", "Cannot set a deleted task as parent.", parent_task_id=dest_parent_task_id)
        # Keep internal consistency: parent must be in same project
        if parent.get("project_id") != dest_project_id:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_task_id must belong to the same project as the task.", parent_task_id=dest_parent_task_id, project_id=dest_project_id)

    if label_ids is not None:
        active_label_ids = {l.get("id") for l in labels if l.get("status") == "active"}
        missing = [lid for lid in label_ids if lid not in active_label_ids]
        if missing:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "One or more labels were not found (or not active).", missing_label_ids=missing)

    # Apply updates
    now = _iso_now()
    changed = False

    def _set(field, value):
        nonlocal changed, task
        if task.get(field) != value:
            task[field] = value
            changed = True

    if content is not None:
        _set("content", content)
    if description is not None:
        _set("description", description)

    if project_id is not None:
        _set("project_id", dest_project_id)
    if section_id is not None:
        _set("section_id", dest_section_id)
    # If project changed but section not explicitly provided, keep existing section only if it still belongs; else null it.
    if project_id is not None and section_id is None:
        if task.get("section_id") is not None:
            sec = next((s for s in sections if s.get("id") == task.get("section_id")), None)
            if sec is None or sec.get("status") == "deleted" or sec.get("project_id") != task.get("project_id"):
                _set("section_id", None)

    if parent_task_id is not None:
        _set("parent_task_id", dest_parent_task_id)
    # If project changed and parent not explicitly provided, clear parent if it would mismatch.
    if project_id is not None and parent_task_id is None:
        pid = task.get("parent_task_id")
        if pid is not None:
            parent = next((t for t in tasks if t.get("id") == pid), None)
            if parent is None or parent.get("project_id") != task.get("project_id") or parent.get("status") == "deleted":
                _set("parent_task_id", None)

    if priority is not None:
        _set("priority", priority)

    if label_ids is not None:
        _set("labels", list(label_ids))

    if due_date is not None:
        _set("due_date", dd_dt.isoformat())
    if due_date_text is not None:
        _set("due_date_text", due_date_text)
    if due_timezone is not None:
        _set("due_timezone", due_timezone)

    if deadline_date is not None:
        _set("deadline_date", dl_dt.isoformat())
    if deadline_lang is not None:
        _set("deadline_lang", deadline_lang)

    if duration_amount is not None:
        _set("duration_amount", duration_amount)
    if duration_unit is not None:
        _set("duration_unit", duration_unit)

    # Enforce constraints: completed_at rules
    if task.get("status") == "completed":
        if task.get("completed_at") is None:
            task["completed_at"] = now
            changed = True
    else:
        # Non-completed must not have completed_at per constraints
        if task.get("completed_at") is not None:
            task["completed_at"] = None
            changed = True

    if changed:
        task["updated_at"] = now
        tasks[idx] = task
        _save("tasks.json", tasks)
    else:
        # still return the current stored row (no success without effect applies to mutations that match no row;
        # here it matched, and idempotency can legitimately result in no change).
        pass

    _log("ok")
    return task

def close_task(task_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start_t = time.time()
    endpoint = "close-task"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            ss = s.strip().replace("Z", "+00:00")
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log(status_code, err_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "credential": None,
            "status": status_code,
            "error_code": err_code,
            "latency_ms": int((time.time() - start_t) * 1000),
            "ts": _iso_now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_rate_limit():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return True
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-2000:]:
            ts = r.get("ts")
            if isinstance(ts, str):
                dt = _parse_dt(ts)
                if dt and dt >= window_start:
                    cnt += 1
        return cnt < 120

    if not _check_rate_limit():
        _log("error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Too many requests; please retry later.")

    tsk_pat = re.compile(r"^tdst_tsk_[0-9A-Z]{18,}$")
    if not isinstance(task_id, str) or not tsk_pat.match(task_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed 'task_id'.")

    tasks = _load("tasks.json")
    idx = None
    for i, t in enumerate(tasks):
        if t.get("id") == task_id:
            idx = i
            break
    if idx is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Task not found.", task_id=task_id)

    task = dict(tasks[idx])
    now = _iso_now()

    if task.get("status") == "deleted":
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Deleted tasks cannot be completed.", task_id=task_id)
    if task.get("status") == "completed":
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Task is already completed.", task_id=task_id)

    # Transition active -> completed
    if task.get("status") != "active":
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Illegal status transition to completed.", from_status=task.get("status"), to_status="completed")

    task["status"] = "completed"
    task["completed_at"] = now
    task["updated_at"] = now
    tasks[idx] = task
    _save("tasks.json", tasks)

    _log("ok")
    return task

def move_tasks(task_ids, project_id=None, section_id=None, parent_task_id=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start_t = time.time()
    endpoint = "move-tasks"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            ss = s.strip().replace("Z", "+00:00")
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log(status_code, err_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "credential": None,
            "status": status_code,
            "error_code": err_code,
            "latency_ms": int((time.time() - start_t) * 1000),
            "ts": _iso_now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_rate_limit():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return True
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-2000:]:
            ts = r.get("ts")
            if isinstance(ts, str):
                dt = _parse_dt(ts)
                if dt and dt >= window_start:
                    cnt += 1
        return cnt < 120

    if not _check_rate_limit():
        _log("error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Too many requests; please retry later.")

    tsk_pat = re.compile(r"^tdst_tsk_[0-9A-Z]{18,}$")
    prj_pat = re.compile(r"^tdst_prj_[0-9A-Z]{18,}$")
    sec_pat = re.compile(r"^tdst_sec_[0-9A-Z]{18,}$")

    if not isinstance(task_ids, list) or len(task_ids) < 1:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "'task_ids' must be a non-empty array.")
    for tid in task_ids:
        if not isinstance(tid, str) or not tsk_pat.match(tid):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Malformed task id in 'task_ids'.", task_id=tid)

    if project_id is None and section_id is None and parent_task_id is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "At least one destination must be provided: project_id and/or section_id and/or parent_task_id.")

    if project_id is not None and (not isinstance(project_id, str) or not prj_pat.match(project_id)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed 'project_id'.")
    if section_id is not None and (not isinstance(section_id, str) or not sec_pat.match(section_id)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed 'section_id'.")
    if parent_task_id is not None and (not isinstance(parent_task_id, str) or not tsk_pat.match(parent_task_id)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed 'parent_task_id'.")

    tasks = _load("tasks.json")
    projects = _load("projects.json")
    sections = _load("sections.json")

    # Gather tasks to move; fail if any missing (atomic behavior)
    by_id = {t.get("id"): t for t in tasks if isinstance(t, dict)}
    missing_tasks = [tid for tid in task_ids if tid not in by_id]
    if missing_tasks:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "One or more tasks not found.", missing_task_ids=missing_tasks)

    # Resolve destination project/section/parent
    dest_project_id = project_id
    dest_section_id = section_id
    dest_parent_id = parent_task_id

    if dest_project_id is not None:
        prj = next((p for p in projects if p.get("id") == dest_project_id), None)
        if prj is None or prj.get("status") == "deleted":
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Destination project not found.", project_id=dest_project_id)

    if dest_section_id is not None:
        sec = next((s for s in sections if s.get("id") == dest_section_id), None)
        if sec is None or sec.get("status") == "deleted":
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Destination section not found.", section_id=dest_section_id)
        # If project_id not provided, infer destination project from section
        if dest_project_id is None:
            dest_project_id = sec.get("project_id")
        else:
            if sec.get("project_id") != dest_project_id:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "section_id must belong to the destination project_id.", section_id=dest_section_id, project_id=dest_project_id)

    # Parent task validation (and infer project from parent if needed)
    parent_task = None
    if dest_parent_id is not None:
        parent_task = by_id.get(dest_parent_id)
        if parent_task is None:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Destination parent_task_id not found.", parent_task_id=dest_parent_id)
        if parent_task.get("status") == "deleted":
            _log("error", "CONFLICT")
            return _err("CONFLICT", "Cannot move tasks under a deleted parent task.", parent_task_id=dest_parent_id)
        if dest_project_id is None:
            dest_project_id = parent_task.get("project_id")
        else:
            if parent_task.get("project_id") != dest_project_id:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "parent_task_id must belong to the destination project_id.", parent_task_id=dest_parent_id, project_id=dest_project_id)

    # If after inference we still don't have a project, keep per-task project unless a section was specified (handled above).
    # But business rule: section must belong to same project after move. We'll enforce per task if dest_project_id remains None.
    now = _iso_now()

    # Pre-validate per-task constraints atomically
    for tid in task_ids:
        if dest_parent_id is not None and tid == dest_parent_id:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "A task cannot be moved to be a child of itself.", task_id=tid, parent_task_id=dest_parent_id)

        t = by_id[tid]
        eff_project = dest_project_id if dest_project_id is not None else t.get("project_id")

        if eff_project is None:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Task has no project_id; cannot move.", task_id=tid)

        prj = next((p for p in projects if p.get("id") == eff_project), None)
        if prj is None or prj.get("status") == "deleted":
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Destination project not found for task.", task_id=tid, project_id=eff_project)

        if dest_section_id is not None:
            sec = next((s for s in sections if s.get("id") == dest_section_id), None)
            if sec is None or sec.get("status") == "deleted":
                _log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "Destination section not found.", section_id=dest_section_id)
            if sec.get("project_id") != eff_project:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "section_id must belong to the same project_id after move.", section_id=dest_section_id, project_id=eff_project, task_id=tid)

        if dest_parent_id is not None:
            # parent must be in same effective project (ensured above via dest_project inference/check)
            pass

    # Apply updates (atomic commit)
    updated = []
    changed_any = False
    for i, t in enumerate(tasks):
        tid = t.get("id")
        if tid not in set(task_ids):
            continue
        newt = dict(t)
        changed = False

        if dest_project_id is not None and newt.get("project_id") != dest_project_id:
            newt["project_id"] = dest_project_id
            changed = True

        if section_id is not None:
            if newt.get("section_id") != dest_section_id:
                newt["section_id"] = dest_section_id
                changed = True
        elif dest_project_id is not None:
            # If moving projects without specifying section, null section if it doesn't belong anymore
            if newt.get("section_id") is not None:
                sec = next((s for s in sections if s.get("id") == newt.get("section_id")), None)
                if sec is None or sec.get("status") == "deleted" or sec.get("project_id") != newt.get("project_id"):
                    newt["section_id"] = None
                    changed = True

        if parent_task_id is not None:
            if newt.get("parent_task_id") != dest_parent_id:
                newt["parent_task_id"] = dest_parent_id
                changed = True
        elif dest_project_id is not None:
            # If project changed and parent not provided, clear parent if it would mismatch
            pid = newt.get("parent_task_id")
            if pid is not None:
                p = by_id.get(pid)
                if p is None or p.get("status") == "deleted" or p.get("project_id") != newt.get("project_id"):
                    newt["parent_task_id"] = None
                    changed = True

        if changed:
            newt["updated_at"] = now
            tasks[i] = newt
            changed_any = True
        updated.append(tasks[i])

    if not changed_any:
        # Matched tasks exist, but nothing changed; idempotent success should still return updated rows.
        _log("ok")
        # Return tasks in same order as input
        out = []
        by_id2 = {t.get("id"): t for t in tasks}
        for tid in task_ids:
            out.append(by_id2[tid])
        return {"moved": out, "count": len(out)}

    _save("tasks.json", tasks)

    # Return tasks in same order as input
    by_id2 = {t.get("id"): t for t in tasks}
    out = [by_id2[tid] for tid in task_ids]

    _log("ok")
    return {"moved": out, "count": len(out)}

def delete_task(task_id, **_extra):
    import json, os, datetime, time, re

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()

    def _get_reqlog():
        rows = _load("request_log.json")
        if isinstance(rows, list):
            return rows
        return []

    def _save_reqlog(rows):
        _save("request_log.json", rows)

    def _enforce_rate_limit(reqlog, endpoint):
        now = datetime.datetime.now(datetime.timezone.utc)
        win_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reqlog:
            try:
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                tss = ts
                if tss.endswith("Z"):
                    tss = tss[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(tss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
                if dt >= win_start:
                    cnt += 1
            except Exception:
                continue
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    endpoint = "delete-task"
    reqlog = _get_reqlog()
    rlerr = _enforce_rate_limit(reqlog, endpoint)
    if rlerr:
        reqlog.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "status": "error",
                "error_code": rlerr["error"]["code"],
                "timestamp": _iso_now(),
                "latency_ms": int((time.time() - _t0) * 1000),
            }
        )
        _save_reqlog(reqlog)
        return rlerr

    if not isinstance(task_id, str) or not re.match(r"^tdst_tsk_[A-Za-z0-9]+$", task_id):
        err = _err("VALIDATION_ERROR", "task_id is malformed")
        reqlog.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "timestamp": _iso_now(),
                "latency_ms": int((time.time() - _t0) * 1000),
            }
        )
        _save_reqlog(reqlog)
        return err

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []

    idx = None
    for i, t in enumerate(tasks):
        if isinstance(t, dict) and t.get("id") == task_id:
            idx = i
            break

    if idx is None:
        err = _err("NOT_FOUND", "Task not found", task_id=task_id)
        reqlog.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "status": "error",
                "error_code": "NOT_FOUND",
                "timestamp": _iso_now(),
                "latency_ms": int((time.time() - _t0) * 1000),
            }
        )
        _save_reqlog(reqlog)
        return err

    task = tasks[idx]
    if not isinstance(task, dict):
        err = _err("NOT_FOUND", "Task not found", task_id=task_id)
        reqlog.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "status": "error",
                "error_code": "NOT_FOUND",
                "timestamp": _iso_now(),
                "latency_ms": int((time.time() - _t0) * 1000),
            }
        )
        _save_reqlog(reqlog)
        return err

    if task.get("status") == "deleted" or task.get("deleted_at") is not None:
        err = _err("CONFLICT", "Task is already deleted", task_id=task_id)
        reqlog.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "status": "error",
                "error_code": "CONFLICT",
                "timestamp": _iso_now(),
                "latency_ms": int((time.time() - _t0) * 1000),
            }
        )
        _save_reqlog(reqlog)
        return err

    # Lifecycle transition: active/completed -> deleted allowed; deleted -> none
    now = _iso_now()
    prev_status = task.get("status")
    if prev_status not in ("active", "completed"):
        # If unknown, treat as invalid transition
        err = _err("INVALID_TRANSITION", "Task cannot be deleted from its current state", from_status=prev_status, to_status="deleted")
        reqlog.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "status": "error",
                "error_code": "INVALID_TRANSITION",
                "timestamp": now,
                "latency_ms": int((time.time() - _t0) * 1000),
            }
        )
        _save_reqlog(reqlog)
        return err

    task["status"] = "deleted"
    task["deleted_at"] = now
    task["updated_at"] = now
    # keep completed_at as-is if previously completed (mirrors common behavior)

    tasks[idx] = task
    _save("tasks.json", tasks)

    reqlog.append(
        {
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": "ok",
            "timestamp": now,
            "latency_ms": int((time.time() - _t0) * 1000),
        }
    )
    _save_reqlog(reqlog)
    return {"task": task}

def reopen_task(task_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- auth (ambient) + rate limiting/quota via request log if present ---
    request_logs = _load("request_logs.json")
    usage = _load("usage.json")
    accounts = _load("accounts.json")
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")

    def _append_log(status, endpoint="reopen-task", credential_id=None, meta=None):
        nonlocal request_logs
        latency_ms = int(round((time.time() - t0) * 1000))
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(request_logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": now
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        request_logs.append(row)
        _save("request_logs.json", request_logs)

    def _find_working_context():
        # Prefer an API key marked active; otherwise accept any active workspace/account combo.
        # This is ambient: caller already authenticated; UNAUTHORIZED only if store has no viable context.
        for k in api_keys if isinstance(api_keys, list) else []:
            if isinstance(k, dict) and k.get("status") in (None, "active", "enabled"):
                return {"credential_id": k.get("id"), "workspace_id": k.get("workspace_id"), "account_id": k.get("account_id")}
        for w in workspaces if isinstance(workspaces, list) else []:
            if isinstance(w, dict) and w.get("status") in (None, "active"):
                return {"credential_id": None, "workspace_id": w.get("id"), "account_id": w.get("account_id")}
        for a in accounts if isinstance(accounts, list) else []:
            if isinstance(a, dict) and a.get("status") in (None, "active"):
                return {"credential_id": None, "workspace_id": None, "account_id": a.get("id")}
        return None

    ctx = _find_working_context()
    if not ctx:
        _append_log("UNAUTHORIZED", meta={"reason": "no_ambient_context"})
        return _err("UNAUTHORIZED", "Not authenticated.")

    # Rate limit/quota enforcement (best-effort; enforced only if usage schema exists in store)
    # usage.json may contain rows keyed by credential_id or account_id with limits.
    def _get_usage_row():
        if not isinstance(usage, list):
            return None
        # try credential-specific first
        cid = ctx.get("credential_id")
        aid = ctx.get("account_id")
        for r in usage:
            if not isinstance(r, dict):
                continue
            if cid and (r.get("credential_id") == cid or r.get("id") == cid):
                return r
        for r in usage:
            if not isinstance(r, dict):
                continue
            if aid and (r.get("account_id") == aid or r.get("id") == aid):
                return r
        return None

    def _parse_ts(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    urow = _get_usage_row()
    if isinstance(urow, dict):
        # Rate limit window: last 60s
        limit_per_min = urow.get("rate_limit_per_minute")
        monthly_quota = urow.get("monthly_quota")
        now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        if isinstance(limit_per_min, int) and limit_per_min >= 0 and isinstance(request_logs, list):
            cutoff = now_dt - datetime.timedelta(seconds=60)
            count = 0
            for rl in request_logs:
                if not isinstance(rl, dict):
                    continue
                if rl.get("credential_id") != ctx.get("credential_id"):
                    continue
                ts = _parse_ts(rl.get("timestamp"))
                if ts and ts >= cutoff:
                    count += 1
            if count >= limit_per_min:
                _append_log("RATE_LIMIT", credential_id=ctx.get("credential_id"), meta={"limit_per_minute": limit_per_min})
                return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(monthly_quota, int) and monthly_quota >= 0 and isinstance(request_logs, list):
            # Approx monthly: same calendar month in UTC
            m0 = now_dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            count = 0
            for rl in request_logs:
                if not isinstance(rl, dict):
                    continue
                if rl.get("credential_id") != ctx.get("credential_id"):
                    continue
                ts = _parse_ts(rl.get("timestamp"))
                if ts and ts >= m0:
                    count += 1
            if count >= monthly_quota:
                _append_log("QUOTA_EXCEEDED", credential_id=ctx.get("credential_id"), meta={"monthly_quota": monthly_quota})
                return _err("QUOTA_EXCEEDED", "Quota exceeded.")

    # --- validate input ---
    if not isinstance(task_id, str):
        _append_log("VALIDATION_ERROR", credential_id=ctx.get("credential_id"), meta={"field": "task_id"})
        return _err("VALIDATION_ERROR", "task_id must be a string.", field="task_id")
    if not re.match(r"^tdst_tsk_[A-Za-z0-9]+$", task_id):
        _append_log("VALIDATION_ERROR", credential_id=ctx.get("credential_id"), meta={"field": "task_id"})
        return _err("VALIDATION_ERROR", "task_id is malformed.", field="task_id")

    # --- load tasks and apply transition ---
    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        _append_log("NOT_FOUND", credential_id=ctx.get("credential_id"))
        return _err("NOT_FOUND", "Task not found.")

    idx = None
    for i, t in enumerate(tasks):
        if isinstance(t, dict) and t.get("id") == task_id:
            idx = i
            break
    if idx is None:
        _append_log("NOT_FOUND", credential_id=ctx.get("credential_id"))
        return _err("NOT_FOUND", "Task not found.", task_id=task_id)

    task = tasks[idx]
    status = task.get("status")

    # Forbidden check: no access model present in schema; cannot deny without evidence.
    # If an access control collection existed, we'd enforce it. Here we proceed.

    if status == "deleted":
        _append_log("CONFLICT", credential_id=ctx.get("credential_id"), meta={"status": status})
        return _err("CONFLICT", "Cannot reopen a deleted task.", task_id=task_id, status=status)

    if status != "completed":
        _append_log("CONFLICT", credential_id=ctx.get("credential_id"), meta={"status": status})
        return _err("CONFLICT", "Task is not currently completed.", task_id=task_id, status=status)

    # lifecycle transition completed -> active; clear completed_at
    task["status"] = "active"
    task["completed_at"] = None
    task["updated_at"] = now

    # Ensure constraint: status <> 'completed' OR completed_at IS NOT NULL satisfied
    # (we cleared completed_at because status is now active)

    tasks[idx] = task
    _save("tasks.json", tasks)

    _append_log("OK", credential_id=ctx.get("credential_id"), meta={"task_id": task_id})

    return {
        "task": task
    }

def get_tasks_by_filter(filter, limit=None, cursor=None, sort_by=None, sort_order=None, status=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log_call(endpoint, status_code, latency_ms, credential_id=None, meta=None):
        # Best-effort request log. If absent from datastore, keep a minimal local log file.
        ts = _now_iso()
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{ts}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": int(latency_ms),
            "timestamp": ts,
            "credential_id": credential_id,
        }
        if meta is not None:
            row["meta"] = meta
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()

    # Validate inputs
    if not isinstance(filter, str) or len(filter.strip()) < 1:
        latency = (time.time() - t0) * 1000
        _log_call("get-tasks-by-filter", "VALIDATION_ERROR", latency, meta={"reason": "empty_filter"})
        return _err("VALIDATION_ERROR", "filter must be a non-empty string")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        latency = (time.time() - t0) * 1000
        _log_call("get-tasks-by-filter", "VALIDATION_ERROR", latency, meta={"reason": "bad_limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    allowed_sort_by = {"due_date", "priority", "created_at", "updated_at"}
    allowed_sort_order = {"asc", "desc"}
    allowed_status = {"active", "completed", "deleted"}

    if sort_by is None:
        sort_by = "due_date"
    if sort_by not in allowed_sort_by:
        latency = (time.time() - t0) * 1000
        _log_call("get-tasks-by-filter", "VALIDATION_ERROR", latency, meta={"reason": "bad_sort_by"})
        return _err("VALIDATION_ERROR", f"sort_by must be one of {sorted(allowed_sort_by)}")

    if sort_order is None:
        sort_order = "asc"
    if sort_order not in allowed_sort_order:
        latency = (time.time() - t0) * 1000
        _log_call("get-tasks-by-filter", "VALIDATION_ERROR", latency, meta={"reason": "bad_sort_order"})
        return _err("VALIDATION_ERROR", f"sort_order must be one of {sorted(allowed_sort_order)}")

    if status is None:
        status = "active"
    if status not in allowed_status:
        latency = (time.time() - t0) * 1000
        _log_call("get-tasks-by-filter", "VALIDATION_ERROR", latency, meta={"reason": "bad_status"})
        return _err("VALIDATION_ERROR", f"status must be one of {sorted(allowed_status)}")

    # Cursor handling: opaque base64(JSON) with query hash and offset
    query_norm = filter.strip()
    qfinger = hashlib.sha256(
        json.dumps(
            {"filter": query_norm, "sort_by": sort_by, "sort_order": sort_order, "status": status},
            sort_keys=True,
            ensure_ascii=False,
        ).encode("utf-8")
    ).hexdigest()

    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            latency = (time.time() - t0) * 1000
            _log_call("get-tasks-by-filter", "VALIDATION_ERROR", latency, meta={"reason": "bad_cursor_type"})
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
        except Exception:
            latency = (time.time() - t0) * 1000
            _log_call("get-tasks-by-filter", "VALIDATION_ERROR", latency, meta={"reason": "cursor_decode"})
            return _err("VALIDATION_ERROR", "cursor is invalid")
        if not isinstance(payload, dict) or payload.get("q") != qfinger:
            latency = (time.time() - t0) * 1000
            _log_call("get-tasks-by-filter", "VALIDATION_ERROR", latency, meta={"reason": "cursor_query_mismatch"})
            return _err("VALIDATION_ERROR", "cursor is invalid for this query")
        off = payload.get("o")
        if not isinstance(off, int) or off < 0:
            latency = (time.time() - t0) * 1000
            _log_call("get-tasks-by-filter", "VALIDATION_ERROR", latency, meta={"reason": "cursor_offset"})
            return _err("VALIDATION_ERROR", "cursor is invalid")
        offset = off

    # Load data
    tasks = _load("tasks.json")
    labels = _load("labels.json")
    projects = _load("projects.json")

    if not isinstance(tasks, list):
        tasks = []
    if not isinstance(labels, list):
        labels = []
    if not isinstance(projects, list):
        projects = []

    label_by_name = {}
    for lb in labels:
        if isinstance(lb, dict) and lb.get("status") == "active":
            nm = lb.get("name")
            if isinstance(nm, str) and nm:
                label_by_name[nm.lower()] = lb.get("id")

    project_by_name = {}
    for pr in projects:
        if isinstance(pr, dict) and pr.get("status") in ("active", "archived"):
            nm = pr.get("name")
            if isinstance(nm, str) and nm:
                project_by_name[nm.lower()] = pr.get("id")

    # Filter language: support a common subset; reject unsupported constructs explicitly
    # Supported tokens:
    #   today, overdue
    #   p1..p4
    #   @labelName
    #   #ProjectName
    # Operators:
    #   "&" AND, "|" OR
    # Parentheses not supported; "!" and complex functions not supported.
    f = query_norm
    unsupported_markers = ["(", ")", "!", "assigned", "search:", "due before", "due after", "##", "(", ")", ":", "(", ")"]
    # Allow "project:" prefix as token (no colon in other contexts)
    # We'll allow exactly "project:<name>" and "label:<name>" and "p1..p4"
    # but reject other ":" usage
    def _has_unsupported(s):
        # Reject parentheses and bang
        if "(" in s or ")" in s or "!" in s:
            return True, "parentheses/negation not supported"
        # Reject quotes and commas (complex constructs)
        if '"' in s or "'" in s or "," in s:
            return True, "quoted/compound expressions not supported"
        # Colon usage limited to project:<x> or label:<x>
        if ":" in s:
            parts = [p for p in s.split() if ":" in p]
            for p in parts:
                if p.startswith("project:") or p.startswith("label:"):
                    if p.count(":") != 1 or len(p.split(":", 1)[1]) == 0:
                        return True, "malformed project:/label: construct"
                else:
                    return True, "unsupported ':' construct"
        return False, None

    bad, reason = _has_unsupported(f)
    if bad:
        latency = (time.time() - t0) * 1000
        _log_call("get-tasks-by-filter", "VALIDATION_ERROR", latency, meta={"reason": reason})
        return _err("VALIDATION_ERROR", f"Unsupported filter construct: {reason}")

    # Tokenize by spaces while keeping & and |
    def _tokenize(s):
        out = []
        buf = ""
        for ch in s:
            if ch in ["&", "|"]:
                if buf.strip():
                    out.append(buf.strip())
                out.append(ch)
                buf = ""
            else:
                buf += ch
        if buf.strip():
            out.append(buf.strip())
        # further split tokens by whitespace
        final = []
        for tok in out:
            if tok in ("&", "|"):
                final.append(tok)
            else:
                final.extend([t for t in tok.split() if t])
        return final

    tokens = _tokenize(f)
    if not tokens:
        latency = (time.time() - t0) * 1000
        _log_call("get-tasks-by-filter", "VALIDATION_ERROR", latency, meta={"reason": "empty_tokens"})
        return _err("VALIDATION_ERROR", "filter must not be empty")

    # Build simple expression: OR of AND-clauses (left associative with & higher precedence)
    # Convert to disjunctive normal-ish form via two-level parsing.
    def _parse(tokens_):
        clauses = []
        cur = []
        expecting_term = True
        for tok in tokens_:
            if tok in ("&", "|"):
                if expecting_term:
                    return None, "operator without term"
                if tok == "|":
                    clauses.append(cur)
                    cur = []
                expecting_term = True
            else:
                cur.append(tok)
                expecting_term = False
        if expecting_term and cur:
            return None, "trailing operator"
        if cur:
            clauses.append(cur)
        return clauses, None

    clauses, perr = _parse(tokens)
    if perr:
        latency = (time.time() - t0) * 1000
        _log_call("get-tasks-by-filter", "VALIDATION_ERROR", latency, meta={"reason": perr})
        return _err("VALIDATION_ERROR", f"Invalid filter syntax: {perr}")

    # Compile term matchers
    today = datetime.datetime.now(datetime.timezone.utc).date()

    def _term_pred(term):
        tl = term.strip()
        if not tl:
            return None, "empty term"
        low = tl.lower()

        if low == "today":
            def _p(t):
                dd = _parse_dt(t.get("due_date"))
                return dd is not None and dd.date() == today
            return _p, None

        if low == "overdue":
            def _p(t):
                dd = _parse_dt(t.get("due_date"))
                return dd is not None and dd < datetime.datetime.now(datetime.timezone.utc)
            return _p, None

        if low in ("p1", "p2", "p3", "p4"):
            pv = int(low[1:])
            def _p(t):
                return t.get("priority") == pv
            return _p, None

        if low.startswith("@") and len(low) > 1:
            lname = low[1:]
            lid = label_by_name.get(lname)
            if not lid:
                # Todoist would just match none; keep that behavior (no error)
                def _p(_t):
                    return False
                return _p, None
            def _p(t):
                lbs = t.get("labels")
                return isinstance(lbs, list) and lid in lbs
            return _p, None

        if low.startswith("#") and len(low) > 1:
            pname = low[1:]
            pid = project_by_name.get(pname)
            if not pid:
                def _p(_t):
                    return False
                return _p, None
            def _p(t):
                return t.get("project_id") == pid
            return _p, None

        if low.startswith("project:") and len(low) > len("project:"):
            pname = low.split(":", 1)[1].strip()
            pid = project_by_name.get(pname)
            if not pid:
                def _p(_t):
                    return False
                return _p, None
            def _p(t):
                return t.get("project_id") == pid
            return _p, None

        if low.startswith("label:") and len(low) > len("label:"):
            lname = low.split(":", 1)[1].strip()
            lid = label_by_name.get(lname)
            if not lid:
                def _p(_t):
                    return False
                return _p, None
            def _p(t):
                lbs = t.get("labels")
                return isinstance(lbs, list) and lid in lbs
            return _p, None

        # If term isn't recognized, reject instead of silently mis-filtering
        return None, f"unsupported term '{term}'"

    compiled = []
    for clause in clauses:
        preds = []
        for term in clause:
            p, e = _term_pred(term)
            if e:
                latency = (time.time() - t0) * 1000
                _log_call("get-tasks-by-filter", "VALIDATION_ERROR", latency, meta={"reason": e})
                return _err("VALIDATION_ERROR", f"Unsupported filter construct: {e}")
            preds.append(p)
        compiled.append(preds)

    def _matches_task(t):
        # status default rule: only active unless explicitly requested otherwise via status param
        if t.get("status") != status:
            return False
        # evaluate OR of ANDs
        for preds in compiled:
            ok = True
            for p in preds:
                if not p(t):
                    ok = False
                    break
            if ok:
                return True
        return False

    # Filter
    filtered = []
    for t in tasks:
        if not isinstance(t, dict):
            continue
        if _matches_task(t):
            filtered.append(t)

    # Sort
    rev = (sort_order == "desc")

    def _sort_key(t):
        if sort_by == "priority":
            v = t.get("priority")
            return (v if isinstance(v, int) else 0, t.get("id", ""))
        if sort_by == "due_date":
            dt = _parse_dt(t.get("due_date"))
            # For asc, tasks without due_date go last; for desc, tasks without due_date go first
            if dt is None:
                return (datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), t.get("id", "")) if not rev else (datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), t.get("id", ""))
            return (dt, t.get("id", ""))
        if sort_by == "created_at":
            dt = _parse_dt(t.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            return (dt, t.get("id", ""))
        if sort_by == "updated_at":
            dt = _parse_dt(t.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            return (dt, t.get("id", ""))
        return (t.get("id", ""))

    filtered.sort(key=_sort_key, reverse=rev)

    total = len(filtered)
    if offset > total:
        latency = (time.time() - t0) * 1000
        _log_call("get-tasks-by-filter", "VALIDATION_ERROR", latency, meta={"reason": "cursor_out_of_range"})
        return _err("VALIDATION_ERROR", "cursor is invalid for this query")

    page = filtered[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = {"q": qfinger, "o": next_offset}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")

    latency = (time.time() - t0) * 1000
    _log_call("get-tasks-by-filter", "OK", latency, meta={"returned": len(page), "total": total})

    return {
        "tasks": page,
        "filter": query_norm,
        "sort_by": sort_by,
        "sort_order": sort_order,
        "status": status,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total,
            "offset": offset,
        },
    }

def add_section(project_id, name, order=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log_call(endpoint, status_code, latency_ms, credential_id=None, meta=None):
        ts = _now_iso()
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{ts}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": int(latency_ms),
            "timestamp": ts,
            "credential_id": credential_id,
        }
        if meta is not None:
            row["meta"] = meta
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()

    # Validate inputs
    if not isinstance(project_id, str) or not project_id:
        latency = (time.time() - t0) * 1000
        _log_call("add-section", "VALIDATION_ERROR", latency, meta={"reason": "bad_project_id"})
        return _err("VALIDATION_ERROR", "project_id must be a non-empty string")
    import re
    if not re.match(r"^tdst_prj_[A-Za-z0-9]+$", project_id):
        latency = (time.time() - t0) * 1000
        _log_call("add-section", "VALIDATION_ERROR", latency, meta={"reason": "project_id_pattern"})
        return _err("VALIDATION_ERROR", "project_id is malformed")

    if not isinstance(name, str) or len(name.strip()) < 1:
        latency = (time.time() - t0) * 1000
        _log_call("add-section", "VALIDATION_ERROR", latency, meta={"reason": "empty_name"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string")
    name = name.strip()

    if order is not None and not isinstance(order, int):
        latency = (time.time() - t0) * 1000
        _log_call("add-section", "VALIDATION_ERROR", latency, meta={"reason": "bad_order_type"})
        return _err("VALIDATION_ERROR", "order must be an integer when provided")
    if isinstance(order, int) and order < 0:
        latency = (time.time() - t0) * 1000
        _log_call("add-section", "VALIDATION_ERROR", latency, meta={"reason": "bad_order_range"})
        return _err("VALIDATION_ERROR", "order must be >= 0 when provided")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    proj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == project_id:
            proj = p
            break
    if proj is None:
        latency = (time.time() - t0) * 1000
        _log_call("add-section", "NOT_FOUND", latency, meta={"reason": "project_not_found"})
        return _err("NOT_FOUND", "project_id does not exist")

    # Treat deleted project as not found for mutation
    if proj.get("status") == "deleted":
        latency = (time.time() - t0) * 1000
        _log_call("add-section", "NOT_FOUND", latency, meta={"reason": "project_deleted"})
        return _err("NOT_FOUND", "project_id does not exist")

    sections = _load("sections.json")
    if not isinstance(sections, list):
        sections = []

    # Enforce unique(project_id, name) where status <> 'deleted'
    for s in sections:
        if not isinstance(s, dict):
            continue
        if s.get("project_id") == project_id and s.get("status") != "deleted" and isinstance(s.get("name"), str) and s.get("name") == name:
            # Idempotent by upstream id isn't possible here (no todoist_section_id param), so return conflict
            latency = (time.time() - t0) * 1000
            _log_call("add-section", "CONFLICT", latency, meta={"reason": "duplicate_name"})
            return _err("CONFLICT", "a non-deleted section with this name already exists in the project")

    # Resolve order if not provided: append after max order within project (treat null as -1)
    resolved_order = order
    if resolved_order is None:
        max_order = -1
        for s in sections:
            if not isinstance(s, dict):
                continue
            if s.get("project_id") != project_id or s.get("status") == "deleted":
                continue
            ov = s.get("order")
            if isinstance(ov, int) and ov > max_order:
                max_order = ov
        resolved_order = max_order + 1

    now = _now_iso()
    new_id = "tdst_sec_" + hashlib.sha256(f"{project_id}|{name}|{now}|{time.time_ns()}".encode("utf-8")).hexdigest()[:12]
    todoist_section_id = "todo_sec_" + hashlib.sha256(f"upstream|{project_id}|{name}|{now}|{time.time_ns()}".encode("utf-8")).hexdigest()[:16]

    # Ensure unique(todoist_section_id) (practically guaranteed, but check)
    existing_todo_ids = {s.get("todoist_section_id") for s in sections if isinstance(s, dict)}
    while todoist_section_id in existing_todo_ids:
        todoist_section_id = "todo_sec_" + hashlib.sha256(f"upstream|{project_id}|{name}|{now}|{time.time_ns()}|x".encode("utf-8")).hexdigest()[:16]

    row = {
        "id": new_id,
        "todoist_section_id": todoist_section_id,
        "project_id": project_id,
        "name": name,
        "order": resolved_order,
        "status": "active",
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }

    sections.append(row)
    _save("sections.json", sections)

    latency = (time.time() - t0) * 1000
    _log_call("add-section", "OK", latency, meta={"section_id": new_id, "project_id": project_id})

    return {"section": row}

