        window_s = limits.get("window_seconds", 60)
        max_req = limits.get("max_requests", None)
        if not isinstance(window_s, int) or window_s <= 0:
            window_s = 60
        if max_req is None:
            return None
        if not isinstance(max_req, int) or max_req <= 0:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s2 = s[:-1]
                    return datetime.datetime.fromisoformat(s2)
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        n = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_ts(r.get("ts"))
            if ts is None:
                continue
            if ts >= cutoff:
                n += 1
        if n >= max_req:
            _log(endpoint, "RATE_LIMIT", started=started, message="Rate limit exceeded")
            return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=window_s)
        return None

    def _decode_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c:
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("idx:"):
                return None
            idx = int(s.split(":", 1)[1])
            if idx < 0:
                return None
            return idx
        except Exception:
            return None

    def _encode_cursor(idx):
        s = f"idx:{idx}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    started = time.time()
    endpoint = "get-sections"
    limited = _enforce_limits(endpoint, started)
    if limited is not None:
        return limited

    if not isinstance(project_id, str) or re.match(r"^tdst_prj_[A-Za-z0-9]+$", project_id) is None:
