    if limit is None:
        limit_v = 50
    else:
        if not isinstance(limit, int):
            _log(endpoint, "VALIDATION_ERROR", started=started, message="limit must be integer")
            return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
        if limit < 1 or limit > 200:
            _log(endpoint, "VALIDATION_ERROR", started=started, message="limit out of range")
            return _err("VALIDATION_ERROR", "limit out of range (1-200)", field="limit")
        limit_v = limit

    if sort_by is None:
        sort_by_v = "order"
    else:
        if sort_by not in ("order", "name", "created_at", "updated_at"):
            _log(endpoint, "VALIDATION_ERROR", started=started, message="Unsupported sort_by")
            return _err("VALIDATION_ERROR", "sort_by is invalid", field="sort_by")
        sort_by_v = sort_by

    if sort_order is None:
        sort_order_v = "asc"
    else:
        if sort_order not in ("asc", "desc"):
            _log(endpoint, "VALIDATION_ERROR", started=started, message="Unsupported sort_order")
            return _err("VALIDATION_ERROR", "sort_order is invalid", field="sort_order")
        sort_order_v = sort_order

    idx0 = _decode_cursor(cursor)
    if idx0 is None:
        _log(endpoint, "VALIDATION_ERROR", started=started, message="Invalid cursor")
        return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    if not any(isinstance(p, dict) and p.get("id") == project_id for p in projects):
        _log(endpoint, "NOT_FOUND", started=started, message="Project not found")
        return _err("NOT_FOUND", "Project not found", project_id=project_id)

    sections = _load("sections.json")
    if not isinstance(sections, list):
        sections = []

    rows = []
    for r in sections:
        if not isinstance(r, dict):
            continue
        if r.get("project_id") != project_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        rows.append(r)

    reverse = (sort_order_v == "desc")

    def _dt_key(v):
        if not isinstance(v, str):
            return datetime.datetime.min
        try:
            if v.endswith("Z"):
                return datetime.datetime.fromisoformat(v[:-1])
            return datetime.datetime.fromisoformat(v)
        except Exception:
            return datetime.datetime.min

    if sort_by_v in ("created_at", "updated_at"):
        rows.sort(key=lambda r: (_dt_key(r.get(sort_by_v)), str(r.get("id", ""))), reverse=reverse)
    elif sort_by_v == "name":
        rows.sort(key=lambda r: (str(r.get("name", "")).lower(), str(r.get("id", ""))), reverse=reverse)
    else:  # order
        def _order_val(x):
            ov = x.get("order")
            return ov if isinstance(ov, int) else 10**18
        rows.sort(key=lambda r: (_order_val(r), str(r.get("name", "")).lower(), str(r.get("id", ""))), reverse=reverse)

    total = len(rows)
    page = rows[idx0: idx0 + limit_v]
    next_idx = idx0 + len(page)
    has_more = next_idx < total
    next_cursor = _encode_cursor(next_idx) if has_more else None

    _log(endpoint, "OK", started=started, extra={"project_id": project_id, "returned": len(page), "total": total})
    return {
        "sections": page,
        "meta": {
            "project_id": project_id,
            "total": total,
            "limit": limit_v,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by_v,
            "sort_order": sort_order_v,
        },
    }

