            return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
        name_v = name.strip()
    else:
        name_v = None

    if order is not None and not isinstance(order, int):
        _log(endpoint, "VALIDATION_ERROR", started=started, message="order must be integer")
        return _err("VALIDATION_ERROR", "order must be an integer", field="order")

    sections = _load("sections.json")
    if not isinstance(sections, list):
        sections = []

    idx = None
    sec = None
    for i, r in enumerate(sections):
        if isinstance(r, dict) and r.get("id") == section_id:
            idx = i
            sec = r
            break

    if sec is None:
        _log(endpoint, "NOT_FOUND", started=started, message="Section not found")
        return _err("NOT_FOUND", "Section not found", section_id=section_id)

    # Unique(project_id, name) where status <> 'deleted'
    project_id = sec.get("project_id")
    if name_v is not None and sec.get("status") != "deleted":
        for r in sections:
            if not isinstance(r, dict):
                continue
            if r.get("id") == section_id:
                continue
            if r.get("status") == "deleted":
                continue
            if r.get("project_id") == project_id and r.get("name") == name_v:
                _log(endpoint, "CONFLICT", started=started, message="Duplicate section name in project")
                return _err("CONFLICT", "A section with this name already exists in the project", field="name")

    changed = False
    now = _now()
    if name_v is not None and sec.get("name") != name_v:
        sec["name"] = name_v
        changed = True
    if order is not None and sec.get("order") != order:
        # order constraint: NULL OR >= 0
        if order is not None and isinstance(order, int) and order < 0:
            _log(endpoint, "VALIDATION_ERROR", started=started, message="order must be >= 0")
            return _err("VALIDATION_ERROR", "order must be >= 0", field="order")
        sec["order"] = order
        changed = True

    if changed:
        sec["updated_at"] = now
        sections[idx] = sec
        _save("sections.json", sections)

    _log(endpoint, "OK", started=started, extra={"section_id": section_id, "changed": changed})
    return {"section": sec}

def delete_section(section_id, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_s, credential_id=None, message=None, extra=None, started=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now()
        latency_ms = None
        if started is not None:
            latency_ms = int(max(0, (time.time() - started) * 1000))
        row = {
            "id": "rql_" + uuid.uuid4().hex[:24],
            "ts": now,
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": latency_ms,
            "credential_id": credential_id,
        }
        if message is not None:
            row["message"] = message
        if isinstance(extra, dict) and extra:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint, started):
        rl = _load("rate_limits.json")
        if not isinstance(rl, dict):
            rl = {}
        limits = rl.get(endpoint) if isinstance(rl.get(endpoint), dict) else rl.get("default")
        if not isinstance(limits, dict):
            return None
        window_s = limits.get("window_seconds", 60)
        max_req = limits.get("max_requests", None)
        if not isinstance(window_s, int) or window_s <= 0:
            window_s = 60
        if max_req is None:
            return None
        if not isinstance(max_req, int) or max_req <= 0:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s2 = s[:-1]
                    return datetime.datetime.fromisoformat(s2)
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        n = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_ts(r.get("ts"))
            if ts is None:
                continue
            if ts >= cutoff:
                n += 1
        if n >= max_req:
            _log(endpoint, "RATE_LIMIT", started=started, message="Rate limit exceeded")
            return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=window_s)
        return None

    started = time.time()
    endpoint = "delete-section"
    limited = _enforce_limits(endpoint, started)
    if limited is not None:
        return limited

    if not isinstance(section_id, str) or re.match(r"^tdst_sec_[A-Za-z0-9]+$", section_id) is None:
        _log(endpoint, "VALIDATION_ERROR", started=started, message="Invalid section_id format")
        return _err("VALIDATION_ERROR", "section_id is invalid", field="section_id")

    sections = _load("sections.json")
    if not isinstance(sections, list):
        sections = []

    idx = None
    sec = None
    for i, r in enumerate(sections):
        if isinstance(r, dict) and r.get("id") == section_id:
            idx = i
            sec = r
            break

    if sec is None:
        _log(endpoint, "NOT_FOUND", started=started, message="Section not found")
        return _err("NOT_FOUND", "Section not found", section_id=section_id)

    # Idempotent soft-delete: if already deleted, return as-is (but still a successful effect already present).
    if sec.get("status") == "deleted":
        _log(endpoint, "OK", started=started, extra={"section_id": section_id, "already_deleted": True})
        return {"section": sec}

    # Lifecycle transition active -> deleted only
    if sec.get("status") != "active":
        _log(endpoint, "INVALID_TRANSITION", started=started, message="Invalid lifecycle state for delete")
        return _err("INVALID_TRANSITION", "Section cannot be deleted from its current status", status=sec.get("status"))

    now = _now()
    sec["status"] = "deleted"
    sec["deleted_at"] = now
    sec["updated_at"] = now
    sections[idx] = sec
    _save("sections.json", sections)

    _log(endpoint, "OK", started=started, extra={"section_id": section_id, "deleted": True})
    return {"section": sec}

def add_comment(target_type, content, task_id=None, project_id=None, attachment=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "add-comment"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status_s, error=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        row = {
            "id": f"rql_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status_s,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code: row["error_code"] = error_code
        if error: row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    def _gen_id(prefix, existing_rows):
        # 18+ uppercase token derived from time; ensure uniqueness by probing
        base = int(time.time() * 1000)
        candidate = f"{prefix}_{base:013d}{len(existing_rows)+1:06d}".upper()
        existing = {r.get("id") for r in existing_rows if isinstance(r, dict)}
        if candidate not in existing:
            return candidate
        # fallback probe
        for i in range(1, 1000):
            c = f"{prefix}_{base:013d}{len(existing_rows)+1+i:06d}".upper()
            if c not in existing:
                return c
        return f"{prefix}_{base:013d}{int(time.time()*1000000)%1000000:06d}".upper()

    # Validate
    if not isinstance(target_type, str) or target_type not in ("task", "project"):
        e = _err("VALIDATION_ERROR", "Invalid target_type.", field="target_type", allowed=["task", "project"])
        _log("error", e["error"], error_code=e["error"]["code"]); return e
    if not isinstance(content, str) or content.strip() == "":
        e = _err("VALIDATION_ERROR", "content must be a non-empty string.", field="content")
        _log("error", e["error"], error_code=e["error"]["code"]); return e

    # Must specify exactly one target overall AND must align with target_type
    if (task_id is None and project_id is None) or (task_id is not None and project_id is not None):
        e = _err("VALIDATION_ERROR", "Specify exactly one of task_id or project_id.")
        _log("error", e["error"], error_code=e["error"]["code"]); return e

    if task_id is not None:
        if not isinstance(task_id, str) or not re.match(r"^tdst_tsk_[0-9A-Z]{18,}$", task_id):
            e = _err("VALIDATION_ERROR", "task_id is malformed.", field="task_id")
            _log("error", e["error"], error_code=e["error"]["code"]); return e
        if target_type != "task":
            e = _err("VALIDATION_ERROR", "task_id provided but target_type is not 'task'.", field="target_type")
            _log("error", e["error"], error_code=e["error"]["code"]); return e
    if project_id is not None:
        if not isinstance(project_id, str) or not re.match(r"^tdst_prj_[0-9A-Z]{18,}$", project_id):
            e = _err("VALIDATION_ERROR", "project_id is malformed.", field="project_id")
            _log("error", e["error"], error_code=e["error"]["code"]); return e
        if target_type != "project":
            e = _err("VALIDATION_ERROR", "project_id provided but target_type is not 'project'.", field="target_type")
            _log("error", e["error"], error_code=e["error"]["code"]); return e
    if attachment is not None and not isinstance(attachment, dict):
        e = _err("VALIDATION_ERROR", "attachment must be an object.", field="attachment")
        _log("error", e["error"], error_code=e["error"]["code"]); return e

    # Validate target existence (NOT_FOUND if missing)
    if target_type == "task":
        tasks = _load("tasks.json")
        if not isinstance(tasks, list): tasks = []
        if not any(isinstance(t, dict) and t.get("id") == task_id for t in tasks):
            e = _err("NOT_FOUND", "Task not found.", field="task_id")
            _log("error", e["error"], error_code=e["error"]["code"]); return e
    else:
        projects = _load("projects.json")
        if not isinstance(projects, list): projects = []
        if not any(isinstance(p, dict) and p.get("id") == project_id for p in projects):
            e = _err("NOT_FOUND", "Project not found.", field="project_id")
            _log("error", e["error"], error_code=e["error"]["code"]); return e

    comments = _load("comments.json")
    if not isinstance(comments, list): comments = []

    now = _now_iso()
    new_row = {
        "id": _gen_id("tdst_cmt", comments),
        "todoist_comment_id": _gen_id("todoist_cmt", comments),
        "target_type": target_type,
        "task_id": task_id if target_type == "task" else None,
        "project_id": project_id if target_type == "project" else None,
        "content": content,
        "attachment": attachment,
        "posted_by": None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }

    comments.append(new_row)
    _save("comments.json", comments)
    _log("ok")
    return {"comment": new_row}

