def get_comments(target_type, task_id=None, project_id=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-comments"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status_s, error=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        row = {
            "id": f"rql_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status_s,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code: row["error_code"] = error_code
        if error: row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_cursor(cur):
        if cur in (None, ""):
            return 0, None
        if not isinstance(cur, str):
            return None, _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("offset:"):
                return None, _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            off = int(s.split(":", 1)[1])
            if off < 0:
                return None, _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            return off, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

    def _make_cursor(off):
        return base64.urlsafe_b64encode(f"offset:{off}".encode("utf-8")).decode("utf-8").rstrip("=")

    # Validate
    if not isinstance(target_type, str) or target_type not in ("task", "project"):
        e = _err("VALIDATION_ERROR", "Invalid target_type.", field="target_type", allowed=["task", "project"])
        _log("error", e["error"], error_code=e["error"]["code"]); return e

    # Allow caller to pass extra ids; enforce rules rather than rejecting for "both passed" in a list endpoint:
    # required id depends on target_type; other id must be None or ignored.
    if target_type == "task":
        if task_id is None:
            e = _err("VALIDATION_ERROR", "task_id is required when target_type='task'.", field="task_id")
            _log("error", e["error"], error_code=e["error"]["code"]); return e
        if not isinstance(task_id, str) or not re.match(r"^tdst_tsk_[0-9A-Z]{18,}$", task_id):
            e = _err("VALIDATION_ERROR", "task_id is malformed.", field="task_id")
            _log("error", e["error"], error_code=e["error"]["code"]); return e
    else:
        if project_id is None:
            e = _err("VALIDATION_ERROR", "project_id is required when target_type='project'.", field="project_id")
            _log("error", e["error"], error_code=e["error"]["code"]); return e
        if not isinstance(project_id, str) or not re.match(r"^tdst_prj_[0-9A-Z]{18,}$", project_id):
            e = _err("VALIDATION_ERROR", "project_id is malformed.", field="project_id")
            _log("error", e["error"], error_code=e["error"]["code"]); return e

    if status is not None and (not isinstance(status, str) or status not in ("active", "deleted")):
        e = _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=["active", "deleted"])
        _log("error", e["error"], error_code=e["error"]["code"]); return e
    if limit is not None:
        if not isinstance(limit, int):
            e = _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
            _log("error", e["error"], error_code=e["error"]["code"]); return e
        if limit < 1 or limit > 200:
            e = _err("VALIDATION_ERROR", "limit out of range.", field="limit", minimum=1, maximum=200)
            _log("error", e["error"], error_code=e["error"]["code"]); return e
    if sort is not None and (not isinstance(sort, str) or sort not in ("created_at", "-created_at")):
        e = _err("VALIDATION_ERROR", "Invalid sort.", field="sort", allowed=["created_at", "-created_at"])
        _log("error", e["error"], error_code=e["error"]["code"]); return e

    off, ce = _parse_cursor(cursor)
    if ce:
        _log("error", ce["error"], error_code=ce["error"]["code"]); return ce

    # Ensure target exists (NOT_FOUND if missing)
    if target_type == "task":
        tasks = _load("tasks.json")
        if not isinstance(tasks, list): tasks = []
        if not any(isinstance(t, dict) and t.get("id") == task_id for t in tasks):
            e = _err("NOT_FOUND", "Task not found.", field="task_id")
            _log("error", e["error"], error_code=e["error"]["code"]); return e
    else:
        projects = _load("projects.json")
        if not isinstance(projects, list): projects = []
        if not any(isinstance(p, dict) and p.get("id") == project_id for p in projects):
            e = _err("NOT_FOUND", "Project not found.", field="project_id")
            _log("error", e["error"], error_code=e["error"]["code"]); return e

    comments = _load("comments.json")
    if not isinstance(comments, list): comments = []

    rows = []
    for c in comments:
        if not isinstance(c, dict): continue
        if c.get("target_type") != target_type: continue
        if target_type == "task":
            if c.get("task_id") != task_id: continue
        else:
            if c.get("project_id") != project_id: continue
        if status is not None and c.get("status") != status: continue
        rows.append(c)

    reverse = (sort or "-created_at") == "-created_at"

    def _parse_dt(ts):
        if not isinstance(ts, str) or not ts: return None
        s = ts
        if s.endswith("Z"): s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except Exception:
            return None
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    rows.sort(key=lambda r: _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), reverse=reverse)

    total = len(rows)
    lim = limit if isinstance(limit, int) else 50
    page = rows[off:off + lim]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    _log("ok")
    return {"comments": page, "total": total, "limit": lim, "has_more": has_more, "next_cursor": next_cursor}

