        if not isinstance(comment_id, str) or not re.match(r"^tdst_cmt_[0-9A-Z]{18,}$", comment_id):
            err = _err("VALIDATION_ERROR", "comment_id is malformed.")
            _log("error", err["error"])
            return err

        if content is None and attachment is None:
            err = _err("VALIDATION_ERROR", "No updatable fields provided. Provide content and/or attachment.")
            _log("error", err["error"])
            return err

        if content is not None:
            if not isinstance(content, str) or content.strip() == "":
                err = _err("VALIDATION_ERROR", "content must be a non-empty string when provided.")
                _log("error", err["error"])
                return err

        comments = _load("comments.json")
        idx = None
        for i, c in enumerate(comments):
            if c.get("id") == comment_id:
                idx = i
                break
        if idx is None:
            err = _err("NOT_FOUND", "Comment not found.")
            _log("error", err["error"])
            return err

        c = comments[idx]

        # Cannot update deleted comment
        if c.get("status") == "deleted":
            err = _err("CONFLICT", "Cannot update a deleted comment.")
            _log("error", err["error"])
            return err

        # Visibility: ensure target exists and not deleted
        if c.get("target_type") == "task":
            tasks = _load("tasks.json")
            t = next((x for x in tasks if x.get("id") == c.get("task_id")), None)
            if not t or t.get("status") == "deleted":
                err = _err("NOT_FOUND", "Comment not found.")
                _log("error", err["error"])
                return err
        elif c.get("target_type") == "project":
            projects = _load("projects.json")
            p = next((x for x in projects if x.get("id") == c.get("project_id")), None)
            if not p or p.get("status") == "deleted":
                err = _err("NOT_FOUND", "Comment not found.")
                _log("error", err["error"])
                return err
        else:
            err = _err("CONFLICT", "Stored comment has invalid target_type.")
            _log("error", err["error"])
            return err

        changed = False
        if content is not None and content != c.get("content"):
            c["content"] = content
            changed = True
        if attachment is not None:
            # attachment is opaque; update even if equal structurally not checked
            c["attachment"] = attachment
            changed = True

        if not changed:
            # No success without effect
            err = _err("CONFLICT", "Update had no effect.")
            _log("error", err["error"])
            return err

        c["updated_at"] = _iso_now()
        comments[idx] = c
        _save("comments.json", comments)

        _log("ok")
        return {"comment": c}
    except Exception as e:
        err = _err("CONFLICT", "Internal error.", detail=str(e))
        _log("error", err["error"])
        return err

