def get_task_comments(task_id, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # ---- usage/audit log (best-effort if file exists in schema-less store) ----
    def _append_audit(status_code, credential_id=None):
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                rows.append(
                    {
                        "id": "req_" + hashlib.sha256(f"{now}|get-task-comments|{task_id}|{time.time()}".encode("utf-8")).hexdigest()[:24],
                        "endpoint": "get-task-comments",
                        "credential_id": credential_id,
                        "status": status_code,
                        "latency_ms": int((time.time() - t0) * 1000),
                        "timestamp": now,
                    }
                )
                _save(fname, rows)
                return

    # ---- validation ----
    if not isinstance(task_id, str) or not re.match(r"^tdst_tsk_[0-9A-Z]{18,}$", task_id):
        _append_audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid task_id.", field="task_id")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            _append_audit("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _append_audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid limit; must be between 1 and 200.", field="limit")

    if sort is None:
        sort = "-created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "-created_at"):
        _append_audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported sort.", field="sort")

    if cursor is not None and not isinstance(cursor, str):
        _append_audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    # ---- load required references ----
    tasks = _load("tasks.json")
    task = next((t for t in tasks if t.get("id") == task_id), None)
    if not task:
        _append_audit("NOT_FOUND")
        return _err("NOT_FOUND", "Task not found.", task_id=task_id)

    # visibility/access: no explicit auth in this service; treat as authorized if task exists
    comments = _load("comments.json")

    # ---- cursor decode/encode ----
    def _decode_cursor(c):
        if not c:
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            if obj.get("v") != 1 or obj.get("endpoint") != "get-task-comments":
                return None
            if obj.get("task_id") != task_id:
                return None
            after = obj.get("after")
            if after is None:
                return None
            if not isinstance(after, str):
                return None
            return after
        except Exception:
            return None

    def _encode_cursor(after):
        obj = {"v": 1, "endpoint": "get-task-comments", "task_id": task_id, "after": after}
        b = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    after_id = _decode_cursor(cursor)
    if cursor is not None and after_id is None:
        _append_audit("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    # ---- filter ----
    rows = [
        c
        for c in comments
        if c.get("target_type") == "task" and c.get("task_id") == task_id
    ]
    if status is not None:
        rows = [c for c in rows if c.get("status") == status]

    # ---- sort ----
    def _dt_key(x):
        v = x.get("created_at")
        return v if isinstance(v, str) else ""

    reverse = sort.startswith("-")
    rows.sort(key=_dt_key, reverse=reverse)

    # ---- paginate using "after id" in sorted order ----
    start = 0
    if after_id is not None:
        idx = next((i for i, r in enumerate(rows) if r.get("id") == after_id), None)
        if idx is None:
            _append_audit("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Cursor does not match current result set.", field="cursor")
        start = idx + 1

    page = rows[start : start + limit]
    has_more = (start + limit) < len(rows)
    next_cursor = _encode_cursor(page[-1].get("id")) if (has_more and page) else None

    _append_audit("OK")
    return {
        "comments": page,
        "task_id": task_id,
        "meta": {
            "limit": limit,
            "sort": sort,
            "total": len(rows),
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

