        _log("error", e["error"], error_code=e["error"]["code"]); return e
    if not isinstance(label_id, str) or not re.match(r"^tdst_lbl_[0-9A-Z]{18,}$", label_id):
        e = _err("VALIDATION_ERROR", "label_id is malformed.", field="label_id")
        _log("error", e["error"], error_code=e["error"]["code"]); return e

    tasks = _load("tasks.json")
    labels = _load("labels.json")
    if not isinstance(tasks, list): tasks = []
    if not isinstance(labels, list): labels = []

    task_idx = None
    for i, t in enumerate(tasks):
        if isinstance(t, dict) and t.get("id") == task_id:
            task_idx = i; break
    if task_idx is None:
        e = _err("NOT_FOUND", "Task not found.")
        _log("error", e["error"], error_code=e["error"]["code"]); return e

    label_row = next((l for l in labels if isinstance(l, dict) and l.get("id") == label_id), None)
    if label_row is None or label_row.get("status") != "active":
        e = _err("NOT_FOUND", "Label not found.")
        _log("error", e["error"], error_code=e["error"]["code"]); return e

