    if not isinstance(task, dict):
        e = _err("CONFLICT", "Corrupt task row.")
        _log("error", e["error"], error_code=e["error"]["code"]); return e
    if task.get("status") == "deleted":
        e = _err("INVALID_TRANSITION", "Cannot modify a deleted task.")
