def delete_label(label_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete-label"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status_s, error=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        row = {
            "id": f"rql_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status_s,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code: row["error_code"] = error_code
        if error: row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(label_id, str) or not re.match(r"^tdst_lbl_[0-9A-Z]{19,}$", label_id):
        e = _err("VALIDATION_ERROR", "label_id is malformed.", field="label_id")
        _log("error", e["error"], error_code=e["error"]["code"]); return e

    labels = _load("labels.json")
    tasks = _load("tasks.json")
    if not isinstance(labels, list): labels = []
    if not isinstance(tasks, list): tasks = []

    l_idx = None
    for i, l in enumerate(labels):
        if isinstance(l, dict) and l.get("id") == label_id:
            l_idx = i; break
    if l_idx is None:
        e = _err("NOT_FOUND", "Label not found.")
        _log("error", e["error"], error_code=e["error"]["code"]); return e

    label = labels[l_idx]
    if not isinstance(label, dict):
        e = _err("CONFLICT", "Corrupt label row.")
        _log("error", e["error"], error_code=e["error"]["code"]); return e

    # Idempotent: already removed => still ensure label removed from tasks
    now = _now_iso()
    if label.get("status") != "removed":
        # lifecycle transition active -> removed only
        if label.get("status") not in ("active", "removed"):
            e = _err("INVALID_TRANSITION", "Invalid label lifecycle state.", field="status")
            _log("error", e["error"], error_code=e["error"]["code"]); return e
        if label.get("status") == "active":
            label["status"] = "removed"
            label["deleted_at"] = now
            label["updated_at"] = now
            labels[l_idx] = label

    # Remove label id from all tasks.labels (same transaction semantics: persist both)
    changed_tasks = False
    for i, t in enumerate(tasks):
        if not isinstance(t, dict): continue
        tl = t.get("labels")
        if not isinstance(tl, list) or not tl:
            continue
        if label_id in tl:
            t["labels"] = [x for x in tl if x != label_id]
            t["updated_at"] = now
            tasks[i] = t
            changed_tasks = True

    # Persist
    _save("labels.json", labels)
    if changed_tasks:
        _save("tasks.json", tasks)

    _log("ok")
    return {"label": label}

