    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, status, credential=None, **meta):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "ts": _now(),
                "endpoint": endpoint,
                "credential": credential,
                "status": status,
                "meta": meta,
            }
        )
        _save("request_log.json", logs)

    # Validate id
    if not isinstance(label_id, str):
        _log("update-label", "VALIDATION_ERROR", reason="label_id_type")
        return _err("VALIDATION_ERROR", "label_id must be a string.")
    if not re.match(r"^tdst_lbl_[0-9A-Z]{19,}$", label_id or ""):
        _log("update-label", "VALIDATION_ERROR", reason="label_id_format")
        return _err("VALIDATION_ERROR", "label_id is malformed.")

    # Validate fields
    if name is not None and (not isinstance(name, str) or name.strip() == ""):
        _log("update-label", "VALIDATION_ERROR", reason="name_invalid")
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    if color is not None and not isinstance(color, str):
        _log("update-label", "VALIDATION_ERROR", reason="color_type")
        return _err("VALIDATION_ERROR", "color must be a string.")
    if is_favorite is not None and not isinstance(is_favorite, bool):
        _log("update-label", "VALIDATION_ERROR", reason="is_favorite_type")
        return _err("VALIDATION_ERROR", "is_favorite must be a boolean.")

    labels = _load("labels.json")
    if not isinstance(labels, list):
        _log("update-label", "UNAUTHORIZED", reason="datastore_unreadable")
        return _err("UNAUTHORIZED", "Caller cannot manage labels.")

    idx = None
    for i, r in enumerate(labels):
        if isinstance(r, dict) and r.get("id") == label_id:
            idx = i
            break
    if idx is None:
        _log("update-label", "NOT_FOUND", label_id=label_id)
        return _err("NOT_FOUND", "Label not found.")

    row = labels[idx]

    # Cannot update removed label
    if row.get("status") == "removed":
        _log("update-label", "CONFLICT", label_id=label_id, current_status=row.get("status"))
        return _err("CONFLICT", "Cannot update a removed label.", current_status="removed")

    if row.get("status") != "active":
        _log("update-label", "CONFLICT", label_id=label_id, current_status=row.get("status"))
        return _err("CONFLICT", "Label is not in an updatable state.", current_status=row.get("status"))

    # Enforce uniqueness of lower(name) among active labels (schema constraint)
    if name is not None:
        ln = name.strip().lower()
        for r in labels:
            if not isinstance(r, dict):
                continue
            if r.get("id") == label_id:
                continue
            if r.get("status") == "active" and isinstance(r.get("name"), str) and r["name"].lower() == ln:
                _log("update-label", "CONFLICT", label_id=label_id, conflict_with=r.get("id"))
                return _err("CONFLICT", "An active label with the same name already exists.", conflict_with=r.get("id"))

    # Apply updates (idempotent)
    changed = False
    now = _now()
    if name is not None:
        new_name = name.strip()
        if row.get("name") != new_name:
            row["name"] = new_name
            changed = True
    if color is not None:
        if row.get("color") != color:
            row["color"] = color
            changed = True
    if is_favorite is not None:
        if row.get("is_favorite") != is_favorite:
            row["is_favorite"] = is_favorite
            changed = True

    if not changed:
        # Still a successful read-after-write style response; effect is none but state already matches request.
        _log("update-label", "OK", label_id=label_id, idempotent=True, changed=False)
        return {"label": row}

    row["updated_at"] = now
    labels[idx] = row
    _save("labels.json", labels)
    _log("update-label", "OK", label_id=label_id, changed=True)
    return {"label": row}

