def get_labels(status=None, is_favorite=None, is_shared=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, status_s, credential=None, **meta):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "ts": _now(),
                "endpoint": endpoint,
                "credential": credential,
                "status": status_s,
                "meta": meta,
            }
        )
        _save("request_log.json", logs)

    def _parse_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or c == "":
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                return None
            off = int(raw.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _make_cursor(off):
        raw = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8")

    # Validate filters
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "removed"):
            _log("get-labels", "VALIDATION_ERROR", reason="status_invalid")
            return _err("VALIDATION_ERROR", "status must be one of: active, removed.")
    if is_favorite is not None and not isinstance(is_favorite, bool):
        _log("get-labels", "VALIDATION_ERROR", reason="is_favorite_type")
        return _err("VALIDATION_ERROR", "is_favorite must be a boolean.")
    if is_shared is not None and not isinstance(is_shared, bool):
        _log("get-labels", "VALIDATION_ERROR", reason="is_shared_type")
        return _err("VALIDATION_ERROR", "is_shared must be a boolean.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log("get-labels", "VALIDATION_ERROR", reason="limit_type")
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 200:
        _log("get-labels", "VALIDATION_ERROR", reason="limit_range")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")

    if sort is None:
        sort = "name"
    if order is None:
        order = "asc"
    if not isinstance(sort, str) or sort not in ("name", "created_at", "updated_at"):
        _log("get-labels", "VALIDATION_ERROR", reason="sort_invalid")
        return _err("VALIDATION_ERROR", "sort must be one of: name, created_at, updated_at.")
    if not isinstance(order, str) or order not in ("asc", "desc"):
        _log("get-labels", "VALIDATION_ERROR", reason="order_invalid")
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc.")

    off = _parse_cursor(cursor)
    if off is None:
        _log("get-labels", "VALIDATION_ERROR", reason="cursor_invalid")
        return _err("VALIDATION_ERROR", "cursor is invalid.")

    labels = _load("labels.json")
    if not isinstance(labels, list):
        _log("get-labels", "UNAUTHORIZED", reason="datastore_unreadable")
        return _err("UNAUTHORIZED", "Caller cannot access labels.")

    # Filter
    out = []
    for r in labels:
        if not isinstance(r, dict):
            continue
        if status is not None and r.get("status") != status:
            continue
        if is_favorite is not None and r.get("is_favorite") is not is_favorite:
            continue
        if is_shared is not None and r.get("is_shared") is not is_shared:
            continue
        out.append(r)

    # Sort
    reverse = (order == "desc")

    def _key(r):
        v = r.get(sort)
        if sort == "name":
            return ("" if v is None else str(v).lower(), str(r.get("id") or ""))
        # timestamps are iso strings; None sorts last in asc, first in desc (stabilize)
        if v is None:
            return ("9999-12-31T23:59:59.999999+00:00" if not reverse else "", str(r.get("id") or ""))
        return (str(v), str(r.get("id") or ""))

    out.sort(key=_key, reverse=reverse)

    total = len(out)
    page = out[off : off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    _log(
        "get-labels",
        "OK",
        status_filter=status,
        is_favorite=is_favorite,
        is_shared=is_shared,
        limit=limit,
        offset=off,
        returned=len(page),
        total=total,
        has_more=has_more,
    )
    return {
        "labels": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
        },
    }

def get_shared_labels(shared_origin=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-shared-labels"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status_s, error=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        row = {
            "id": f"rql_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status_s,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code: row["error_code"] = error_code
        if error: row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_cursor(cur):
        if cur in (None, ""):
            return 0, None
        if not isinstance(cur, str):
            return None, _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("offset:"):
                return None, _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            off = int(s.split(":", 1)[1])
            if off < 0:
                return None, _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            return off, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

    def _make_cursor(off):
        return base64.urlsafe_b64encode(f"offset:{off}".encode("utf-8")).decode("utf-8").rstrip("=")

    # Validate
    if shared_origin is not None and (not isinstance(shared_origin, str) or shared_origin not in ("name", "id", "unknown")):
        e = _err("VALIDATION_ERROR", "Invalid shared_origin.", field="shared_origin", allowed=["name", "id", "unknown"])
        _log("error", e["error"], error_code=e["error"]["code"]); return e
    if limit is not None:
        if not isinstance(limit, int):
            e = _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
            _log("error", e["error"], error_code=e["error"]["code"]); return e
        if limit < 1 or limit > 200:
            e = _err("VALIDATION_ERROR", "limit out of range.", field="limit", minimum=1, maximum=200)
            _log("error", e["error"], error_code=e["error"]["code"]); return e
    if sort is not None and (not isinstance(sort, str) or sort not in ("name", "created_at", "updated_at")):
        e = _err("VALIDATION_ERROR", "Invalid sort.", field="sort", allowed=["name", "created_at", "updated_at"])
        _log("error", e["error"], error_code=e["error"]["code"]); return e
    if order is not None and (not isinstance(order, str) or order not in ("asc", "desc")):
        e = _err("VALIDATION_ERROR", "Invalid order.", field="order", allowed=["asc", "desc"])
        _log("error", e["error"], error_code=e["error"]["code"]); return e

    off, ce = _parse_cursor(cursor)
    if ce:
        _log("error", ce["error"], error_code=ce["error"]["code"]); return ce

    labels = _load("labels.json")
    if not isinstance(labels, list): labels = []

    rows = []
    for l in labels:
        if not isinstance(l, dict): continue
        if l.get("is_shared") is not True: continue
        if l.get("status") != "active": continue
        if shared_origin is not None and l.get("shared_origin") != shared_origin: continue
        rows.append(l)

    sb = sort or "updated_at"
    so = order or "desc"

    def _parse_dt(ts):
        if not isinstance(ts, str) or not ts: return None
        s = ts
        if s.endswith("Z"): s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except Exception:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _sort_key(r):
        if sb in ("created_at", "updated_at"):
            return _parse_dt(r.get(sb)) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (r.get("name") or "").lower()

    rows.sort(key=_sort_key, reverse=(so == "desc"))

    total = len(rows)
    lim = limit if isinstance(limit, int) else 50
    page = rows[off:off + lim]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    _log("ok")
    return {"labels": page, "total": total, "limit": lim, "has_more": has_more, "next_cursor": next_cursor}

def remove_shared_label(label_id, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
           	    return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _record(endpoint, status, detail=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": "rql_" + hashlib.sha256(f"{endpoint}|{_now_iso()}|{os.getpid()}".encode("utf-8")).hexdigest()[:24],
                "endpoint": endpoint,
                "status": status,
                "detail": detail,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
            })
            _save("request_logs.json", logs)

    # validation
    if not isinstance(label_id, str) or not re.match(r"^tdst_lbl_[0-9A-Z]{19,}$", label_id):
        out = _err("VALIDATION_ERROR", "label_id is malformed.")
        _record("remove-shared-label", "VALIDATION_ERROR", out["error"]["message"])
        return out

    # ambient auth (best-effort)
    auth_ok = True
    accounts = _load("accounts.json")
    workspaces = _load("workspaces.json")
    if isinstance(accounts, list) and isinstance(workspaces, list) and (accounts or workspaces):
        auth_ok = any((a.get("status") in (None, "active") for a in accounts if isinstance(a, dict))) or \
                  any((w.get("status") in (None, "active") for w in workspaces if isinstance(w, dict)))
    if not auth_ok:
        out = _err("UNAUTHORIZED", "Not authorized to manage shared labels.")
        _record("remove-shared-label", "UNAUTHORIZED", out["error"]["message"])
        return out

    labels = _load("labels.json")
    tasks = _load("tasks.json")
    if not isinstance(labels, list):
        labels = []
    if not isinstance(tasks, list):
        tasks = []

    idx = None
    for i, r in enumerate(labels):
        if isinstance(r, dict) and r.get("id") == label_id:
            idx = i
            break
    if idx is None:
        out = _err("NOT_FOUND", "Shared label not found.")
        _record("remove-shared-label", "NOT_FOUND", out["error"]["message"])
        return out

    lab = labels[idx]
    if lab.get("is_shared") is not True:
        out = _err("NOT_FOUND", "Shared label not found.")
        _record("remove-shared-label", "NOT_FOUND", out["error"]["message"])
        return out

    # idempotent removal: if already removed, no further side effects.
    if lab.get("status") == "removed":
        _record("remove-shared-label", "ok", None)
        return {"shared_label": lab, "meta": {"idempotent": True}}

    # transition active -> removed only
    if lab.get("status") != "active":
        out = _err("INVALID_TRANSITION", "Label cannot be removed from its current state.", from_status=lab.get("status"), to_status="removed")
        _record("remove-shared-label", "INVALID_TRANSITION", out["error"]["message"])
        return out

    # remove label id from all tasks.labels atomically with label status update
    changed_tasks = 0
    for t in tasks:
        if not isinstance(t, dict):
            continue
        lbls = t.get("labels")
        if isinstance(lbls, list) and label_id in lbls:
            t["labels"] = [x for x in lbls if x != label_id]
            t["updated_at"] = _now_iso()
            # update filter cache tokens if present (best-effort)
            toks = t.get("filter_cache_tokens")
            if isinstance(toks, list):
                t["filter_cache_tokens"] = [tok for tok in toks if not (isinstance(tok, str) and tok.lower() in (f"@{lab.get('name','')}".lower(), f"label:{label_id}".lower()))]
            changed_tasks += 1

    lab["status"] = "removed"
    lab["deleted_at"] = _now_iso()
    lab["updated_at"] = lab["deleted_at"]
    labels[idx] = lab

    _save("tasks.json", tasks)
    _save("labels.json", labels)

    _record("remove-shared-label", "ok", None)
    return {"shared_label": lab, "meta": {"tasks_updated": changed_tasks}}

