            break
    if idx is None:
        out = _err("NOT_FOUND", "Shared label not found.")
        _record("rename-shared-label", "NOT_FOUND", out["error"]["message"])
        return out

    lab = labels[idx]
    if lab.get("is_shared") is not True or lab.get("status") != "active":
        # per business rule: only shared & active are renameable; removed should be conflict
        if lab.get("is_shared") is not True:
            out = _err("NOT_FOUND", "Shared label not found.")
            _record("rename-shared-label", "NOT_FOUND", out["error"]["message"])
            return out
        if lab.get("status") == "removed":
            out = _err("CONFLICT", "Label is removed and cannot be renamed.")
            _record("rename-shared-label", "CONFLICT", out["error"]["message"])
            return out
        out = _err("CONFLICT", "Label is not renameable in its current state.", status=lab.get("status"))
        _record("rename-shared-label", "CONFLICT", out["error"]["message"])
        return out

    # uniqueness of lower(name) among active labels
    target_lower = new_name.casefold()
    for r in labels:
        if not isinstance(r, dict):
            continue
        if r.get("status") != "active":
            continue
        if r.get("id") == label_id:
            continue
        nm = r.get("name")
        if isinstance(nm, str) and nm.casefold() == target_lower:
            out = _err("CONFLICT", "An active label with the same name already exists.")
            _record("rename-shared-label", "CONFLICT", out["error"]["message"])
            return out

    # idempotent: same name -> no change but return updated record
    if isinstance(lab.get("name"), str) and lab.get("name") == new_name:
        _record("rename-shared-label", "ok", None)
        return {"shared_label": lab, "meta": {"idempotent": True}}

    lab["name"] = new_name
    lab["updated_at"] = _now_iso()
    labels[idx] = lab
    _save("labels.json", labels)

    _record("rename-shared-label", "ok", None)
    return {"shared_label": lab}

def sync_todoist_domain(todoist_access_token, sync_mode=None, since=None, include_deleted=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _record(endpoint, status, detail=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": "rql_" + hashlib.sha256(f"{endpoint}|{_now_iso()}|{os.getpid()}".encode("utf-8")).hexdigest()[:24],
                "endpoint": endpoint,
                "status": status,
                "detail": detail,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
            })
            _save("request_logs.json", logs)

    def _enforce_limits():
        limits = _load("limits.json")
        if not isinstance(limits, dict):
            return None
        ep = "sync-todoist-domain"
        conf = limits.get(ep) or limits.get("default") or {}
        rpm = conf.get("rpm")
        daily = conf.get("daily")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.now(datetime.timezone.utc)
        if isinstance(rpm, int) and rpm > 0:
            cutoff = now - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                try:
                    ts = r.get("timestamp")
                    if not ts:
                        continue
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    if dt >= cutoff and r.get("endpoint") == ep:
                        c += 1
                except Exception:
                    continue
            if c >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(daily, int) and daily > 0:
            cutoff = now - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                try:
                    ts = r.get("timestamp")
                    if not ts:
                        continue
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    if dt >= cutoff and r.get("endpoint") == ep:
                        c += 1
                except Exception:
                    continue
            if c >= daily:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    # validation
    if not isinstance(todoist_access_token, str) or todoist_access_token.strip() == "":
        out = _err("VALIDATION_ERROR", "todoist_access_token is required.")
        _record("sync-todoist-domain", "VALIDATION_ERROR", out["error"]["message"])
        return out

    if sync_mode is None:
        sync_mode = "incremental"
    if not isinstance(sync_mode, str) or sync_mode not in ("full", "incremental"):
        out = _err("VALIDATION_ERROR", "Invalid sync_mode. Must be one of: full, incremental.")
        _record("sync-todoist-domain", "VALIDATION_ERROR", out["error"]["message"])
        return out

    since_dt = None
    if since is not None:
        if not isinstance(since, str):
            out = _err("VALIDATION_ERROR", "since must be an RFC3339 date-time string.")
            _record("sync-todoist-domain", "VALIDATION_ERROR", out["error"]["message"])
            return out
        try:
            since_dt = datetime.datetime.fromisoformat(since.replace("Z", "+00:00"))
            if since_dt.tzinfo is None:
                since_dt = since_dt.replace(tzinfo=datetime.timezone.utc)
            else:
                since_dt = since_dt.astimezone(datetime.timezone.utc)
        except Exception:
            out = _err("VALIDATION_ERROR", "since must be an RFC3339 date-time string.")
            _record("sync-todoist-domain", "VALIDATION_ERROR", out["error"]["message"])
            return out
    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        out = _err("VALIDATION_ERROR", "include_deleted must be a boolean.")
        _record("sync-todoist-domain", "VALIDATION_ERROR", out["error"]["message"])
        return out

    lim_err = _enforce_limits()
    if lim_err:
        _record("sync-todoist-domain", lim_err["error"]["code"], lim_err["error"]["message"])
        return lim_err

    # authenticate token against a token store if present; otherwise accept as "valid" only if a context exists.
    tokens = _load("todoist_tokens.json")
    token_row = None
    if isinstance(tokens, list) and tokens:
        for r in tokens:
            if not isinstance(r, dict):
                continue
            if r.get("access_token") == todoist_access_token or r.get("id") == todoist_access_token:
                if r.get("status") in (None, "active"):
                    token_row = r
                    break
        if token_row is None:
            out = _err("UNAUTHORIZED", "Todoist access token is missing or invalid.")
            _record("sync-todoist-domain", "UNAUTHORIZED", out["error"]["message"])
            return out
    else:
        # no explicit token store; require any ambient auth context to exist if such files exist
        accounts = _load("accounts.json")
        workspaces = _load("workspaces.json")
        if (isinstance(accounts, list) and accounts) or (isinstance(workspaces, list) and workspaces):
            auth_ok = any((a.get("status") in (None, "active") for a in accounts if isinstance(a, dict))) or \
                      any((w.get("status") in (None, "active") for w in workspaces if isinstance(w, dict)))
            if not auth_ok:
                out = _err("UNAUTHORIZED", "Todoist access token is missing or invalid.")
                _record("sync-todoist-domain", "UNAUTHORIZED", out["error"]["message"])
                return out
        # else: accept (offline simulator)

    # Offline server: no upstream calls possible. Implement "sync" as an upsert of staged upstream payload if present.
    staged = _load("todoist_staged_sync.json")
    if not isinstance(staged, dict):
        staged = {}

    # If incremental: apply a time filter to staged items where possible (using updated_at-like fields).
    def _parse_dt(x):
        try:
            if isinstance(x, str) and x:
                d = datetime.datetime.fromisoformat(x.replace("Z", "+00:00"))
                if d.tzinfo is None:
                    d = d.replace(tzinfo=datetime.timezone.utc)
                return d.astimezone(datetime.timezone.utc)
        except Exception:
            return None
        return None

    def _gen_id(prefix):
        return prefix + hashlib.sha256(f"{prefix}|{_now_iso()}|{os.getpid()}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]

    # load local collections
    projects = _load("projects.json");  projects = projects if isinstance(projects, list) else []
    sections = _load("sections.json");  sections = sections if isinstance(sections, list) else []
    tasks = _load("tasks.json");        tasks = tasks if isinstance(tasks, list) else []
    labels = _load("labels.json");      labels = labels if isinstance(labels, list) else []
    comments = _load("comments.json");  comments = comments if isinstance(comments, list) else []

    # index by todoist_*_id for idempotent upsert
    idx_proj = {r.get("todoist_project_id"): i for i, r in enumerate(projects) if isinstance(r, dict) and r.get("todoist_project_id")}
    idx_sect = {r.get("todoist_section_id"): i for i, r in enumerate(sections) if isinstance(r, dict) and r.get("todoist_section_id")}
    idx_task = {r.get("todoist_task_id"): i for i, r in enumerate(tasks) if isinstance(r, dict) and r.get("todoist_task_id")}
    idx_label = {r.get("todoist_label_id"): i for i, r in enumerate(labels) if isinstance(r, dict) and r.get("todoist_label_id")}
    idx_comment = {r.get("todoist_comment_id"): i for i, r in enumerate(comments) if isinstance(r, dict) and r.get("todoist_comment_id")}

    # helpers to validate FK references inside staged payload using todoist ids to map to internal
    def _find_project_internal(todoist_project_id):
        i = idx_proj.get(todoist_project_id)
        if i is None:
            return None
        return projects[i].get("id")

    def _find_section_internal(todoist_section_id):
        i = idx_sect.get(todoist_section_id)
        if i is None:
            return None
        return sections[i].get("id")

    def _summary_init():
        return {"created": 0, "updated": 0, "unchanged": 0}

    summary = {
        "projects": _summary_init(),
        "sections": _summary_init(),
        "tasks": _summary_init(),
        "labels": _summary_init(),
        "comments": _summary_init(),
    }

    # Apply staged payload
    # Supported staged keys: projects, sections, tasks, labels, comments. Each list item should contain relevant todoist ids.
    def _should_apply(obj):
        if sync_mode == "full" or since_dt is None:
            return True
        u = _parse_dt(obj.get("updated_at") or obj.get("synced_at") or obj.get("created_at"))
        if u is None:
            return True
        return u >= since_dt

    now = _now_iso()

    # Projects
    for p in staged.get("projects", []) if isinstance(staged.get("projects", []), list) else []:
        if not isinstance(p, dict) or not _should_apply(p):
            continue
        tpid = p.get("todoist_project_id")
        if not isinstance(tpid, str) or tpid == "":
            continue
        existing_i = idx_proj.get(tpid)
        desired_status = p.get("status", "active")
        if desired_status not in ("active", "archived", "deleted"):
            desired_status = "active"
        if desired_status == "deleted" and not include_deleted:
            continue

        if existing_i is None:
            # enforce unique(todoist_project_id) by construction
            row = {
                "id": _gen_id("tdst_prj_"),
                "todoist_project_id": tpid,
                "name": str(p.get("name") or "").strip(),
                "color": p.get("color"),
                "parent_project_id": None,
                "is_favorite": bool(p.get("is_favorite")) if p.get("is_favorite") is not None else False,
                "view_style": p.get("view_style") if p.get("view_style") in ("list", "board", "calendar", "unknown") else None,
                "collaborators": p.get("collaborators") if isinstance(p.get("collaborators"), list) else [],
                "status": desired_status,
                "created_at": now,
                "updated_at": now,
                "deleted_at": now if desired_status == "deleted" else None
            }
            if row["name"] == "":
                continue
            # parent_project_id via todoist id mapping (optional)
            parent_tpid = p.get("parent_todoist_project_id")
            if isinstance(parent_tpid, str) and parent_tpid:
                row["parent_project_id"] = _find_project_internal(parent_tpid)
            projects.append(row)
            idx_proj[tpid] = len(projects) - 1
            summary["projects"]["created"] += 1
        else:
            row = projects[existing_i]
            before = json.dumps(row, sort_keys=True, ensure_ascii=False)
            # update mutable fields
            if isinstance(p.get("name"), str) and p.get("name").strip():
                row["name"] = p.get("name").strip()
            if "color" in p:
                row["color"] = p.get("color")
            if "is_favorite" in p and isinstance(p.get("is_favorite"), bool):
                row["is_favorite"] = p.get("is_favorite")
            if "view_style" in p and (p.get("view_style") in ("list", "board", "calendar", "unknown") or p.get("view_style") is None):
                row["view_style"] = p.get("view_style")
            if isinstance(p.get("collaborators"), list):
                row["collaborators"] = p.get("collaborators")
            # status transition enforce
            cur = row.get("status")
            if desired_status != cur:
                allowed = {"active": {"archived", "deleted"}, "archived": {"active", "deleted"}, "deleted": set()}
                if desired_status in allowed.get(cur, set()):
                    row["status"] = desired_status
                    if desired_status == "deleted":
                        row["deleted_at"] = row.get("deleted_at") or now
                    else:
                        row["deleted_at"] = None
                # illegal transitions from deleted ignored (idempotent safety)
            row["updated_at"] = now
            projects[existing_i] = row
            after = json.dumps(row, sort_keys=True, ensure_ascii=False)
            if after == before:
                summary["projects"]["unchanged"] += 1
            else:
                summary["projects"]["updated"] += 1

    # Sections
    for s in staged.get("sections", []) if isinstance(staged.get("sections", []), list) else []:
        if not isinstance(s, dict) or not _should_apply(s):
            continue
        tsid = s.get("todoist_section_id")
        tpid = s.get("todoist_project_id")
        if not isinstance(tsid, str) or tsid == "" or not isinstance(tpid, str) or tpid == "":
            continue
        project_internal = _find_project_internal(tpid)
        if project_internal is None:
            continue
        desired_status = s.get("status", "active")
        if desired_status not in ("active", "deleted"):
            desired_status = "active"
        if desired_status == "deleted" and not include_deleted:
            continue

        existing_i = idx_sect.get(tsid)
        if existing_i is None:
            nm = str(s.get("name") or "").strip()
            if nm == "":
                continue
            # uniqueness(project_id, name) where status <> deleted
            conflict = any(isinstance(r, dict) and r.get("project_id") == project_internal and r.get("status") != "deleted" and (r.get("name") or "") == nm for r in sections)
            if conflict:
                continue
            row = {
                "id": _gen_id("tdst_sec_"),
                "todoist_section_id": tsid,
                "project_id": project_internal,
                "name": nm,
                "order": s.get("order") if isinstance(s.get("order"), int) and s.get("order") >= 0 else None,
                "status": desired_status,
                "created_at": now,
                "updated_at": now,
                "deleted_at": now if desired_status == "deleted" else None
            }
            sections.append(row)
            idx_sect[tsid] = len(sections) - 1
            summary["sections"]["created"] += 1
        else:
            row = sections[existing_i]
            before = json.dumps(row, sort_keys=True, ensure_ascii=False)
            # update
            nm = s.get("name")
            if isinstance(nm, str) and nm.strip():
                nm = nm.strip()
                # uniqueness constraint
                conflict = any(isinstance(r, dict) and r.get("id") != row.get("id") and r.get("project_id") == row.get("project_id") and r.get("status") != "deleted" and (r.get("name") or "") == nm for r in sections)
                if not conflict:
                    row["name"] = nm
            # project move not supported here (keep FK stable)
            if "order" in s:
                if s.get("order") is None or (isinstance(s.get("order"), int) and s.get("order") >= 0):
                    row["order"] = s.get("order")
            cur = row.get("status")
            if desired_status != cur:
                allowed = {"active": {"deleted"}, "deleted": set()}
                if desired_status in allowed.get(cur, set()):
                    row["status"] = desired_status
                    row["deleted_at"] = now if desired_status == "deleted" else None
            row["updated_at"] = now
            sections[existing_i] = row
            after = json.dumps(row, sort_keys=True, ensure_ascii=False)
            if after == before:
                summary["sections"]["unchanged"] += 1
            else:
                summary["sections"]["updated"] += 1

    # Labels
    for l in staged.get("labels", []) if isinstance(staged.get("labels", []), list) else []:
        if not isinstance(l, dict) or not _should_apply(l):
            continue
        tlid = l.get("todoist_label_id")
        nm = str(l.get("name") or "").strip()
        if nm == "":
            continue
        desired_status = l.get("status", "active")
        if desired_status not in ("active", "removed"):
            desired_status = "active"
        if desired_status == "removed" and not include_deleted:
            continue
        is_shared = bool(l.get("is_shared")) if l.get("is_shared") is not None else False

        # If todoist_label_id absent, treat as a shared label addressed by name; upsert by lower(name) for shared only.
        existing_i = None
        if isinstance(tlid, str) and tlid:
            existing_i = idx_label.get(tlid)
        elif is_shared:
            for i, r in enumerate(labels):
                if isinstance(r, dict) and r.get("status") == "active" and isinstance(r.get("name"), str) and r.get("name").casefold() == nm.casefold() and r.get("is_shared") is True:
                    existing_i = i
                    break

        if existing_i is None:
            # enforce unique(lower(name)) where status=active
            if desired_status == "active":
                if any(isinstance(r, dict) and r.get("status") == "active" and isinstance(r.get("name"), str) and r.get("name").casefold() == nm.casefold() for r in labels):
                    continue
            row = {
                "id": _gen_id("tdst_lbl_").upper(),  # match pattern often used in tools (uppercase base)
                "todoist_label_id": tlid if isinstance(tlid, str) and tlid else None,
                "name": nm,
                "color": l.get("color"),
                "is_favorite": bool(l.get("is_favorite")) if l.get("is_favorite") is not None else False,
                "is_shared": is_shared,
                "shared_origin": l.get("shared_origin") if l.get("shared_origin") in ("name", "id", "unknown") else (("name" if is_shared and not tlid else "id") if is_shared else None),
                "status": desired_status,
                "created_at": now,
                "updated_at": now,
                "deleted_at": now if desired_status == "removed" else None
            }
            labels.append(row)
            if isinstance(tlid, str) and tlid:
                idx_label[tlid] = len(labels) - 1
            summary["labels"]["created"] += 1
        else:
            row = labels[existing_i]
            before = json.dumps(row, sort_keys=True, ensure_ascii=False)
            # rename/update fields; enforce uniqueness for active labels if changing name
            if nm and nm != row.get("name"):
                if row.get("status") == "active":
                    if any(isinstance(r, dict) and r.get("id") != row.get("id") and r.get("status") == "active" and isinstance(r.get("name"), str) and r.get("name").casefold() == nm.casefold() for r in labels):
                        nm = row.get("name")
                row["name"] = nm
            if "color" in l:
                row["color"] = l.get("color")
            if "is_favorite" in l and isinstance(l.get("is_favorite"), bool):
                row["is_favorite"] = l.get("is_favorite")
            if "is_shared" in l and isinstance(l.get("is_shared"), bool):
                row["is_shared"] = l.get("is_shared")
            if "shared_origin" in l and (l.get("shared_origin") in ("name", "id", "unknown") or l.get("shared_origin") is None):
                row["shared_origin"] = l.get("shared_origin")
            cur = row.get("status")
            if desired_status != cur:
                allowed = {"active": {"removed"}, "removed": set()}
                if desired_status in allowed.get(cur, set()):
                    row["status"] = desired_status
                    row["deleted_at"] = now if desired_status == "removed" else None
            row["updated_at"] = now
            labels[existing_i] = row
            after = json.dumps(row, sort_keys=True, ensure_ascii=False)
            if after == before:
                summary["labels"]["unchanged"] += 1
            else:
                summary["labels"]["updated"] += 1

    # Projects/Sections mapping for tasks
    def _label_internal_ids_from_todoist(todoist_label_ids):
        if not isinstance(todoist_label_ids, list):
            return []
        out_ids = []
        for tlid in todoist_label_ids:
            if not isinstance(tlid, str) or not tlid:
                continue
            i = idx_label.get(tlid)
            if i is not None and isinstance(labels[i], dict):
                out_ids.append(labels[i].get("id"))
        return [x for x in out_ids if isinstance(x, str) and x]

    # Tasks
    for t in staged.get("tasks", []) if isinstance(staged.get("tasks", []), list) else []:
        if not isinstance(t, dict) or not _should_apply(t):
            continue
        ttid = t.get("todoist_task_id")
        tpid = t.get("todoist_project_id")
        if not isinstance(ttid, str) or ttid == "" or not isinstance(tpid, str) or tpid == "":
            continue
        project_internal = _find_project_internal(tpid)
        if project_internal is None:
            continue
        desired_status = t.get("status", "active")
        if desired_status not in ("active", "completed", "deleted"):
            desired_status = "active"
        if desired_status == "deleted" and not include_deleted:
            continue

        existing_i = idx_task.get(ttid)
        content = str(t.get("content") or "").strip()
        if content == "":
            continue

        # due_date parsing
        due_dt = _parse_dt(t.get("due_date")) if "due_date" in t else None
        deadline_dt = _parse_dt(t.get("deadline_date")) if "deadline_date" in t else None
        completed_at = _parse_dt(t.get("completed_at")) if "completed_at" in t else None

        priority = t.get("priority")
        if not isinstance(priority, int) or not (1 <= priority <= 4):
            priority = 1

        section_internal = None
        if isinstance(t.get("todoist_section_id"), str) and t.get("todoist_section_id"):
            section_internal = _find_section_internal(t.get("todoist_section_id"))
            # section must belong to the same project
            if section_internal is not None:
                try:
                    sec_row = next((s for s in sections if isinstance(s, dict) and s.get("id") == section_internal), None)
                    if not sec_row or sec_row.get("project_id") != project_internal or sec_row.get("status") == "deleted":
                        section_internal = None
                except Exception:
                    section_internal = None

        if existing_i is None:
            row = {
                "id": _gen_id("tdst_tsk_"),
                "todoist_task_id": ttid,
                "project_id": project_internal,
                "section_id": section_internal,
                "parent_task_id": None,  # parent linking by todoist id not implemented in offline staged
                "content": content,
                "description": t.get("description") if isinstance(t.get("description"), str) else None,
                "priority": priority,
                "labels": _label_internal_ids_from_todoist(t.get("todoist_label_ids")),
                "due_date": due_dt.isoformat() if due_dt else None,
                "due_date_text": t.get("due_date_text") if isinstance(t.get("due_date_text"), str) else None,
                "due_timezone": t.get("due_timezone") if isinstance(t.get("due_timezone"), str) else None,
                "deadline_date": deadline_dt.isoformat() if deadline_dt else None,
                "deadline_lang": t.get("deadline_lang") if isinstance(t.get("deadline_lang"), str) else None,
                "duration_amount": t.get("duration_amount") if isinstance(t.get("duration_amount"), int) and t.get("duration_amount") > 0 else None,
                "duration_unit": t.get("duration_unit") if t.get("duration_unit") in ("minute", "day") else None,
                "created_by_quick_add": False,
                "quick_add_raw_text": None,
                "filter_cache_tokens": t.get("filter_cache_tokens") if isinstance(t.get("filter_cache_tokens"), list) else [],
                "status": desired_status,
                "completed_at": (completed_at.isoformat() if completed_at else now) if desired_status == "completed" else None,
                "created_at": now,
                "updated_at": now,
                "deleted_at": now if desired_status == "deleted" else None
            }
            tasks.append(row)
            idx_task[ttid] = len(tasks) - 1
            summary["tasks"]["created"] += 1
        else:
            row = tasks[existing_i]
            before = json.dumps(row, sort_keys=True, ensure_ascii=False)
            # update fields
            row["content"] = content
            if "description" in t:
                row["description"] = t.get("description") if isinstance(t.get("description"), str) else None
            row["priority"] = priority
            if "todoist_label_ids" in t:
                row["labels"] = _label_internal_ids_from_todoist(t.get("todoist_label_ids"))
            if "due_date" in t:
                row["due_date"] = due_dt.isoformat() if due_dt else None
            if "due_date_text" in t:
                row["due_date_text"] = t.get("due_date_text") if isinstance(t.get("due_date_text"), str) else None
            if "due_timezone" in t:
                row["due_timezone"] = t.get("due_timezone") if isinstance(t.get("due_timezone"), str) else None
            if "deadline_date" in t:
                row["deadline_date"] = deadline_dt.isoformat() if deadline_dt else None
            if "deadline_lang" in t:
                row["deadline_lang"] = t.get("deadline_lang") if isinstance(t.get("deadline_lang"), str) else None
            if "duration_amount" in t:
                row["duration_amount"] = t.get("duration_amount") if isinstance(t.get("duration_amount"), int) and t.get("duration_amount") > 0 else None
            if "duration_unit" in t:
                row["duration_unit"] = t.get("duration_unit") if t.get("duration_unit") in ("minute", "day") else None
            if "filter_cache_tokens" in t and isinstance(t.get("filter_cache_tokens"), list):
                row["filter_cache_tokens"] = t.get("filter_cache_tokens")
            # keep project/section in sync if provided
            row["project_id"] = project_internal
            row["section_id"] = section_internal

            # status transition (avoid illegal transitions from deleted)
            cur = row.get("status")
            if desired_status != cur:
                allowed = {"active": {"completed", "deleted"}, "completed": {"active", "deleted"}, "deleted": set()}
                if desired_status in allowed.get(cur, set()):
                    row["status"] = desired_status
                    if desired_status == "completed":
                        row["completed_at"] = completed_at.isoformat() if completed_at else (row.get("completed_at") or now)
                        row["deleted_at"] = None
                    elif desired_status == "active":
                        row["completed_at"] = None
                        row["deleted_at"] = None
                    elif desired_status == "deleted":
                        row["deleted_at"] = row.get("deleted_at") or now
                        # do not force completed_at clearing
            # if status is completed ensure completed_at present
            if row.get("status") == "completed" and not row.get("completed_at"):
                row["completed_at"] = now
            if row.get("status") != "completed":
                row["completed_at"] = None if row.get("status") == "active" else row.get("completed_at")

            row["updated_at"] = now
            tasks[existing_i] = row
            after = json.dumps(row, sort_keys=True, ensure_ascii=False)
            if after == before:
                summary["tasks"]["unchanged"] += 1
            else:
                summary["tasks"]["updated"] += 1

    # Comments
    for c in staged.get("comments", []) if isinstance(staged.get("comments", []), list) else []:
        if not isinstance(c, dict) or not _should_apply(c):
            continue
        tcid = c.get("todoist_comment_id")
        if not isinstance(tcid, str) or tcid == "":
            continue
        target_type = c.get("target_type")
        if target_type not in ("task", "project"):
            continue
        desired_status = c.get("status", "active")
        if desired_status not in ("active", "deleted"):
            desired_status = "active"
        if desired_status == "deleted" and not include_deleted:
            continue
        content = str(c.get("content") or "").strip()
        if content == "":
            continue

        task_internal = None
        proj_internal = None
        if target_type == "task":
            ttid = c.get("todoist_task_id")
            if isinstance(ttid, str) and ttid and ttid in idx_task:
                task_internal = tasks[idx_task[ttid]].get("id")
            if not task_internal:
                continue
        else:
            tpid = c.get("todoist_project_id")
            if isinstance(tpid, str) and tpid and tpid in idx_proj:
                proj_internal = projects[idx_proj[tpid]].get("id")
            if not proj_internal:
                continue

        existing_i = idx_comment.get(tcid)
        if existing_i is None:
            row = {
                "id": _gen_id("tdst_cmt_"),
                "todoist_comment_id": tcid,
                "target_type": target_type,
                "task_id": task_internal,
                "project_id": proj_internal,
                "content": content,
                "attachment": c.get("attachment") if isinstance(c.get("attachment"), dict) else None,
                "posted_by": c.get("posted_by") if isinstance(c.get("posted_by"), dict) else None,
                "status": desired_status,
                "created_at": now,
                "updated_at": now,
                "deleted_at": now if desired_status == "deleted" else None
            }
            comments.append(row)
            idx_comment[tcid] = len(comments) - 1
            summary["comments"]["created"] += 1
        else:
            row = comments[existing_i]
            before = json.dumps(row, sort_keys=True, ensure_ascii=False)
            row["content"] = content
            if "attachment" in c:
                row["attachment"] = c.get("attachment") if isinstance(c.get("attachment"), dict) else None
            if "posted_by" in c:
                row["posted_by"] = c.get("posted_by") if isinstance(c.get("posted_by"), dict) else None
            cur = row.get("status")
            if desired_status != cur:
                allowed = {"active": {"deleted"}, "deleted": set()}
                if desired_status in allowed.get(cur, set()):
                    row["status"] = desired_status
                    row["deleted_at"] = now if desired_status == "deleted" else None
            row["updated_at"] = now
            comments[existing_i] = row
            after = json.dumps(row, sort_keys=True, ensure_ascii=False)
            if after == before:
                summary["comments"]["unchanged"] += 1
            else:
                summary["comments"]["updated"] += 1

    # Persist all
    _save("projects.json", projects)
    _save("sections.json", sections)
    _save("tasks.json", tasks)
    _save("labels.json", labels)
    _save("comments.json", comments)

    # Update sync state if file exists
    sync_state = _load("sync_state.json")
    if isinstance(sync_state, dict):
        sync_state["last_sync_at"] = now
        sync_state["last_sync_mode"] = sync_mode
        _save("sync_state.json", sync_state)

    out = {
        "summary": summary,
        "meta": {
            "sync_mode": sync_mode,
            "since": since,
            "include_deleted": include_deleted,
            "last_sync_at": now
        }
    }
    _record("sync-todoist-domain", "ok", None)
    return out

def upsert_task(todoist_access_token, todoist_task_id, project_id, section_id=None, parent_task_id=None, content=None, description=None, priority=None, label_ids=None, due_date=None, due_date_text=None, due_timezone=None, deadline_date=None, deadline_lang=None, duration_amount=None, duration_unit=None, created_by_quick_add=None, quick_add_raw_text=None, status=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(status_code, credential_value, endpoint, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential": credential_value,
            "status": status_code,
            "timestamp": _now,
            "latency_ms": int((time.time() - _t0) * 1000),
            "detail": detail
        })
        _save("request_logs.json", logs)

    def _find_credential(token):
        creds = _load("credentials.json")
        if not isinstance(creds, list):
            creds = []
        for r in creds:
            if isinstance(r, dict) and (r.get("id") == token or r.get("access_token") == token or r.get("token") == token or r.get("value") == token):
                # optionally require active if such a field exists
                if "status" in r and r.get("status") not in (None, "active", "enabled"):
                    continue
                return r
        return None

    def _enforce_limits(cred_id):
        # Simple default: 60 req/min per credential, 10k req/day per credential.
        # Uses request_logs.json; if absent, treated as empty.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.utcnow()
        win_start = now_dt - datetime.timedelta(seconds=60)
        day_start = datetime.datetime(now_dt.year, now_dt.month, now_dt.day)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s2 = s[:-1]
                    return datetime.datetime.fromisoformat(s2)
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("credential") != cred_id:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= win_start:
                per_min += 1
            if ts >= day_start:
                per_day += 1

        if per_min >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded (60 requests/minute).", limit_per_minute=60, used_in_window=per_min)
        if per_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded (10000 requests/day).", quota_per_day=10000, used_today=per_day)
        return None

    cred = _find_credential(todoist_access_token)
    if cred is None:
        _audit(401, todoist_access_token, "upsert-task", "unauthorized")
        return _err("UNAUTHORIZED", "Invalid or unknown todoist_access_token.")

    lim_err = _enforce_limits(cred.get("id", todoist_access_token))
    if lim_err:
        _audit(429, cred.get("id", todoist_access_token), "upsert-task", lim_err["error"]["code"])
        return lim_err

    # ---- validations ----
    if not isinstance(todoist_task_id, str) or not todoist_task_id.strip():
        _audit(400, cred.get("id", todoist_access_token), "upsert-task", "bad todoist_task_id")
        return _err("VALIDATION_ERROR", "todoist_task_id must be a non-empty string.")
    if not isinstance(project_id, str):
        _audit(400, cred.get("id", todoist_access_token), "upsert-task", "bad project_id")
        return _err("VALIDATION_ERROR", "project_id must be a string.")
    if not re.match(r"^tdst_prj_[0-9A-Z]{18,}$", project_id):
        _audit(400, cred.get("id", todoist_access_token), "upsert-task", "project_id pattern")
        return _err("VALIDATION_ERROR", "project_id is malformed.", field="project_id")

    if section_id is not None:
        if not isinstance(section_id, str) or not re.match(r"^tdst_sec_[0-9A-Z]{18,}$", section_id):
            _audit(400, cred.get("id", todoist_access_token), "upsert-task", "section_id pattern")
            return _err("VALIDATION_ERROR", "section_id is malformed.", field="section_id")

    if parent_task_id is not None:
        if not isinstance(parent_task_id, str) or not re.match(r"^tdst_tsk_[0-9A-Z]{18,}$", parent_task_id):
            _audit(400, cred.get("id", todoist_access_token), "upsert-task", "parent_task_id pattern")
            return _err("VALIDATION_ERROR", "parent_task_id is malformed.", field="parent_task_id")

    if content is None or not isinstance(content, str) or not content.strip():
        _audit(400, cred.get("id", todoist_access_token), "upsert-task", "content empty")
        return _err("VALIDATION_ERROR", "content must be a non-empty string.", field="content")

    if description is not None and not isinstance(description, str):
        _audit(400, cred.get("id", todoist_access_token), "upsert-task", "description type")
        return _err("VALIDATION_ERROR", "description must be a string if provided.", field="description")

    if priority is not None:
        if not isinstance(priority, int) or isinstance(priority, bool) or priority < 1 or priority > 4:
            _audit(400, cred.get("id", todoist_access_token), "upsert-task", "priority range")
            return _err("VALIDATION_ERROR", "priority must be an integer between 1 and 4.", field="priority")

    if label_ids is not None:
        if not isinstance(label_ids, list):
            _audit(400, cred.get("id", todoist_access_token), "upsert-task", "label_ids type")
            return _err("VALIDATION_ERROR", "label_ids must be an array of strings.", field="label_ids")
        for lid in label_ids:
            if not isinstance(lid, str) or not re.match(r"^tdst_lbl_[0-9A-Z]{18,}$", lid):
                _audit(400, cred.get("id", todoist_access_token), "upsert-task", "label_id pattern")
                return _err("VALIDATION_ERROR", "label_ids contains a malformed label id.", field="label_ids", value=lid)

    def _parse_date_yyyy_mm_dd(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be a string in YYYY-MM-DD format.", field=field)
        try:
            d = datetime.date.fromisoformat(s)
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be a valid date in YYYY-MM-DD format.", field=field)
        # store as UTC midnight ISO datetime for date-only fields
        dt = datetime.datetime(d.year, d.month, d.day, 0, 0, 0)
        return dt.isoformat() + "Z"

    due_dt = _parse_date_yyyy_mm_dd(due_date, "due_date")
    if isinstance(due_dt, dict) and "error" in due_dt:
        _audit(400, cred.get("id", todoist_access_token), "upsert-task", "due_date parse")
        return due_dt
    deadline_dt = _parse_date_yyyy_mm_dd(deadline_date, "deadline_date")
    if isinstance(deadline_dt, dict) and "error" in deadline_dt:
        _audit(400, cred.get("id", todoist_access_token), "upsert-task", "deadline_date parse")
        return deadline_dt

    if due_date_text is not None and not isinstance(due_date_text, str):
        _audit(400, cred.get("id", todoist_access_token), "upsert-task", "due_date_text type")
        return _err("VALIDATION_ERROR", "due_date_text must be a string.", field="due_date_text")
    if due_timezone is not None and not isinstance(due_timezone, str):
        _audit(400, cred.get("id", todoist_access_token), "upsert-task", "due_timezone type")
        return _err("VALIDATION_ERROR", "due_timezone must be a string.", field="due_timezone")

    if deadline_lang is not None and not isinstance(deadline_lang, str):
        _audit(400, cred.get("id", todoist_access_token), "upsert-task", "deadline_lang type")
        return _err("VALIDATION_ERROR", "deadline_lang must be a string.", field="deadline_lang")

    if duration_amount is not None:
        if not isinstance(duration_amount, int) or isinstance(duration_amount, bool) or duration_amount < 1:
            _audit(400, cred.get("id", todoist_access_token), "upsert-task", "duration_amount range")
            return _err("VALIDATION_ERROR", "duration_amount must be an integer >= 1.", field="duration_amount")
    if duration_unit is not None:
        if not isinstance(duration_unit, str) or duration_unit not in ("minute", "day"):
            _audit(400, cred.get("id", todoist_access_token), "upsert-task", "duration_unit enum")
            return _err("VALIDATION_ERROR", "duration_unit must be 'minute' or 'day'.", field="duration_unit")

    if (duration_amount is None) ^ (duration_unit is None):
        _audit(400, cred.get("id", todoist_access_token), "upsert-task", "duration pair")
        return _err("VALIDATION_ERROR", "duration_amount and duration_unit must be provided together.", field="duration_amount")

    if created_by_quick_add is not None and not isinstance(created_by_quick_add, bool):
        _audit(400, cred.get("id", todoist_access_token), "upsert-task", "created_by_quick_add type")
        return _err("VALIDATION_ERROR", "created_by_quick_add must be boolean.", field="created_by_quick_add")
    if quick_add_raw_text is not None and not isinstance(quick_add_raw_text, str):
        _audit(400, cred.get("id", todoist_access_token), "upsert-task", "quick_add_raw_text type")
        return _err("VALIDATION_ERROR", "quick_add_raw_text must be a string.", field="quick_add_raw_text")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "completed", "deleted"):
            _audit(400, cred.get("id", todoist_access_token), "upsert-task", "status enum")
            return _err("VALIDATION_ERROR", "status must be one of: active, completed, deleted.", field="status")

    # ---- reference checks ----
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if proj is None:
        _audit(404, cred.get("id", todoist_access_token), "upsert-task", "project not found")
        return _err("NOT_FOUND", "Referenced project_id not found.", field="project_id")
    if proj.get("status") == "deleted":
        _audit(409, cred.get("id", todoist_access_token), "upsert-task", "project deleted")
        return _err("CONFLICT", "Cannot attach task to a deleted project.", field="project_id")

    sections = _load("sections.json")
    if not isinstance(sections, list):
        sections = []
    sec = None
    if section_id is not None:
        sec = next((s for s in sections if isinstance(s, dict) and s.get("id") == section_id), None)
        if sec is None:
            _audit(404, cred.get("id", todoist_access_token), "upsert-task", "section not found")
            return _err("NOT_FOUND", "Referenced section_id not found.", field="section_id")
        if sec.get("status") == "deleted":
            _audit(409, cred.get("id", todoist_access_token), "upsert-task", "section deleted")
            return _err("CONFLICT", "Cannot attach task to a deleted section.", field="section_id")
        if sec.get("project_id") != project_id:
            _audit(409, cred.get("id", todoist_access_token), "upsert-task", "section project mismatch")
            return _err("CONFLICT", "section_id must belong to the same project_id.", field="section_id")

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []

    parent = None
    if parent_task_id is not None:
        parent = next((t for t in tasks if isinstance(t, dict) and t.get("id") == parent_task_id), None)
        if parent is None:
            _audit(404, cred.get("id", todoist_access_token), "upsert-task", "parent not found")
            return _err("NOT_FOUND", "Referenced parent_task_id not found.", field="parent_task_id")
        if parent.get("status") == "deleted":
            _audit(409, cred.get("id", todoist_access_token), "upsert-task", "parent deleted")
            return _err("CONFLICT", "Cannot assign a deleted parent_task_id.", field="parent_task_id")
        # reasonable constraint: parent should be in same project
        if parent.get("project_id") != project_id:
            _audit(409, cred.get("id", todoist_access_token), "upsert-task", "parent project mismatch")
            return _err("CONFLICT", "parent_task_id must belong to the same project_id.", field="parent_task_id")

    labels = _load("labels.json")
    if not isinstance(labels, list):
        labels = []
    if label_ids is not None:
        label_set = {l.get("id") for l in labels if isinstance(l, dict) and l.get("status") == "active"}
        for lid in label_ids:
            if lid not in label_set:
                _audit(404, cred.get("id", todoist_access_token), "upsert-task", "label not found")
                return _err("NOT_FOUND", "Referenced label id not found or not active.", field="label_ids", value=lid)

    # ---- upsert ----
    existing = next((t for t in tasks if isinstance(t, dict) and t.get("todoist_task_id") == todoist_task_id), None)

    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex[:24].upper()

    def _compute_filter_tokens(row):
        toks = set()
        pr = row.get("priority")
        if isinstance(pr, int):
            toks.add(f"p{pr}")
        pid = row.get("project_id")
        if isinstance(pid, str) and pid:
            toks.add("project:" + pid)
        lbs = row.get("labels") or []
        if isinstance(lbs, list):
            for lid in lbs:
                if isinstance(lid, str) and lid:
                    toks.add("@"+lid)
        # due tokens: today / overdue (based on UTC date)
        dd = row.get("due_date")
        if isinstance(dd, str) and dd:
            try:
                s = dd[:-1] if dd.endswith("Z") else dd
                dt = datetime.datetime.fromisoformat(s)
                due_d = dt.date()
                today = datetime.datetime.utcnow().date()
                if due_d == today:
                    toks.add("today")
                if due_d < today:
                    toks.add("overdue")
            except Exception:
                pass
        return sorted(toks)

    # Validate lifecycle transitions if status is being set/changed
    def _check_transition(old, new):
        transitions = {
            "active": {"completed", "deleted"},
            "completed": {"active", "deleted"},
            "deleted": set()
        }
        if old == new:
            return True
        return new in transitions.get(old, set())

    if existing is None:
        # create
        new_status = status if status is not None else "active"
        if new_status == "completed":
            completed_at = _now
        else:
            completed_at = None
        if new_status == "deleted":
            deleted_at = _now
        else:
            deleted_at = None

        row = {
            "id": _gen_id("tdst_tsk_"),
            "todoist_task_id": todoist_task_id,
            "project_id": project_id,
            "section_id": section_id,
            "parent_task_id": parent_task_id,
            "content": content,
            "description": description,
            "priority": priority if priority is not None else 1,
            "labels": label_ids if label_ids is not None else [],
            "due_date": due_dt,
            "due_date_text": due_date_text,
            "due_timezone": due_timezone,
            "deadline_date": deadline_dt,
            "deadline_lang": deadline_lang,
            "duration_amount": duration_amount,
            "duration_unit": duration_unit,
            "created_by_quick_add": created_by_quick_add if created_by_quick_add is not None else False,
            "quick_add_raw_text": quick_add_raw_text,
            "filter_cache_tokens": [],
            "status": new_status,
            "completed_at": completed_at,
            "created_at": _now,
            "updated_at": _now,
            "deleted_at": deleted_at
        }
        # enforce constraints
        if not (1 <= row["priority"] <= 4):
            _audit(400, cred.get("id", todoist_access_token), "upsert-task", "priority constraint")
            return _err("VALIDATION_ERROR", "priority must be between 1 and 4.", field="priority")
        if row["duration_amount"] is not None and row["duration_amount"] <= 0:
            _audit(400, cred.get("id", todoist_access_token), "upsert-task", "duration_amount constraint")
            return _err("VALIDATION_ERROR", "duration_amount must be > 0.", field="duration_amount")
        if row["duration_unit"] is not None and row["duration_unit"] not in ("minute", "day"):
            _audit(400, cred.get("id", todoist_access_token), "upsert-task", "duration_unit constraint")
            return _err("VALIDATION_ERROR", "duration_unit invalid.", field="duration_unit")
        if (row["completed_at"] is None) != (row["status"] != "completed"):
            # completed => completed_at not null ; not completed => completed_at null
            if row["status"] == "completed" and row["completed_at"] is None:
                _audit(400, cred.get("id", todoist_access_token), "upsert-task", "completed_at required")
                return _err("VALIDATION_ERROR", "completed tasks must have completed_at.")
            if row["status"] != "completed" and row["completed_at"] is not None:
                row["completed_at"] = None

        row["filter_cache_tokens"] = _compute_filter_tokens(row)
        tasks.append(row)
        _save("tasks.json", tasks)
        _audit(200, cred.get("id", todoist_access_token), "upsert-task", "created")
        return {"task": row}
    else:
        # update existing
        old_status = existing.get("status")
        new_status = status if status is not None else old_status

        if not isinstance(old_status, str) or old_status not in ("active", "completed", "deleted"):
            # repair invalid stored state safely
            old_status = "active"

        if not _check_transition(old_status, new_status):
            _audit(409, cred.get("id", todoist_access_token), "upsert-task", "invalid transition")
            return _err("INVALID_TRANSITION", f"Illegal status transition from {old_status} to {new_status}.", from_status=old_status, to_status=new_status)

        # apply field updates (full replacement for label_ids)
        existing["project_id"] = project_id
        existing["section_id"] = section_id
        existing["parent_task_id"] = parent_task_id
        existing["content"] = content
        if description is not None:
            existing["description"] = description
        if priority is not None:
            existing["priority"] = priority
        if label_ids is not None:
            existing["labels"] = label_ids
        existing["due_date"] = due_dt
        if due_date_text is not None:
            existing["due_date_text"] = due_date_text
        if due_timezone is not None:
            existing["due_timezone"] = due_timezone
        existing["deadline_date"] = deadline_dt
        if deadline_lang is not None:
            existing["deadline_lang"] = deadline_lang
        existing["duration_amount"] = duration_amount
        existing["duration_unit"] = duration_unit
        if created_by_quick_add is not None:
            existing["created_by_quick_add"] = created_by_quick_add
        if quick_add_raw_text is not None:
            existing["quick_add_raw_text"] = quick_add_raw_text

        # status bookkeeping
        if old_status != new_status:
            existing["status"] = new_status
            if new_status == "completed":
                existing["completed_at"] = _now
                existing["deleted_at"] = None
            elif new_status == "active":
                existing["completed_at"] = None
                existing["deleted_at"] = None
            elif new_status == "deleted":
                existing["deleted_at"] = _now
                # keep completed_at as-is? enforce constraints: deleted may keep completed_at but status != completed implies completed_at must be null per constraints.
                existing["completed_at"] = None
        else:
            # enforce constraints around completed_at/status consistency
            if existing.get("status") == "completed" and not existing.get("completed_at"):
                existing["completed_at"] = _now
            if existing.get("status") != "completed":
                existing["completed_at"] = None
            if existing.get("status") != "deleted":
                existing["deleted_at"] = None
            elif not existing.get("deleted_at"):
                existing["deleted_at"] = _now

        # validate remaining constraints
        if not isinstance(existing.get("priority"), int) or not (1 <= existing["priority"] <= 4):
            _audit(400, cred.get("id", todoist_access_token), "upsert-task", "priority constraint (update)")
            return _err("VALIDATION_ERROR", "priority must be between 1 and 4.", field="priority")
        if existing.get("duration_amount") is not None and existing["duration_amount"] <= 0:
            _audit(400, cred.get("id", todoist_access_token), "upsert-task", "duration_amount constraint (update)")
            return _err("VALIDATION_ERROR", "duration_amount must be > 0.", field="duration_amount")
        if existing.get("duration_unit") is not None and existing["duration_unit"] not in ("minute", "day"):
            _audit(400, cred.get("id", todoist_access_token), "upsert-task", "duration_unit constraint (update)")
            return _err("VALIDATION_ERROR", "duration_unit invalid.", field="duration_unit")
        if existing.get("status") == "completed" and not existing.get("completed_at"):
            _audit(400, cred.get("id", todoist_access_token), "upsert-task", "completed_at required (update)")
            return _err("VALIDATION_ERROR", "completed tasks must have completed_at.")

        existing["filter_cache_tokens"] = _compute_filter_tokens(existing)
        existing["updated_at"] = _now

        _save("tasks.json", tasks)
        _audit(200, cred.get("id", todoist_access_token), "upsert-task", "updated")
        return {"task": existing}

def get_whoami(todoist_access_token, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0165000" if __import__("os").path.isdir("./environment_mix/0165000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- request logging / quota & rate limit enforcement (best-effort if collections exist) ---
    def _append_log(status, credential=None, meta=None):
        meta = meta or {}
        for fname in ("request_log.json", "requests.json", "audit_log.json", "usage.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                if not isinstance(rows, list):
                    rows = []
                rows.append({
                    "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                    "endpoint": "get-whoami",
                    "credential": credential,
                    "status": status,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": now,
                    "meta": meta
                })
                _save(fname, rows)
                break

    if not isinstance(todoist_access_token, str) or not todoist_access_token.strip():
        _append_log("VALIDATION_ERROR", meta={"field": "todoist_access_token"})
        return _err("VALIDATION_ERROR", "todoist_access_token is required.", field="todoist_access_token")

    token = todoist_access_token.strip()

    # Authenticate against any credential store present in DB. Since schema doesn't define it,
    # search known filenames and field patterns.
    credential_row = None
    cred_source = None

    for fname in (
        "credentials.json",
        "todoist_credentials.json",
        "api_keys.json",
        "access_tokens.json",
        "tokens.json",
        "auth.json",
        "users.json",
        "accounts.json",
        "workspaces.json",
    ):
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            continue
        rows = _load(fname)
        if not isinstance(rows, list):
            continue
        for r in rows:
            if not isinstance(r, dict):
                continue
            # match either id or client-visible token fields
            for k in ("todoist_access_token", "access_token", "token", "api_key", "key", "value", "secret", "id"):
                v = r.get(k)
                if isinstance(v, str) and v == token:
                    credential_row = r
                    cred_source = fname
                    break
            if credential_row is not None:
                break
        if credential_row is not None:
            break

    if credential_row is None:
        _append_log("UNAUTHORIZED", credential=token)
        return _err("UNAUTHORIZED", "Invalid or unknown todoist_access_token.")

    # Build an identity response using whatever fields exist.
    # Do not fabricate data; only surface what is stored.
    identity = {
        "credential": {
            "source": cred_source,
            "id": credential_row.get("id"),
        },
        "subject": {},
        "entitlements": {},
        "rate_limit": {},
        "quota": {}
    }

    # Common user-like fields
    for k in ("user_id", "account_id", "workspace_id", "email", "name", "username"):
        if k in credential_row:
            identity["subject"][k] = credential_row.get(k)

    # Common scopes/permissions fields
    for k in ("scopes", "scope", "permissions", "entitlements", "plan", "role"):
        if k in credential_row:
            identity["entitlements"][k] = credential_row.get(k)

    # Snapshot current rate/quota consumption if request logs exist
    # We can only compute basic counts in time windows; if no logs, return empty objects.
    log_rows = None
    log_file = None
    for fname in ("request_log.json", "requests.json", "audit_log.json", "usage.json"):
        path = os.path.join(_DB, fname)
        if os.path.exists(path):
            lr = _load(fname)
            if isinstance(lr, list):
                log_rows = lr
                log_file = fname
                break

    if log_rows is not None:
        # Compute last 60s and last 24h counts for this credential token
        # Only counts entries with matching credential exactly.
        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                # Accept ISO8601 with Z
                if s.endswith("Z"):
                    s2 = s[:-1]
                else:
                    s2 = s
                return datetime.datetime.fromisoformat(s2)
            except Exception:
                return None

        now_dt = _parse_ts(now) or datetime.datetime.utcnow()
        c_60 = 0
        c_86400 = 0
        for e in log_rows:
            if not isinstance(e, dict):
                continue
            if e.get("credential") != token:
                continue
            ts = _parse_ts(e.get("timestamp"))
            if ts is None:
                continue
            delta = (now_dt - ts).total_seconds()
            if 0 <= delta <= 60:
                c_60 += 1
            if 0 <= delta <= 86400:
                c_86400 += 1

        identity["rate_limit"] = {
            "log_source": log_file,
            "requests_last_60s": c_60
        }
        identity["quota"] = {
            "log_source": log_file,
            "requests_last_24h": c_86400
        }

    _append_log("OK", credential=token, meta={"credential_source": cred_source})
    return {"whoami": identity}
